DECLARATIONS.update({'choose_special_message_for_action_fields': {'signature': 'state: SceneState',
                                              'returns': 'SpecialMessageSelectorFields',
                                              'flow': 'checked_state(state)\n'
                                                      'value = u16(17)\n'
                                                      'operand_address_1 = 4294964102\n'
                                                      'read_value_2 = '
                                                      'state.read(operand_address_1, 2)\n'
                                                      'comparison_left = u16(read_value_2)\n'
                                                      'comparison_right = u16(0)\n'
                                                      'tested_value = u16(comparison_left - '
                                                      'comparison_right)\n'
                                                      'value_is_zero = tested_value == 0\n'
                                                      'value_is_negative = bool(tested_value & '
                                                      '32768)\n'
                                                      'arithmetic_carry = comparison_left < '
                                                      'comparison_right\n'
                                                      'arithmetic_overflow = bool((comparison_left '
                                                      '^ comparison_right) & (comparison_left ^ '
                                                      'u16(comparison_left - comparison_right)) & '
                                                      '32768)\n'
                                                      'if not value_is_zero:\n'
                                                      '    value = u16(18)\n'
                                                      '    tested_value = u16(18)\n'
                                                      '    value_is_zero = tested_value == 0\n'
                                                      '    value_is_negative = bool(tested_value & '
                                                      '32768)\n'
                                                      '    arithmetic_carry = False\n'
                                                      '    arithmetic_overflow = False\n'
                                                      'return SpecialMessageSelectorFields(value, '
                                                      'None, None, None, arithmetic_carry, '
                                                      'value_is_zero, value_is_negative, '
                                                      'arithmetic_overflow).validate(state)'},
 'enter_special_message_mode_fields': {'signature': 'state: SceneState',
                                       'returns': 'SpecialMessageSelectorFields',
                                       'flow': 'checked_state(state)\n'
                                               'destination = state.table_at(u32(423892))\n'
                                               'call_result_1 = '
                                               'lookup_special_message_for_selection_fields(state, '
                                               'destination)\n'
                                               'destination = '
                                               'call_result_1.destination_if_written\n'
                                               'value = call_result_1.value\n'
                                               'field = call_result_1.field_if_written\n'
                                               'tile = call_result_1.tile_if_written\n'
                                               'arithmetic_carry = call_result_1.carry\n'
                                               'value_is_zero = call_result_1.zero\n'
                                               'value_is_negative = call_result_1.negative\n'
                                               'arithmetic_overflow = call_result_1.overflow\n'
                                               'read_value_2 = state.read(4294964754, 2)\n'
                                               'state.write(4294964186, 2, u16(read_value_2))\n'
                                               'read_value_3 = state.read(4294964066, 2)\n'
                                               'state.write(4294964188, 2, u16(read_value_3))\n'
                                               'state.write(4294964754, 2, u16(520))\n'
                                               'state.write(4294964066, 2, u16(22))\n'
                                               'tested_value = u16(22)\n'
                                               'value_is_zero = tested_value == 0\n'
                                               'value_is_negative = bool(tested_value & 32768)\n'
                                               'arithmetic_carry = False\n'
                                               'arithmetic_overflow = False\n'
                                               'return SpecialMessageSelectorFields(value, field, '
                                               'tile, destination, arithmetic_carry, '
                                               'value_is_zero, value_is_negative, '
                                               'arithmetic_overflow).validate(state)'},
 'fixed_special_message_fields': {'signature': 'state: SceneState',
                                  'returns': 'SpecialMessageSelectorFields',
                                  'flow': 'checked_state(state)\n'
                                          'value = u16(16)\n'
                                          'tested_value = u16(16)\n'
                                          'value_is_zero = tested_value == 0\n'
                                          'value_is_negative = bool(tested_value & 32768)\n'
                                          'arithmetic_carry = False\n'
                                          'arithmetic_overflow = False\n'
                                          'return SpecialMessageSelectorFields(value, None, None, '
                                          'None, arithmetic_carry, value_is_zero, '
                                          'value_is_negative, '
                                          'arithmetic_overflow).validate(state)'},
 'lookup_special_message_for_selection_fields': {'signature': 'state: SceneState, destination: '
                                                              'Table',
                                                 'returns': 'SpecialMessageSelectorFields',
                                                 'flow': 'checked_state(state)\n'
                                                         'checked_table(destination, state)\n'
                                                         'read_value_1 = state.read(4294964108, '
                                                         '2)\n'
                                                         'field = u16(read_value_1)\n'
                                                         'while True:\n'
                                                         '    read_value_2 = '
                                                         'state.read(u32(destination.base + 0), '
                                                         '2)\n'
                                                         '    destination = '
                                                         'destination.advance(2)\n'
                                                         '    tile = u16(read_value_2)\n'
                                                         '    tested_value = u16(read_value_2)\n'
                                                         '    value_is_zero = tested_value == 0\n'
                                                         '    value_is_negative = '
                                                         'bool(tested_value & 32768)\n'
                                                         '    arithmetic_carry = False\n'
                                                         '    arithmetic_overflow = False\n'
                                                         '    if value_is_negative:\n'
                                                         '        break\n'
                                                         '    comparison_left = u16(field)\n'
                                                         '    comparison_right = u16(tile)\n'
                                                         '    tested_value = u16(comparison_left - '
                                                         'comparison_right)\n'
                                                         '    value_is_zero = tested_value == 0\n'
                                                         '    value_is_negative = '
                                                         'bool(tested_value & 32768)\n'
                                                         '    arithmetic_carry = comparison_left < '
                                                         'comparison_right\n'
                                                         '    arithmetic_overflow = '
                                                         'bool((comparison_left ^ '
                                                         'comparison_right) & (comparison_left ^ '
                                                         'u16(comparison_left - comparison_right)) '
                                                         '& 32768)\n'
                                                         '    if value_is_zero:\n'
                                                         '        break\n'
                                                         '    destination = '
                                                         'state.table_at(u32(u32(destination.base '
                                                         '+ 2)))\n'
                                                         '    continue\n'
                                                         'read_value_3 = '
                                                         'state.read(u32(destination.base + 0), '
                                                         '2)\n'
                                                         'value = u16(read_value_3)\n'
                                                         'tested_value = u16(read_value_3)\n'
                                                         'value_is_zero = tested_value == 0\n'
                                                         'value_is_negative = bool(tested_value & '
                                                         '32768)\n'
                                                         'arithmetic_carry = False\n'
                                                         'arithmetic_overflow = False\n'
                                                         'return '
                                                         'SpecialMessageSelectorFields(value, '
                                                         'field, tile, destination, '
                                                         'arithmetic_carry, value_is_zero, '
                                                         'value_is_negative, '
                                                         'arithmetic_overflow).validate(state)'}})


APPROVED.setdefault('domain', set()).update({'Table', 'checked_table'})
