def compile_source(source, *, selected_names=None):
    records = semantic_functions(source, DECLARATIONS, APPROVED)
    officer_fields = {name: records[name]['effects'] for name in ('_officer_outcome_call_fields', '_officer_outcome_seek_fields', 'remove_officer_from_active_or_retired_fields', 'remove_officer_from_selected_active_fields', 'read_officer_influence_pair_fields', '_officer_influence_ratio_fields', 'decrease_removed_officer_influence_fields', 'increase_returned_officer_influence_fields', 'increase_retired_officer_influence_fields', '_append_officer_outcome_destination_fields', '_prepare_officer_outcome_message_fields', 'return_selected_officer_to_outcome_fields', 'retire_selected_officer_to_outcome_fields')}
    for owner in ('highbank_select_live_state_8', 'highbank_select_live_state_9', 'highbank_calculate_live_quotient_1', 'highbank_select_live_state_10', 'highbank_update_record_flags_2', 'highbank_calculate_live_quotient_2', 'highbank_coordinate_live_state_12', 'highbank_calculate_live_quotient_3'):
        records[owner]['effects'] = dict(legacy_projection=records[owner]['effects'], sole_officer_outcomes=officer_fields)
    for owner in ('highbank_coordinate_live_state_90', 'highbank_coordinate_live_state_91'):
        records[owner]['effects'] = dict(legacy_projection=records[owner]['effects'], supplied_unique_ranked_fields=records['execute_ranked_standard_action_fields']['effects'])
    records['highbank_coordinate_live_state_86']['effects'] = dict(legacy_projection=records['highbank_coordinate_live_state_86']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('_attribute_order_compare', '_attribute_order_call_fields', 'evaluate_second_side_attribute_order_fields')})
