    records['highbank_select_live_state_43']['effects'] = dict(legacy_projection=records['highbank_select_live_state_43']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('lookup_special_message_for_selection_fields',)})
    records['highbank_coordinate_live_state_178']['effects'] = dict(legacy_projection=records['highbank_coordinate_live_state_178']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('enter_special_message_mode_fields',)})
    records['highbank_update_live_fields_18']['effects'] = dict(legacy_projection=records['highbank_update_live_fields_18']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('fixed_special_message_fields',)})
    records['highbank_select_live_state_44']['effects'] = dict(legacy_projection=records['highbank_select_live_state_44']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('choose_special_message_for_action_fields',)})
    records['highbank_process_counted_records_10']['effects'] = dict(legacy_projection=records['highbank_process_counted_records_10']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('_retreat_policy_move', '_retreat_policy_compare', '_retreat_policy_carry', 'find_other_owned_city_fields')})
    records['highbank_coordinate_live_state_51']['effects'] = dict(legacy_projection=records['highbank_coordinate_live_state_51']['effects'], supplied_unique_fields={name: records[name]['effects'] for name in ('_retreat_policy_move', '_retreat_policy_compare', '_retreat_policy_shift', '_retreat_policy_carry', 'find_other_owned_city_fields', '_retreat_policy_random', '_retreat_policy_call', '_retreat_policy_modal', 'evaluate_other_city_retreat_order_fields', '_standard_order_enter', '_standard_order_leave')})
