DECLARATIONS.update({'highbank_coordinate_live_state_85': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState85Input', 'returns': 'HighbankCoordinateLiveState85Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState85Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, offset_x=inputs.limit, choice=inputs.remaining, roster=inputs.destination.cursor(), stack_cursor=inputs.stack_cursor)\nfields = execute_standard_action_chain_fields(state, frame)\nresult, flags = (fields.frame, fields.conditions)\nreturn HighbankCoordinateLiveState85Result(destination=state.table_at(result.roster.base), value=result.target_x, field=result.target_y, remaining=result.choice, carry=bool(flags & 1), zero=bool(flags & 4), negative=bool(flags & 8), overflow=bool(flags & 2)).validate(state)"}})

DECLARATIONS.update({'evaluate_secondary_standard_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current fields and actual completeness selector required')\nframe.validate(state, complete)\nfor carrier in (frame.target_x, frame.target_y, frame.unit, frame.choice):\n    uint(carrier, 32)\nrank_table = state.table_at(4294948352).cursor()\nactor = low16(frame.choice)\noffset = u16(actor << 1)\nstatus = (17 if actor & 32768 else 0) | (8 if offset & 32768 else 0) | (4 if offset == 0 else 0)\nframe = first_replace(frame, target_x=replace_word(frame.target_x, offset), roster=rank_table, status=status)\nrank = rank_table.word(offset)\nframe = first_replace(frame, target_y=replace_word(frame.target_y, rank), unit=replace_word(frame.unit, 1), status=frame.status & 16)\nframe = _standard_order_compare(frame, rank, 60)\nif rank >= 60:\n    frame = _standard_order_increment(frame, 'unit')\n    frame = _standard_order_compare(frame, rank, 80)\n    if rank >= 80:\n        frame = _standard_order_increment(frame, 'target_y')\n        frame = _standard_order_compare(frame, low16(frame.target_y), 100)\n        if low16(frame.target_y) >= 100:\n            frame = _standard_order_increment(frame, 'target_y')\nentered = _standard_order_enter(frame, 145176)\nfrom .services import sample_random_pair\nrandom = sample_random_pair(state)\nextend = low16(random.sample) < low16(random.updated_state)\nrandom_status = (16 if extend else 0) | (8 if random.updated_state & 2147483648 else 0) | (4 if random.updated_state == 0 else 0)\nframe = _standard_order_leave(first_replace(entered, target_x=random.sample, target_y=random.updated_state, status=random_status), 145176)\nsample = random.sample & 65535\nshifted = u32(sample << 2)\nscaled = swap_words(shifted)\nframe = first_replace(frame, target_x=scaled, status=(8 if scaled & 2147483648 else 0) | (4 if scaled == 0 else 0))\nthreshold = low16(frame.unit)\nframe = _standard_order_compare(frame, low16(scaled), threshold)\nif low16(scaled) >= threshold:\n    if not state.sr & 8192:\n        raise Boundary('standard-order original full-SR operation requires supervisor')\n    if state.sr & 32768:\n        raise Boundary('standard-order trace continuation unmodeled')\n    frame = first_replace(frame, status=frame.status & 30)\n    state.set_status_word(state.sr & 65504 | frame.status)\n    return frame.validate(state, complete)\nentered = _standard_order_enter(frame, 145196)\nstate.sr = state.sr & 65504 | entered.status\nif not complete:\n    highbank_coordinate_live_state_85(state, HighbankCoordinateLiveState85Input(destination=state.table_at(entered.roster.base), value=entered.target_x, field=entered.target_y, tile=entered.unit, limit=entered.offset_x, remaining=entered.choice, stack_cursor=entered.stack_cursor, carry=bool(entered.status & 1), zero=bool(entered.status & 4), negative=bool(entered.status & 8), overflow=bool(entered.status & 2)))\n    raise Boundary('legacy 26560 return does not observe actual SP or full fields')\nresult = execute_standard_action_chain_fields(state, entered, True).validate(state, True).frame\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('26560 must return the actual current sole deployment fields')\nresult.validate(state, True)\nreturn _standard_order_leave(result, 145196).validate(state, True)"}})

DECLARATIONS.update({'_standard_action_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "entered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nresult = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('action callee must return actual current sole deployment fields')\nresult.validate(state, complete)\nreturn _standard_order_leave(result, continuation).validate(state, complete)"}})

DECLARATIONS.update({'execute_standard_action_chain_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current action fields and actual observation selector required')\nframe.validate(state, complete)\nuint(frame.choice, 32)\nif frame.stack_cursor is None:\n    raise Boundary('action chain requires actual current callee-entry A7')\nactor = low16(frame.choice)\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, actor)\nflags = (8 if actor & 32768 else 0) | (4 if actor == 0 else 0)\nframe = first_replace(frame, stack_cursor=stack, status=None if frame.status is None else frame.status & 16 | flags)\nframe = _standard_action_call_fields(state, frame, 144594, 157030, complete)\ncandidate = state.read(4294955776, 2)\nflags = (8 if candidate & 32768 else 0) | (4 if candidate == 0 else 0)\nframe = first_replace(frame, status=None if frame.status is None else frame.status & 16 | flags)\nselected = False\nif not candidate & 32768:\n    for target, continuation in ((157104, 157042), (157400, 157050), (157660, 157058), (157944, 157066), (158118, 157074), (158380, 157082)):\n        frame = _standard_action_call_fields(state, frame, target, continuation, complete)\n        if frame.status is None:\n            raise Boundary('action attempt has not observed its actual returned carry')\n        if frame.status & 1:\n            selected = True\n            break\nstack = frame.stack_cursor\nrestored_actor = stack.next_word()\nframe = first_replace(frame, choice=replace_word(frame.choice, restored_actor), stack_cursor=stack, status=None if frame.status is None else frame.status & 16 | (8 if restored_actor & 32768 else 0) | (4 if restored_actor == 0 else 0))\nflags = (8 if restored_actor & 32768 else 0) | (4 if restored_actor == 0 else 0)\nreturn _position_order_carry(state, frame, flags, selected).validate(state, complete)"}})

DECLARATIONS.update({'_standard_action_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "entered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif target == 144594:\n    from .services import BattlePolicyMemory, collect_contacts_in_speed_radius_fields\n    result = collect_contacts_in_speed_radius_fields(BattlePolicyMemory(state), entered).frame\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('action callee must return actual current sole deployment fields')\nresult.validate(state, complete)\nreturn _standard_order_leave(result, continuation).validate(state, complete)"}})

