DECLARATIONS.update({'_retreat_policy_carry': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, enabled: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(enabled) is not bool or frame.status is None:\n    raise ValueError('actual known retreat flags and carry required')\nstatus = frame.status & 30 | int(enabled)\nstate.set_status_word(state.sr & 65504 | status)\nreturn first_replace(frame, status=status)"}})


