DECLARATIONS.update({'_retreat_policy_random': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'entered = _standard_order_enter(frame, 141210)\nfrom .services import sample_random_pair\nrandom = sample_random_pair(state)\nextend = low16(random.sample) < low16(random.updated_state)\nstatus = (16 if extend else 0) | (8 if random.updated_state & 2147483648 else 0) | (4 if random.updated_state == 0 else 0)\nstate.sr = state.sr & 65504 | status\nresult = first_replace(entered, target_x=random.sample, target_y=random.updated_state, status=status)\nreturn _standard_order_leave(result, 141210)'}})


