DECLARATIONS.update({'_retreat_policy_call': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool, legacy_kind', 'returns': 'FirstDeploymentFrame', 'flow': "if type(complete) is not bool or legacy_kind not in (HighbankCoordinateLiveState51Service1, HighbankCoordinateLiveState51Service2, HighbankCoordinateLiveState51Service3, HighbankCoordinateLiveState51Service4, HighbankCoordinateLiveState51Service5, HighbankCoordinateLiveState51Service6):\n    raise ValueError('one existing retreat child contract required')\nentered = _standard_order_enter(frame, continuation)\nstate.sr = state.sr & 65504 | entered.status\nif not complete:\n    context = legacy_kind(destination=state.table_at(entered.roster.base), descriptor=state.table_at(entered.controller.base), value=entered.target_x, field=entered.target_y, row=entered.count, offset=entered.distance, remaining=entered.choice)\n    call_target(state, target, context)\n    raise Boundary('legacy retreat child return lacks actual full fields and SP')\nresult = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('retreat child requires all actual full fields and SP')\nresult.validate(state, True)\nstate.sr = state.sr & 65504 | result.status\nreturn _standard_order_leave(result, continuation)"}})


