DECLARATIONS.update({'_retreat_policy_modal': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool, middle_band: bool', 'returns': 'FirstDeploymentFrame', 'flow': "saved = low16(frame.choice)\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, saved)\nframe = _retreat_policy_move(state, first_replace(frame, stack_cursor=stack), 'choice', saved)\nframe = _retreat_policy_call(state, frame, 97418, 141234, complete, HighbankCoordinateLiveState51Service4 if middle_band else HighbankCoordinateLiveState51Service1)\nrestored = frame.stack_cursor.word()\nframe = _retreat_policy_move(state, first_replace(frame, stack_cursor=frame.stack_cursor.advance(2)), 'choice', restored)\nselected = state.read(4294964972, 2)\nconditions = (8 if selected & 32768 else 0) | (4 if selected == 0 else 0)\nframe = first_replace(frame, status=frame.status & 16 | conditions)\nstate.sr = state.sr & 65504 | frame.status\nif selected & 32768:\n    return _retreat_policy_carry(state, frame, False)\nvalue = low16(frame.choice)\nframe = _retreat_policy_move(state, frame, 'choice', value)\nstate.write(4294964134, 2, value)\nframe = _retreat_policy_call(state, frame, 98096, 141252, complete, HighbankCoordinateLiveState51Service5 if middle_band else HighbankCoordinateLiveState51Service2)\nvalue = state.read(4294964134, 2)\nconditions = (8 if value & 32768 else 0) | (4 if value == 0 else 0)\nframe = first_replace(frame, status=frame.status & 16 | conditions)\nstate.sr = state.sr & 65504 | frame.status\nstate.write(4294964178, 2, value)\nstate.write(4294965056, 2, 302)\nframe = first_replace(frame, status=frame.status & 16)\nstate.sr = state.sr & 65504 | frame.status\nflag = state.read(4294964951, 1)\nframe = first_replace(frame, status=frame.status & 27 | (0 if flag & 2 else 4))\nstate.sr = state.sr & 65504 | frame.status\nstate.write(4294964951, 1, flag ^ 2)\nframe = _retreat_policy_call(state, frame, 155876, 141276, complete, HighbankCoordinateLiveState51Service6 if middle_band else HighbankCoordinateLiveState51Service3)\nflag = state.read(4294964951, 1)\nframe = first_replace(frame, status=frame.status & 27 | (0 if flag & 2 else 4))\nstate.sr = state.sr & 65504 | frame.status\nstate.write(4294964951, 1, flag ^ 2)\nreturn _retreat_policy_carry(state, frame, True)"}})


