DECLARATIONS.update({'evaluate_other_city_retreat_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole retreat fields and actual completeness required')\nframe.validate(state, complete)\nfor carrier in (frame.target_x, frame.target_y, frame.count, frame.distance, frame.choice):\n    uint(carrier, 32)\nif frame.stack_cursor is None:\n    raise Boundary('22756 requires actual current callee-entry SP')\nentered = _standard_order_enter(frame, 141144)\nframe = find_other_owned_city_fields(state, entered, complete)\nframe = _standard_order_leave(frame, 141144)\nif not frame.status & 1:\n    return _retreat_policy_carry(state, frame, False).validate(state, complete)\nframe = _retreat_policy_move(state, frame, 'target_x', low16(frame.choice))\nframe = _retreat_policy_shift(state, frame, 'target_x', 2)\noffset = low16(frame.target_x)\ntroops = state.table_at(4294952960)\nframe = first_replace(frame, controller=troops)\nstrength = troops.long(offset)\nframe = _retreat_policy_compare(state, frame, strength, 200, 32)\nmiddle_band = strength > 200\nif middle_band:\n    strength = troops.long(offset)\n    frame = _retreat_policy_compare(state, frame, strength, 500, 32)\n    if strength > 500:\n        return _retreat_policy_carry(state, frame, False).validate(state, complete)\n    frame = _retreat_policy_shift(state, frame, 'target_x', 1, True)\n    skills = state.table_at(4294946816)\n    frame = first_replace(frame, controller=skills)\n    frame = _retreat_policy_move(state, frame, 'target_y', skills.word(low16(frame.target_x)))\n    frame = _retreat_policy_shift(state, frame, 'target_y', 2, True)\n    aptitudes = state.table_at(4294947328)\n    frame = first_replace(frame, controller=aptitudes)\n    aptitude = aptitudes.word(low16(frame.target_x))\n    frame = _retreat_policy_compare(state, frame, low16(frame.target_y), aptitude, 16)\n    if low16(frame.target_y) < aptitude:\n        return _retreat_policy_carry(state, frame, False).validate(state, complete)\nframe = _retreat_policy_random(state, frame)\nstatus = frame.status & 27 | (0 if frame.target_x & 1 else 4)\nstate.sr = state.sr & 65504 | status\nframe = first_replace(frame, status=status)\nif not frame.target_x & 1:\n    return _retreat_policy_carry(state, frame, False).validate(state, complete)\nreturn _retreat_policy_modal(state, frame, complete, middle_band).validate(state, complete)"}})


# Current whole retreat-child dispatch: actual preexisting JSR slot retained.
DECLARATIONS.update({'_retreat_policy_call': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool, legacy_kind', 'returns': 'FirstDeploymentFrame', 'flow': "if type(complete) is not bool or legacy_kind not in (HighbankCoordinateLiveState51Service1, HighbankCoordinateLiveState51Service2, HighbankCoordinateLiveState51Service3, HighbankCoordinateLiveState51Service4, HighbankCoordinateLiveState51Service5, HighbankCoordinateLiveState51Service6):\n    raise ValueError('one existing retreat child contract required')\nentered = _standard_order_enter(frame, continuation)\nstate.sr = state.sr & 65504 | entered.status\nif not complete:\n    context = legacy_kind(destination=state.table_at(entered.roster.base), descriptor=state.table_at(entered.controller.base), value=entered.target_x, field=entered.target_y, row=entered.count, offset=entered.distance, remaining=entered.choice)\n    call_target(state, target, context)\n    raise Boundary('legacy retreat child return lacks actual full fields and SP')\nif target == 97418:\n    from .services import ensure_neighbor_capacity_fields\n    result = ensure_neighbor_capacity_fields(state, entered)\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('retreat child requires all actual full fields and SP')\nresult.validate(state, True)\nstate.sr = state.sr & 65504 | result.status\nreturn _standard_order_leave(result, continuation)"}})
