DECLARATIONS.update({'highbank_coordinate_live_state_87': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState87Input', 'returns': 'HighbankCoordinateLiveState87Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState87Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), unit=inputs.tile, offset_x=inputs.limit, choice=inputs.remaining, roster=inputs.destination.cursor())\nfields = execute_type6_standard_action_fields(state, frame, False).validate(state)\nframe = fields.frame\nflags = fields.conditions\nreturn HighbankCoordinateLiveState87Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, carry=bool(flags & 1), zero=bool(flags & 4), negative=bool(flags & 8), overflow=bool(flags & 2)).validate(state)"}})

DECLARATIONS.update({'_standard_action_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "entered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif target == 144594:\n    from .services import BattlePolicyMemory, collect_contacts_in_speed_radius_fields\n    result = collect_contacts_in_speed_radius_fields(BattlePolicyMemory(state), entered).frame\nelif target == 157400:\n    result = execute_type6_standard_action_fields(state, entered, complete).frame\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('action callee must return actual current sole deployment fields')\nresult.validate(state, complete)\nreturn _standard_order_leave(result, continuation).validate(state, complete)"}})

DECLARATIONS.update({'execute_type6_standard_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('current action fields and actual completeness selector required')\nframe.validate(state, complete)\nfrom .services import BattlePolicyMemory, sample_battle_action_random_fields, select_strongest_type6_candidate_fields, compute_type6_budget_from_random_state_fields\nmemory = BattlePolicyMemory(state)\nframe = sample_battle_action_random_fields(memory, frame, 157406)\nvalue = frame.target_x & 65535\nframe = first_replace(frame, target_x=value, status=frame.status & 16 | (4 if value == 0 else 0))\nvalue = u32(value << 2)\nframe = first_replace(frame, target_x=value, status=(8 if value & 2147483648 else 0) | (4 if value == 0 else 0))\nvalue = swap_words(value)\nframe = first_replace(frame, target_x=value, status=(8 if value & 2147483648 else 0) | (4 if value == 0 else 0))\nframe = _standard_order_compare(frame, low16(value), 3)\nif low16(value) == 3:\n    return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)\nentered = _standard_order_enter(frame, 157428) if frame.stack_cursor is not None else frame\nframe = select_strongest_type6_candidate_fields(memory, entered)\nif frame.stack_cursor is not None:\n    frame = _standard_order_leave(frame, 157428)\nuint(frame.offset_x, 32)\nselected = low16(frame.offset_x)\nframe = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))\nif selected & 32768:\n    return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)\nstate.write(4294964134, 2, selected)\nframe = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))\nentered = _standard_order_enter(frame, 157442) if frame.stack_cursor is not None else frame\nframe = compute_type6_budget_from_random_state_fields(memory, entered)\nif frame.stack_cursor is not None:\n    frame = _standard_order_leave(frame, 157442)\nceiling = state.read(4294964886, 4)\nleft = frame.unit\ncompared = u32(left - ceiling)\nflags = (1 if left < ceiling else 0) | (8 if compared & 2147483648 else 0) | (4 if compared == 0 else 0) | (2 if (left ^ ceiling) & (left ^ compared) & 2147483648 else 0)\nframe = first_replace(frame, status=frame.status & 16 | flags)\nif left > ceiling:\n    return _position_order_carry(state, frame, flags, False).validate(state, complete)\norders = state.table_at(4294944596).cursor()\nframe = first_replace(frame, roster=orders)\nuint(frame.choice, 32)\nactor = low16(frame.choice)\norders.set_byte(actor, 3)\nframe = first_replace(frame, status=frame.status & 16)\nstate.write(4294964210, 2, actor)\nframe = first_replace(frame, status=frame.status & 16 | (8 if actor & 32768 else 0) | (4 if actor == 0 else 0))\nstate.write(4294964948, 2, 3)\nframe = first_replace(frame, status=frame.status & 16)\nframe = _standard_action_call_fields(state, frame, 107642, 157476, complete)\nif frame.status is None:\n    raise Boundary('actual battle presentation carry has not been observed')\nif not frame.status & 1:\n    side = state.read(4294964951, 1)\n    state.write(4294964951, 1, side ^ 2)\n    frame = first_replace(frame, status=frame.status & 27 | (0 if side & 2 else 4))\n    selected = state.read(4294964134, 2)\n    state.write(4294964176, 2, selected)\n    frame = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))\n    state.write(4294965056, 2, 299)\n    frame = first_replace(frame, status=frame.status & 16)\n    frame = _standard_action_call_fields(state, frame, 155876, 157502, complete)\n    if frame.status is None:\n        raise Boundary('actual battle message fields have not returned')\n    side = state.read(4294964951, 1)\n    state.write(4294964951, 1, side ^ 2)\n    frame = first_replace(frame, status=frame.status & 27 | (0 if side & 2 else 4))\nreturn _position_order_carry(state, frame, frame.status & 15, True).validate(state, complete)"}})

