DECLARATIONS.update({'_standard_action_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "entered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif target == 144594:\n    from .services import BattlePolicyMemory, collect_contacts_in_speed_radius_fields\n    result = collect_contacts_in_speed_radius_fields(BattlePolicyMemory(state), entered).frame\nelif target == 157400:\n    result = execute_type6_standard_action_fields(state, entered, complete).frame\nelif target == 157104:\n    result = evaluate_second_side_attribute_order_fields(state, entered, complete)\nelif target == 157660:\n    result = execute_open_terrain_standard_action_fields(state, entered, complete).frame\nelif target == 157944:\n    result = execute_second_open_standard_action_fields(state, entered, complete).frame\nelif target == 158118:\n    result = execute_ranked_standard_action_fields(state, entered, 1, complete).frame\nelif target == 158380:\n    result = execute_ranked_standard_action_fields(state, entered, 4, complete).frame\nelif target == 155876 and complete:\n    from .services import present_battle_message_fields\n    result = present_battle_message_fields(state, entered)\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('action callee must return actual current sole deployment fields')\nresult.validate(state, complete)\nreturn _standard_order_leave(result, continuation).validate(state, complete)"}})

DECLARATIONS.update({'highbank_coordinate_live_state_73': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState73Input', 'returns': 'HighbankCoordinateLiveState73Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState73Input:\n    raise ValueError('function-specific actual position input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, candidates=inputs.source.cursor(), scratch=inputs.roster.cursor(), stack_cursor=inputs.stack_cursor)\nresult = evaluate_contact_position_order_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState73Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

