DECLARATIONS.update({'highbank_coordinate_live_state_78': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState78Input', 'returns': 'HighbankCoordinateLiveState78Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState78Input:\n    raise ValueError('function-specific actual position input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, offset_x=inputs.limit, choice=inputs.remaining, stack_cursor=inputs.stack_cursor)\nresult = evaluate_nearest_anchor_contact_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState78Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'highbank_coordinate_live_state_77_alternate_1': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState77Alternate1Input', 'returns': 'HighbankCoordinateLiveState77Alternate1Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState77Alternate1Input:\n    raise ValueError('function-specific actual position input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, candidates=inputs.source.cursor(), scratch=inputs.roster.cursor(), stack_cursor=inputs.stack_cursor)\nresult = evaluate_alternate_anchor_position_order_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState77Alternate1Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'_position_strategy_status': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, value, width: int, carry: bool=False, overflow: bool=False, extend: bool | None=None', 'returns': 'FirstDeploymentFrame', 'flow': 'from ..high_level_battle_ai.business_geometry import _contact_status\nframe = _contact_status(frame, value, width, carry, overflow, extend)\nflags = int(carry) | (2 if overflow else 0) | (4 if value == 0 else 0) | (8 if value & 1 << width - 1 else 0)\nstate.sr = state.sr & 65520 | flags if frame.status is None else state.sr & 65504 | frame.status\nreturn frame'}})

DECLARATIONS.update({'_position_strategy_move': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, name, value, width: int=16', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _position_order_move(frame, name, value, width)\nreturn _position_strategy_status(state, frame, value, width)'}})

DECLARATIONS.update({'_position_strategy_done': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool', 'returns': 'StandardPositionOrderFields', 'flow': 'if frame.status is not None:\n    state.sr = state.sr & 65504 | frame.status\nreturn StandardPositionOrderFields(frame, state.sr & 15).validate(state, complete)'}})

DECLARATIONS.update({'_position_strategy_actor_gate': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'tuple', 'flow': "actor = low16(frame.choice)\nfor address, name in ((4294944340, 'roster'), (16727234, 'roster'), (16727490, 'candidates')):\n    view = state.table_at(address).cursor()\n    frame = first_replace(frame, **{name: view})\n    active = view.byte(actor)\n    frame = _position_strategy_status(state, frame, active, 8)\n    if active != 0:\n        return (frame, False)\nreturn (frame, True)"}})

DECLARATIONS.update({'_position_strategy_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import BattlePolicyMemory\nfrom ..high_level_battle_ai.business_geometry import collect_contacts_in_speed_radius_fields\nfrom ..high_level_battle_ai.business_formation import compare_actor_shifted_troop_word_to_weakest_contact_fields, read_outer_east_staging_anchor_fields, select_contact_nearest_deployment_anchor_fields, read_formation_relative_position_delta_fields, first_deployment_random_fields, test_point_in_battlefield_staging_rectangle_fields, sample_battlefield_staging_rectangle_fields\nentered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif not complete and any((value is None for value in (entered.target_x, entered.target_y, entered.unit, entered.count, entered.distance, entered.offset_x, entered.offset_y, entered.choice, entered.status))):\n    raise Boundary('old position API lacks an actual child CCR or retained carrier; real return slot is already written')\nmemory = BattlePolicyMemory(state)\nif target == 144594:\n    result = collect_contacts_in_speed_radius_fields(memory, entered).frame\nelif target == 148384:\n    result = compare_actor_shifted_troop_word_to_weakest_contact_fields(memory, entered)[0]\nelif target == 148444:\n    result = evaluate_selected_contact_position_fields(state, entered, complete).frame\nelif target == 148542:\n    result = read_outer_east_staging_anchor_fields(memory, entered)[0]\nelif target == 149714:\n    result = evaluate_nearest_anchor_contact_fields(state, entered, complete).frame\nelif target == 149798:\n    result = select_contact_nearest_deployment_anchor_fields(memory, entered)[0]\nelif target == 149904:\n    result = read_formation_relative_position_delta_fields(memory, entered)[0]\nelif target == 146184:\n    result = test_point_in_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 146342:\n    result = sample_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 33748:\n    result = first_deployment_random_fields(memory, entered)\nelif target == 157024:\n    result = execute_standard_action_chain_fields(state, entered, complete).frame\nelif target == 122026:\n    from .business_city import city_calculate_live_quotient_10_fields\n    result = city_calculate_live_quotient_10_fields(memory, entered)\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('position child requires its actual current retained fields')\nresult.validate(state, complete)\nreturned = _standard_order_leave(result, continuation)\nif returned.status is not None:\n    state.sr = state.sr & 65504 | returned.status\nreturn returned"}})

DECLARATIONS.update({'_commit_contact_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, vertical, continuation, complete: bool', 'returns': 'StandardPositionOrderFields', 'flow': "targets = state.table_at(16722944).cursor()\nframe = first_replace(frame, roster=targets)\nframe = _position_strategy_move(state, frame, 'target_y', low16(frame.choice))\nframe = _position_order_shift(frame, 'target_y', 2)\noffset = low16(frame.target_y)\nframe = _position_order_shift(frame, 'unit', 7, True)\ntargets.set_word(offset, low16(frame.unit))\nframe = _position_strategy_status(state, frame, low16(frame.unit), 16)\nframe = _position_order_shift(frame, vertical, 7, True)\ntargets.set_word(offset, low16(frame.carrier(vertical)), 2)\nframe = _position_strategy_status(state, frame, low16(frame.carrier(vertical)), 16)\nsubmitted = state.table_at(4294946344).cursor()\nframe = first_replace(frame, roster=submitted)\nsubmitted.set_byte(low16(frame.choice), 1)\nframe = _position_strategy_status(state, frame, 1, 8)\nframe = _position_strategy_call_fields(state, frame, 122026, continuation, complete)\nreturn _position_strategy_done(state, frame, complete)"}})

DECLARATIONS.update({'evaluate_contact_position_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('actual position fields and completeness selector required')\nframe.validate(state, complete)\nuint(frame.choice, 32)\nframe, allowed = _position_strategy_actor_gate(state, frame)\nif not allowed:\n    return _position_strategy_done(state, frame, complete)\npositions = state.table_at(4294943056).cursor()\nframe = first_replace(frame, roster=positions)\nframe = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\nframe = _position_order_shift(frame, 'target_x', 2)\noffset = low16(frame.target_x)\nframe = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))\nframe = _position_strategy_move(state, frame, 'target_x', positions.word(offset))\nframe = _position_strategy_call_fields(state, frame, 148384, 148304, complete)\nif frame.status & 1:\n    selected = low16(frame.count)\n    state.write(4294964134, 2, selected)\n    frame = _position_strategy_status(state, frame, selected, 16)\n    frame = _position_strategy_call_fields(state, frame, 148444, 148316, complete)\n    if frame.status & 1:\n        return _position_strategy_done(state, frame, complete)\nelse:\n    frame = _position_strategy_call_fields(state, frame, 146184, 148328, complete)\n    if frame.status & 1:\n        frame = _position_strategy_call_fields(state, frame, 148542, 148344, complete)\n    else:\n        frame = _position_strategy_call_fields(state, frame, 146342, 148336, complete)\nreturn _commit_contact_position_fields(state, frame, 'distance', 148382, complete)"}})

DECLARATIONS.update({'_evaluate_position_contact_response_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, nearest: bool, complete: bool', 'returns': 'StandardPositionOrderFields', 'flow': "from ..high_level_battle_ai.business_formation import _first_add_word\nif type(nearest) is not bool or type(complete) is not bool:\n    raise ValueError('actual response route and completeness selectors required')\nframe.validate(state, complete)\nreadiness_table = state.table_at(4294948352).cursor()\nframe = first_replace(frame, roster=readiness_table)\nactor = low16(frame.choice)\nframe = _position_strategy_move(state, frame, 'target_x', actor)\nframe = _position_order_shift(frame, 'target_x', 1)\nreadiness = readiness_table.word(low16(frame.target_x))\nframe = _position_strategy_move(state, frame, 'target_y', readiness)\nframe = _position_strategy_move(state, frame, 'unit', 0)\nframe = _standard_order_compare(frame, readiness, 70)\nif readiness >= 70:\n    frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)\n    frame = _standard_order_compare(frame, readiness, 90)\n    if readiness >= 90:\n        frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)\nframe = _position_strategy_call_fields(state, frame, 33748, 149754 if nearest else 148484, complete)\nsample = low16(frame.target_x)\nframe = first_replace(frame, target_x=sample)\nframe = _position_strategy_status(state, frame, sample, 32)\nshifted = u32(sample << 2)\nframe = first_replace(frame, target_x=shifted)\nframe = _position_strategy_status(state, frame, shifted, 32, False, False, False)\nswapped = swap_words(shifted)\nframe = first_replace(frame, target_x=swapped)\nframe = _position_strategy_status(state, frame, swapped, 32)\nframe = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))\nif low16(frame.target_x) < low16(frame.unit):\n    frame = _position_strategy_call_fields(state, frame, 157024, 149774 if nearest else 148504, complete)\n    if frame.status & 1:\n        return _position_strategy_done(state, frame, complete)\nif nearest:\n    frame = _position_strategy_call_fields(state, frame, 149798, 149782, complete)\n    frame = _position_order_shift(frame, 'target_y', 2)\n    offset = low16(frame.target_y)\n    frame = _position_strategy_move(state, frame, 'unit', frame.roster.word(offset))\n    frame = _position_strategy_move(state, frame, 'count', frame.roster.word(offset, 2))\nelse:\n    frame = first_replace(frame, candidates=state.table_at(16722944).cursor())\n    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\n    frame = _position_order_shift(frame, 'target_x', 2)\n    frame = first_replace(frame, roster=state.table_at(4294943056).cursor())\n    selected = state.read(4294964134, 2)\n    frame = _position_strategy_move(state, frame, 'count', selected)\n    frame = _position_order_shift(frame, 'count', 2)\n    offset = low16(frame.count)\n    frame = _position_strategy_move(state, frame, 'unit', frame.roster.word(offset))\n    frame = _position_strategy_move(state, frame, 'distance', frame.roster.word(offset, 2))\nreturn _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)"}})

DECLARATIONS.update({'evaluate_selected_contact_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': 'return _evaluate_position_contact_response_fields(state, frame, False, complete)'}})

DECLARATIONS.update({'evaluate_nearest_anchor_contact_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': 'return _evaluate_position_contact_response_fields(state, frame, True, complete)'}})

DECLARATIONS.update({'_evaluate_anchor_position_body_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool', 'returns': 'StandardPositionOrderFields', 'flow': "frame, allowed = _position_strategy_actor_gate(state, frame)\nif not allowed:\n    return _position_strategy_done(state, frame, complete)\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, low16(frame.unit))\nframe = first_replace(frame, stack_cursor=stack)\nframe = _position_strategy_call_fields(state, frame, 144594, 149608, complete)\nstack = frame.stack_cursor\npacked = stack.word()\nframe = first_replace(frame, stack_cursor=stack.advance(2))\nframe = _position_strategy_move(state, frame, 'unit', packed)\ncontacts = state.read(4294955776, 2)\nframe = _position_strategy_status(state, frame, contacts, 16)\nif not contacts & 32768:\n    frame = _position_strategy_call_fields(state, frame, 149714, 149622, complete)\n    if frame.status & 1:\n        return _position_strategy_done(state, frame, complete)\nelse:\n    frame = _position_strategy_call_fields(state, frame, 149904, 149634, complete)\n    positions = state.table_at(4294943056).cursor()\n    frame = first_replace(frame, roster=positions)\n    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\n    frame = _position_order_shift(frame, 'target_x', 2)\n    offset = low16(frame.target_x)\n    frame = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))\n    frame = _position_strategy_move(state, frame, 'target_x', positions.word(offset))\n    frame = _position_strategy_move(state, frame, 'count', low16(frame.unit))\n    masked = low16(frame.unit) & 65280\n    frame = _position_strategy_move(state, frame, 'unit', masked)\n    frame = _position_order_shift(frame, 'unit', 2)\n    frame = _position_order_shift(frame, 'count', 7)\n    frame = _position_order_shift(frame, 'count', 3)\n    frame = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))\n    if low16(frame.target_x) == low16(frame.unit):\n        frame = _standard_order_compare(frame, low16(frame.target_y), low16(frame.count))\n        if low16(frame.target_y) == low16(frame.count):\n            return _position_strategy_done(state, frame, complete)\nreturn _commit_contact_position_fields(state, frame, 'count', 149712, complete)"}})

DECLARATIONS.update({'evaluate_anchor_position_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current position fields required')\nframe.validate(state, complete)\nframe = _position_strategy_move(state, frame, 'unit', state.read(16727754, 2))\nreturn _evaluate_anchor_position_body_fields(state, frame, complete)"}})

DECLARATIONS.update({'evaluate_alternate_anchor_position_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current alternate fields required')\nframe.validate(state, complete)\nframe = _position_strategy_move(state, frame, 'unit', state.read(16727756, 2))\nreturn _evaluate_anchor_position_body_fields(state, frame, complete)"}})

