DECLARATIONS.update({'highbank_coordinate_live_state_69': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState69Input', 'returns': 'HighbankCoordinateLiveState69Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState69Input:\n    raise ValueError('function-specific typed staging input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, offset_x=inputs.limit, choice=inputs.remaining, stack_cursor=inputs.stack_cursor)\nresult = evaluate_readiness_contact_action_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState69Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'highbank_coordinate_live_state_65_alternate_2': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState65Alternate2Input', 'returns': 'HighbankCoordinateLiveState65Alternate2Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState65Alternate2Input:\n    raise ValueError('function-specific typed staging input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, roster=inputs.destination.cursor(), candidates=inputs.source.cursor(), controller=inputs.descriptor.cursor(), scratch=inputs.roster.cursor(), stack_cursor=inputs.stack_cursor)\nresult = evaluate_guarded_second_staging_order_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState65Alternate2Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), descriptor=state.table_at(frame.controller.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'highbank_coordinate_live_state_70': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState70Input', 'returns': 'HighbankCoordinateLiveState70Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState70Input:\n    raise ValueError('function-specific typed staging input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, candidates=inputs.source.cursor(), scratch=inputs.roster.cursor())\nresult = evaluate_second_staging_position_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState70Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'evaluate_readiness_contact_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "from ..high_level_battle_ai.business_formation import _first_add_word\nchecked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('actual readiness-action fields required')\nframe.validate(state, complete)\nreadiness_table = state.table_at(4294948352).cursor()\nframe = first_replace(frame, roster=readiness_table)\nframe = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\nframe = _position_order_shift(frame, 'target_x', 1)\nframe = _position_strategy_move(state, frame, 'unit', 0)\nreadiness = readiness_table.word(low16(frame.target_x))\nframe = _position_strategy_move(state, frame, 'target_y', readiness)\nfor threshold in (50, 70, 90):\n    frame = _standard_order_compare(frame, readiness, threshold)\n    if readiness < threshold:\n        break\n    frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)\nframe = _position_strategy_call_fields(state, frame, 33748, 146544, complete)\nsample = low16(frame.target_x)\nframe = first_replace(frame, target_x=sample)\nframe = _position_strategy_status(state, frame, sample, 32)\nshifted = u32(sample << 2)\nframe = first_replace(frame, target_x=shifted)\nframe = _position_strategy_status(state, frame, shifted, 32, False, False, False)\nswapped = swap_words(shifted)\nframe = first_replace(frame, target_x=swapped)\nframe = _position_strategy_status(state, frame, swapped, 32)\nframe = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))\nif low16(frame.target_x) < low16(frame.unit):\n    frame = _position_strategy_call_fields(state, frame, 144594, 146564, complete)\n    first = state.read(4294955776, 2)\n    frame = _position_strategy_status(state, frame, first, 16)\n    if not first & 32768:\n        frame = _position_strategy_call_fields(state, frame, 157024, 146576, complete)\n        return _position_strategy_done(state, frame, complete)\nreturn _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)"}})

DECLARATIONS.update({'_secondary_staging_policy_route_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation=None', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_main_flows.contexts_gameplay import BattlePolicy\nfrom ..high_level_main_flows.business_gameplay import _primary_city_rectangle_call, _primary_other_city_retreat_call, _primary_low_strength_fallback_tail, _battle_policy_retained_frame\nframe.validate(state, True)\nstate.sr = state.sr & 65504 | frame.status\npolicy = BattlePolicy(target_x=frame.target_x, target_y=frame.target_y, unit=frame.unit, count=frame.count, distance=frame.distance, offset_x=frame.offset_x, offset_y=frame.offset_y, choice=frame.choice, roster=frame.roster, candidates=frame.candidates, controller=frame.controller, scan=frame.scan, opponent=frame.opponent, scratch=frame.scratch, auxiliary=frame.auxiliary, stack_cursor=frame.stack_cursor).validate(state)\nif target == 145206:\n    uint(continuation, 32)\n    returned = _primary_city_rectangle_call(state, policy, continuation)\nelif target == 141142:\n    uint(continuation, 32)\n    returned = _primary_other_city_retreat_call(state, policy, continuation)\nelif target == 149526:\n    if continuation is not None:\n        raise ValueError('original BCS24816 has no additional continuation')\n    returned = _primary_low_strength_fallback_tail(state, policy)\nelse:\n    raise ValueError('only the three actual existing staging policy routes are admitted')\nreturn _battle_policy_retained_frame(state, returned)"}})

DECLARATIONS.update({'evaluate_guarded_second_staging_order_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current guarded-staging fields required')\nframe.validate(state, complete)\nframe = _position_strategy_call_fields(state, frame, 146586, 146622, complete)\nif frame.status & 1:\n    frame = _secondary_staging_policy_route_fields(state, frame, 149526)\n    return _position_strategy_done(state, frame, complete)\nframe = _secondary_staging_policy_route_fields(state, frame, 145206, 146630)\nif frame.status & 1:\n    return _position_strategy_done(state, frame, complete)\nframe = _secondary_staging_policy_route_fields(state, frame, 141142, 146638)\nif frame.status & 1:\n    return _position_strategy_done(state, frame, complete)\nframe = _position_strategy_call_fields(state, frame, 146494, 146646, complete)\nif frame.status & 1:\n    return _position_strategy_done(state, frame, complete)\nframe = _position_strategy_call_fields(state, frame, 146656, 146654, complete)\nreturn _position_strategy_done(state, frame, complete)"}})

DECLARATIONS.update({'evaluate_second_staging_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current staging-position fields required')\nframe.validate(state, complete)\nframe, allowed = _position_strategy_actor_gate(state, frame)\nif not allowed:\n    return _position_strategy_done(state, frame, complete)\npositions = state.table_at(4294943056).cursor()\nframe = first_replace(frame, roster=positions)\nframe = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\nframe = _position_order_shift(frame, 'target_x', 2)\noffset = low16(frame.target_x)\nframe = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))\nframe = _position_strategy_move(state, frame, 'target_x', positions.word(offset))\nframe = _position_strategy_call_fields(state, frame, 146184, 146716, complete)\nif frame.status & 1:\n    frame = _position_strategy_call_fields(state, frame, 146772, 146732, complete)\nelse:\n    frame = _position_strategy_call_fields(state, frame, 146342, 146724, complete)\nreturn _commit_contact_position_fields(state, frame, 'distance', 146770, complete)"}})

DECLARATIONS.update({'_position_strategy_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import BattlePolicyMemory\nfrom ..high_level_battle_ai.business_geometry import collect_contacts_in_speed_radius_fields\nfrom ..high_level_battle_ai.business_formation import compare_actor_shifted_troop_word_to_weakest_contact_fields, read_outer_east_staging_anchor_fields, select_contact_nearest_deployment_anchor_fields, read_formation_relative_position_delta_fields, first_deployment_random_fields, read_second_side_staging_anchor_fields, test_second_side_relative_total_shortfall_fields, test_point_in_battlefield_staging_rectangle_fields, sample_battlefield_staging_rectangle_fields\nentered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif not complete and any((value is None for value in (entered.target_x, entered.target_y, entered.unit, entered.count, entered.distance, entered.offset_x, entered.offset_y, entered.choice, entered.status))):\n    raise Boundary('old position API lacks an actual child CCR or retained carrier; real return slot is already written')\nmemory = BattlePolicyMemory(state)\nif target == 144594:\n    result = collect_contacts_in_speed_radius_fields(memory, entered).frame\nelif target == 148384:\n    result = compare_actor_shifted_troop_word_to_weakest_contact_fields(memory, entered)[0]\nelif target == 148444:\n    result = evaluate_selected_contact_position_fields(state, entered, complete).frame\nelif target == 148542:\n    result = read_outer_east_staging_anchor_fields(memory, entered)[0]\nelif target == 149714:\n    result = evaluate_nearest_anchor_contact_fields(state, entered, complete).frame\nelif target == 149798:\n    result = select_contact_nearest_deployment_anchor_fields(memory, entered)[0]\nelif target == 149904:\n    result = read_formation_relative_position_delta_fields(memory, entered)[0]\nelif target == 146184:\n    result = test_point_in_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 146342:\n    result = sample_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 33748:\n    result = first_deployment_random_fields(memory, entered)\nelif target == 157024:\n    result = execute_standard_action_chain_fields(state, entered, complete).frame\nelif target == 122026:\n    from .business_city import city_calculate_live_quotient_10_fields\n    result = city_calculate_live_quotient_10_fields(memory, entered)\nelif target == 146586:\n    result = test_second_side_relative_total_shortfall_fields(memory, entered)[0]\nelif target == 146494:\n    result = evaluate_readiness_contact_action_fields(state, entered, complete).frame\nelif target == 146656:\n    result = evaluate_second_staging_position_fields(state, entered, complete).frame\nelif target == 146772:\n    result = read_second_side_staging_anchor_fields(memory, entered)[0]\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('position child requires its actual current retained fields')\nresult.validate(state, complete)\nreturned = _standard_order_leave(result, continuation)\nif returned.status is not None:\n    state.sr = state.sr & 65504 | returned.status\nreturn returned"}})

