DECLARATIONS.update({'highbank_coordinate_live_state_68': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState68Input', 'returns': 'HighbankCoordinateLiveState68Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState68Input:\n    raise ValueError('function-specific typed staging input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, offset_y=inputs.member, choice=inputs.remaining, candidates=inputs.source.cursor(), scratch=inputs.roster.cursor())\nresult = evaluate_first_staging_position_fields(state, frame, False)\nframe = result.frame\nreturn HighbankCoordinateLiveState68Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), roster=state.table_at(frame.scratch.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice, carry=bool(result.conditions & 1), zero=bool(result.conditions & 4), negative=bool(result.conditions & 8), overflow=bool(result.conditions & 2)).validate(state)"}})

DECLARATIONS.update({'evaluate_first_staging_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, complete: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool:\n    raise ValueError('sole current first-staging fields required')\nframe.validate(state, complete)\nframe, allowed = _position_strategy_actor_gate(state, frame)\nif not allowed:\n    return _position_strategy_done(state, frame, complete)\npositions = state.table_at(4294943056).cursor()\nframe = first_replace(frame, roster=positions)\nframe = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))\nframe = _position_order_shift(frame, 'target_x', 2)\noffset = low16(frame.target_x)\nframe = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))\nframe = _position_strategy_move(state, frame, 'target_x', positions.word(offset))\nframe = _position_strategy_call_fields(state, frame, 146184, 146128, complete)\nif frame.status & 1:\n    frame = _position_strategy_call_fields(state, frame, 146420, 146144, complete)\nelse:\n    frame = _position_strategy_call_fields(state, frame, 146342, 146136, complete)\nreturn _commit_contact_position_fields(state, frame, 'distance', 146182, complete)"}})

DECLARATIONS.update({'_position_strategy_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool', 'returns': 'FirstDeploymentFrame', 'flow': "from .services import BattlePolicyMemory\nfrom ..high_level_battle_ai.business_geometry import collect_contacts_in_speed_radius_fields\nfrom ..high_level_battle_ai.business_formation import compare_actor_shifted_troop_word_to_weakest_contact_fields, read_outer_east_staging_anchor_fields, select_contact_nearest_deployment_anchor_fields, read_formation_relative_position_delta_fields, first_deployment_random_fields, read_second_side_staging_anchor_fields, test_second_side_relative_total_shortfall_fields, read_first_side_staging_anchor_fields, test_point_in_battlefield_staging_rectangle_fields, sample_battlefield_staging_rectangle_fields\nentered = _standard_order_enter(frame, continuation)\nif entered.status is not None:\n    state.sr = state.sr & 65504 | entered.status\nif not complete and any((value is None for value in (entered.target_x, entered.target_y, entered.unit, entered.count, entered.distance, entered.offset_x, entered.offset_y, entered.choice, entered.status))):\n    raise Boundary('old position API lacks an actual child CCR or retained carrier; real return slot is already written')\nmemory = BattlePolicyMemory(state)\nif target == 144594:\n    result = collect_contacts_in_speed_radius_fields(memory, entered).frame\nelif target == 148384:\n    result = compare_actor_shifted_troop_word_to_weakest_contact_fields(memory, entered)[0]\nelif target == 148444:\n    result = evaluate_selected_contact_position_fields(state, entered, complete).frame\nelif target == 148542:\n    result = read_outer_east_staging_anchor_fields(memory, entered)[0]\nelif target == 149714:\n    result = evaluate_nearest_anchor_contact_fields(state, entered, complete).frame\nelif target == 149798:\n    result = select_contact_nearest_deployment_anchor_fields(memory, entered)[0]\nelif target == 149904:\n    result = read_formation_relative_position_delta_fields(memory, entered)[0]\nelif target == 146184:\n    result = test_point_in_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 146342:\n    result = sample_battlefield_staging_rectangle_fields(memory, entered)\nelif target == 33748:\n    result = first_deployment_random_fields(memory, entered)\nelif target == 157024:\n    result = execute_standard_action_chain_fields(state, entered, complete).frame\nelif target == 122026:\n    from .business_city import city_calculate_live_quotient_10_fields\n    result = city_calculate_live_quotient_10_fields(memory, entered)\nelif target == 146586:\n    result = test_second_side_relative_total_shortfall_fields(memory, entered)[0]\nelif target == 146494:\n    result = evaluate_readiness_contact_action_fields(state, entered, complete).frame\nelif target == 146656:\n    result = evaluate_second_staging_position_fields(state, entered, complete).frame\nelif target == 146772:\n    result = read_second_side_staging_anchor_fields(memory, entered)[0]\nelif target == 146420:\n    result = read_first_side_staging_anchor_fields(memory, entered)[0]\nelse:\n    result = call_target(state, target, entered)\nif type(result) is not FirstDeploymentFrame:\n    raise Boundary('position child requires its actual current retained fields')\nresult.validate(state, complete)\nreturned = _standard_order_leave(result, continuation)\nif returned.status is not None:\n    state.sr = state.sr & 65504 | returned.status\nreturn returned"}})

