DECLARATIONS.update({'_evaluate_guarded_deployment_attempts_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, family: int, complete: bool, skip_gate: bool=False', 'returns': 'StandardPositionOrderFields', 'flow': "checked_state(state)\nif type(frame) is not FirstDeploymentFrame or type(complete) is not bool or type(skip_gate) is not bool:\n    raise ValueError('actual deployment fields, entry and completeness required')\nframe.validate(state, complete)\nif family == 2:\n    gate_return, tries = (146622, ((145206, 146630), (141142, 146638), (146494, 146646), (146656, 146654)))\nelif family == 6:\n    gate_return, tries = (148620, ((145206, 148628), (141142, 148636), (142640, 148644), (148654, 148652)))\nelif family == 7:\n    gate_return, tries = (148944, ((145206, 148952), (141142, 148960), (142640, 148968), (148978, 148976)))\nelif family == 8:\n    gate_return, tries = (149196, ((145206, 149204), (141142, 149212), (142640, 149220), (146068, 149228)))\nelse:\n    raise ValueError('only the actual connected deployment families required')\nif not skip_gate:\n    frame = _position_strategy_call_fields(state, frame, 146586, gate_return, complete)\n    if frame.status & 1:\n        frame = _secondary_staging_policy_route_fields(state, frame, 149526)\n        return _position_strategy_done(state, frame, complete)\nfor target, continuation in tries:\n    if target in (145206, 141142, 142640):\n        frame = _secondary_staging_policy_route_fields(state, frame, target, continuation)\n    else:\n        frame = _position_strategy_call_fields(state, frame, target, continuation, complete)\n    if frame.status & 1:\n        break\nreturn _position_strategy_done(state, frame, complete)"}})


