DECLARATIONS.update({'_secondary_staging_policy_route_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target, continuation=None', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_main_flows.contexts_gameplay import BattlePolicy\nfrom ..high_level_main_flows.business_gameplay import _primary_city_rectangle_call, _primary_other_city_retreat_call, _primary_retreat_mark_call, _primary_short_roster_tail, _primary_low_strength_fallback_tail, _primary_small_force_tail, _battle_policy_retained_frame\nframe.validate(state, True)\nstate.sr = state.sr & 65504 | frame.status\npolicy = BattlePolicy(target_x=frame.target_x, target_y=frame.target_y, unit=frame.unit, count=frame.count, distance=frame.distance, offset_x=frame.offset_x, offset_y=frame.offset_y, choice=frame.choice, roster=frame.roster, candidates=frame.candidates, controller=frame.controller, scan=frame.scan, opponent=frame.opponent, scratch=frame.scratch, auxiliary=frame.auxiliary, stack_cursor=frame.stack_cursor).validate(state)\nif target == 145206:\n    uint(continuation, 32)\n    returned = _primary_city_rectangle_call(state, policy, continuation)\nelif target == 141142:\n    uint(continuation, 32)\n    returned = _primary_other_city_retreat_call(state, policy, continuation)\nelif target == 149526:\n    if continuation is not None:\n        raise ValueError('original BCS24816 has no additional continuation')\n    returned = _primary_low_strength_fallback_tail(state, policy)\nelif target == 148214:\n    if continuation is not None:\n        raise ValueError('original strategy5 fallthrough adds no continuation')\n    returned = _primary_small_force_tail(state, policy)\nelif target == 142640:\n    uint(continuation, 32)\n    returned = _primary_retreat_mark_call(state, policy, continuation)\nelif target == 146038:\n    if continuation is not None:\n        raise ValueError('original23A76 branch adds no call slot')\n    returned = _primary_short_roster_tail(state, policy)\nelse:\n    raise ValueError('only the actual existing staging policy routes are admitted')\nreturn _battle_policy_retained_frame(state, returned)"}})


