DECLARATIONS.update({'highbank_select_live_state_3': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState3Input', 'returns': 'HighbankSelectLiveState3Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState3Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit)\nframe = test_city_engagement_member_near_origin_fields(state, frame)\nreturn HighbankSelectLiveState3Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_city_engagement_record_shift_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, amount: int, right: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if amount not in (1, 2, 3, 5, 7):\n    raise ValueError('original engagement-record shift required')\nframe = _position_order_shift(frame, carrier, amount, right)\nstate.sr = state.sr & 65504 | frame.status\nreturn frame"}})

DECLARATIONS.update({'_city_engagement_scan_display_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "while True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_compare(state, frame, low8(frame.target_y), low8(frame.target_x), 8)\n    if frame.status & 4:\n        return frame"}})

DECLARATIONS.update({'select_city_engagement_display_side_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131208)\nframe = first_replace(frame, roster=state.table_at(4294964318).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nvalue = frame.roster.word(s16(low16(frame.target_x)))\nframe = _movement_move(state, frame, 'target_x', value, 16)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor())\nframe = _city_engagement_scan_display_member_fields(state, frame)\nside = 0\nif not frame.status & 8:\n    frame = first_replace(frame, roster=state.table_at(4294942759).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\n    value = frame.roster.byte(s16(low16(frame.target_x)))\n    frame = _movement_move(state, frame, 'target_x', value, 8)\n    frame = first_replace(frame, roster=state.table_at(4294944080).cursor())\n    frame = _city_engagement_scan_display_member_fields(state, frame)\n    if not frame.status & 8:\n        return frame\n    side = 2\nframe = _duel_menu_write_word_fields(state, frame, 4294964950, side)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1041)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)"}})

DECLARATIONS.update({'_city_engagement_participation_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, mark: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(mark) is not bool:\n    raise ValueError('actual participation test or mark required')\nframe = _movement_move(state, frame, 'offset_y', state.read(4294964874, 2), 16)\nframe = _movement_adjust_word(state, frame, 'offset_y', -1)\nframe = _movement_move(state, frame, 'choice', low16(frame.offset_y), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'choice', 3, True)\nframe = _movement_move(state, frame, 'offset_y', low16(frame.offset_y) & 7, 16)\nframe = first_replace(frame, auxiliary=state.table_at(4294963114).cursor())\noffset = s16(low16(frame.choice))\nvalue = frame.auxiliary.byte(offset)\nbit = low16(frame.offset_y) & 7\nstatus = frame.status & 27 | (0 if value & 1 << bit else 4)\nstate.sr = state.sr & 65504 | status\nframe = first_replace(frame, status=status)\nif mark:\n    frame.auxiliary.set_byte(offset, value | 1 << bit)\nreturn frame"}})

DECLARATIONS.update({'_city_engagement_merge_pending_resource_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, pending: int, total: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (pending, total) not in ((4294964886, 4294964890), (4294964894, 4294964898)):\n    raise ValueError('original participation resource pair required')\nframe = _movement_move_long(state, frame, 'target_x', state.read(pending, 4))\nframe = _movement_arithmetic_long(state, frame, 'target_x', state.read(total, 4))\nframe = _first_compare_long(frame, frame.target_x, 999999)\nstate.sr = state.sr & 65504 | frame.status\nif not frame.status & 5:\n    frame = _movement_move_long(state, frame, 'target_x', 999999)\nstate.write(total, 4, frame.target_x)\nframe = _movement_test_long(state, frame, frame.target_x)\nstate.read(pending, 4)\nstate.write(pending, 4, 0)\nreturn _movement_test_long(state, frame, 0)"}})

DECLARATIONS.update({'commit_city_engagement_participation_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131298)\nframe = _city_engagement_participation_bit_fields(state, frame, False)\nif frame.status & 4:\n    frame = _deployment_menu_call_fields(state, frame, 131476, 131328)\n    if not frame.status & 1:\n        return frame\n    frame = _duel_menu_write_word_fields(state, frame, 4294964066, 5)\n    frame = _movement_move(state, frame, 'target_x', 314, 16)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964086, state.read(4294964876, 2))\n    frame = _deployment_menu_call_fields(state, frame, 423666, 131354)\nframe = _city_engagement_participation_bit_fields(state, frame, True)\nframe = _city_engagement_merge_pending_resource_fields(state, frame, 4294964886, 4294964890)\nframe = _city_engagement_merge_pending_resource_fields(state, frame, 4294964894, 4294964898)\nframe = first_replace(frame, roster=state.table_at(4294944122).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame.candidates.set_byte(s16(low16(frame.target_y)), low8(frame.target_x))\n    frame = _movement_test(state, frame, low8(frame.target_x), 8)\nreturn _duel_menu_write_word_fields(state, frame, 4294944122, 65535)"}})

DECLARATIONS.update({'test_city_engagement_member_near_origin_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131476)\nframe = first_replace(frame, roster=state.table_at(4294942719).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(s16(low16(frame.target_x))), 8)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 5)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))\nframe = first_replace(frame, roster=state.table_at(703912).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(s16(low16(frame.target_x))), 8)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 3)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 7)\nframe = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)\nframe = _movement_move(state, frame, 'count', 0, 16)\nframe = _movement_move(state, frame, 'count', frame.roster.byte(s16(low16(frame.target_x)), 1), 8)\nframe = _city_engagement_record_shift_fields(state, frame, 'count', 3)\nframe = _city_engagement_record_shift_fields(state, frame, 'count', 7)\nframe = _movement_move(state, frame, 'distance', low16(frame.count), 16)\nframe = _special_action_sub_word(state, frame, 'target_y', 1024)\nframe = _movement_add_word(state, frame, 'unit', 1024)\nframe = _special_action_sub_word(state, frame, 'count', 1024)\nframe = _movement_add_word(state, frame, 'distance', 1024)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor(), candidates=state.table_at(4294943056).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        state.sr &= 65534\n        return first_replace(frame, status=state.sr & 31)\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\n    offset = s16(low16(frame.target_x))\n    frame = _movement_move(state, frame, 'offset_x', frame.candidates.word(offset), 16)\n    frame = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.target_y), 16)\n    if frame.status & 1:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.unit), 16)\n    if not frame.status & 5:\n        continue\n    frame = _movement_move(state, frame, 'offset_x', frame.candidates.word(offset, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.count), 16)\n    if frame.status & 1:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.distance), 16)\n    if not frame.status & 5:\n        continue\n    state.sr |= 1\n    return first_replace(frame, status=state.sr & 31)"}})

