DECLARATIONS.update({'highbank_select_live_state_8': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState8Input', 'returns': 'HighbankSelectLiveState8Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState8Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field)\nframe = remove_officer_from_active_or_retired_fields(state, frame)\nreturn HighbankSelectLiveState8Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), field=frame.target_y, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_select_live_state_9': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState9Input', 'returns': 'HighbankSelectLiveState9Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState9Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field)\nframe = remove_officer_from_selected_active_fields(state, frame)\nreturn HighbankSelectLiveState9Result(destination=state.table_at(frame.roster.base), field=frame.target_y, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_calculate_live_quotient_1': {'signature': 'state: SceneState, inputs: HighbankCalculateLiveQuotient1Input', 'returns': 'HighbankCalculateLiveQuotient1Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCalculateLiveQuotient1Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), unit=inputs.tile)\nframe = decrease_removed_officer_influence_fields(state, frame)\nreturn HighbankCalculateLiveQuotient1Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_select_live_state_10': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState10Input', 'returns': 'HighbankSelectLiveState10Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState10Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = read_officer_influence_pair_fields(state, frame)\nreturn HighbankSelectLiveState10Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_update_record_flags_2': {'signature': 'state: SceneState, inputs: HighbankUpdateRecordFlags2Input', 'returns': 'HighbankUpdateRecordFlags2Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankUpdateRecordFlags2Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = return_selected_officer_to_outcome_fields(state, frame)\nreturn HighbankUpdateRecordFlags2Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_calculate_live_quotient_2': {'signature': 'state: SceneState, inputs: HighbankCalculateLiveQuotient2Input', 'returns': 'HighbankCalculateLiveQuotient2Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCalculateLiveQuotient2Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), unit=inputs.tile)\nframe = increase_returned_officer_influence_fields(state, frame)\nreturn HighbankCalculateLiveQuotient2Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_coordinate_live_state_12': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState12Input', 'returns': 'HighbankCoordinateLiveState12Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState12Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile)\nframe = retire_selected_officer_to_outcome_fields(state, frame)\nreturn HighbankCoordinateLiveState12Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, 'highbank_calculate_live_quotient_3': {'signature': 'state: SceneState, inputs: HighbankCalculateLiveQuotient3Input', 'returns': 'HighbankCalculateLiveQuotient3Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCalculateLiveQuotient3Input:\n    raise ValueError('function-specific historical officer outcome required')\ninputs.validate(state)\nframe = first_replace(FirstDeploymentFrame.unobserved(), unit=inputs.tile)\nframe = increase_retired_officer_influence_fields(state, frame)\nreturn HighbankCalculateLiveQuotient3Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2)).validate(state)"}, '_officer_outcome_call_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, target: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "pairs = ((33748, 132968), (133008, 132972), (132852, 133090), (132924, 133094), (133152, 133098), (423666, 133124), (33748, 133158), (133008, 133162), (132852, 133228), (132924, 133232), (133274, 133236), (133326, 133240), (423666, 133266), (33748, 133280), (133008, 133284))\nif (target, continuation) not in pairs:\n    raise ValueError('actual officer-outcome child/return pair required')\nframe = _resource_cost_frame(state, frame, target)\nmemory = BattlePresentationMemory(state)\ndef child(actual_memory, entered):\n    if target == 33748:\n        return _presentation_random_fields(actual_memory, entered)\n    if target == 132852:\n        return remove_officer_from_active_or_retired_fields(state, entered)\n    if target == 132924:\n        return remove_officer_from_selected_active_fields(state, entered)\n    if target == 133008:\n        return read_officer_influence_pair_fields(state, entered)\n    if target == 133152:\n        return increase_returned_officer_influence_fields(state, entered)\n    if target == 133274:\n        return increase_retired_officer_influence_fields(state, entered)\n    if target == 133326:\n        return apply_returning_officer_loyalty_fields(actual_memory, entered)\n    return execute_deployment_menu_fields(state, 423666, entered)\nreturn _presentation_call_fields(memory, frame, continuation, child)"}, '_officer_outcome_seek_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view_role: str', 'returns': 'tuple', 'flow': "if view_role not in ('roster', 'candidates'):\n    raise ValueError('original active/retired list role required')\nwhile True:\n    view = frame.roster if view_role == 'roster' else frame.candidates\n    member = view.word()\n    frame = first_replace(frame, **{view_role: view.advance(2)})\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return (frame, False)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        return (frame, True)"}, 'remove_officer_from_active_or_retired_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132852)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor(), candidates=state.table_at(4294944122).cursor())\nbit = state.read(4294964951, 1) & 2\nframe = _postbattle_bit_fields(frame, bool(bit))\nstate.sr = state.sr & 65504 | frame.status\nif bit:\n    frame = first_replace(frame, roster=state.table_at(4294944080).cursor(), candidates=state.table_at(4294944206).cursor())\nframe, found = _officer_outcome_seek_fields(state, frame, 'roster')\nrole = 'roster'\nif not found:\n    role = 'candidates'\n    frame, found = _officer_outcome_seek_fields(state, frame, role)\nif found:\n    frame = _duel_result_compact_roster_fields(BattlePresentationMemory(state), frame, role)\nreturn frame"}, 'remove_officer_from_selected_active_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132924)\nbit = state.read(4294964951, 1) & 2\nframe = _postbattle_bit_fields(frame, bool(bit))\nstate.sr = state.sr & 65504 | frame.status\nframe = first_replace(frame, roster=state.table_at(4294944080 if bit else 4294944164).cursor())\nframe, found = _officer_outcome_seek_fields(state, frame, 'roster')\nif found:\n    frame = _duel_result_compact_roster_fields(BattlePresentationMemory(state), frame)\nreturn frame"}, 'read_officer_influence_pair_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133008)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nbit = state.read(4294964951, 1) & 2\nframe = _postbattle_bit_fields(frame, bool(bit))\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878 if bit else 4294964876, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'unit', frame.roster.word(s16(low16(frame.target_y))), 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964210, low16(frame.unit))\nframe = first_replace(frame, roster=state.table_at(4294951424).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', frame.roster.byte(s16(low16(frame.unit))), 8)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_move_long(state, frame, 'count', 0)\nreturn _movement_move(state, frame, 'count', frame.roster.byte(s16(low16(frame.target_x))), 8)"}, '_officer_influence_ratio_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, mode: str', 'returns': 'FirstDeploymentFrame', 'flow': "if mode not in ('loss', 'returned', 'retired'):\n    raise ValueError('original officer influence outcome required')\nslots = {'loss': (132968, 132972, 132994), 'returned': (133158, 133162, 133182), 'retired': (133280, 133284, 133306)}\nrandom_return, lookup_return, divide_site = slots[mode]\nframe = _officer_outcome_call_fields(state, frame, 33748, random_return)\nframe = _officer_outcome_call_fields(state, frame, 133008, lookup_return)\nframe = _movement_move_long(state, frame, 'target_x', 0)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964764, 2), 16)\nframe = _movement_move_long(state, frame, 'distance', frame.target_x)\nmemory = BattlePresentationMemory(state)\nframe = _postbattle_shift_long_fields(memory, frame, 'target_x', 1 if mode == 'retired' else 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.distance)\nframe = _postbattle_shift_long_fields(memory, frame, 'target_x', 3 if mode == 'retired' else 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.distance)\nif mode == 'retired':\n    frame = _postbattle_shift_long_fields(memory, frame, 'target_x', 1)\nelif mode == 'loss':\n    frame = _movement_move_long(state, frame, 'target_x', swap_words(frame.target_x))\nframe = _movement_add_word(state, frame, 'target_x', 10 if mode == 'loss' else 30 if mode == 'returned' else 50)\ndivisor = low16(frame.target_x)\nif divisor == 0:\n    raise MovementContinuationBoundary(divide_site, frame, 'original zero divisor requires its real exception continuation')\nresult = divu_retained(frame.count, divisor)\nframe = first_replace(frame, count=result)\nif mode == 'loss':\n    frame = _special_action_sub_word(state, frame, 'target_y', low16(frame.count))\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'target_y', 0, 16)\nelse:\n    frame = _movement_add_word(state, frame, 'target_y', low16(frame.count))\n    frame = _movement_compare(state, frame, low16(frame.target_y), 100, 16)\n    if not frame.status & 5:\n        frame = _movement_move(state, frame, 'target_y', 100, 16)\nframe.roster.set_byte(s16(low16(frame.unit)), low8(frame.target_y))\nreturn _movement_test(state, frame, low8(frame.target_y), 8)"}, 'decrease_removed_officer_influence_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "return _officer_influence_ratio_fields(state, _resource_cost_frame(state, frame, 132962), 'loss')"}, 'increase_returned_officer_influence_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "return _officer_influence_ratio_fields(state, _resource_cost_frame(state, frame, 133152), 'returned')"}, 'increase_retired_officer_influence_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "return _officer_influence_ratio_fields(state, _resource_cost_frame(state, frame, 133274), 'retired')"}, '_append_officer_outcome_destination_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, destination: int', 'returns': 'FirstDeploymentFrame', 'flow': "if destination not in (4294963072, 4294946600):\n    raise ValueError('original officer outcome destination required')\nframe = first_replace(frame, roster=state.table_at(destination).cursor())\nwhile True:\n    value = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_test(state, frame, value, 16)\n    if frame.status & 8:\n        break\nframe = _duel_menu_write_word_fields(state, frame, u32(frame.roster.base - 2), state.read(4294964134, 2))\nreturn _duel_menu_write_word_fields(state, frame, frame.roster.base, 65535)"}, '_prepare_officer_outcome_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, kind: str', 'returns': 'FirstDeploymentFrame', 'flow': "if kind not in ('returned', 'retired'):\n    raise ValueError('original officer outcome message required')\nframe = _duel_menu_write_word_fields(state, frame, 4294964178, state.read(4294964134, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, state.read(4294964134, 2))\nframe = _movement_move(state, frame, 'target_x', 286 if kind == 'returned' else 287, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _officer_outcome_call_fields(state, frame, 423666, 133124 if kind == 'returned' else 133266)\nreturn _duel_menu_write_word_fields(state, frame, 4294964818, 1)"}, 'return_selected_officer_to_outcome_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133064)\nframe = _append_officer_outcome_destination_fields(state, frame, 4294963072)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _officer_outcome_call_fields(state, frame, 132852, 133090)\nframe = _officer_outcome_call_fields(state, frame, 132924, 133094)\nframe = _officer_outcome_call_fields(state, frame, 133152, 133098)\nframe = _prepare_officer_outcome_message_fields(state, frame, 'returned')\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _postbattle_bit_fields(frame, bool(frame.target_x & 128))\nframe = first_replace(frame, target_x=frame.target_x | 128)\nstate.sr = state.sr & 65504 | frame.status\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe.roster.set_byte(s16(low16(frame.target_y)), low8(frame.target_x))\nreturn _movement_test(state, frame, low8(frame.target_x), 8)"}, 'retire_selected_officer_to_outcome_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133202)\nframe = _append_officer_outcome_destination_fields(state, frame, 4294946600)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _officer_outcome_call_fields(state, frame, 132852, 133228)\nframe = _officer_outcome_call_fields(state, frame, 132924, 133232)\nframe = _officer_outcome_call_fields(state, frame, 133274, 133236)\nframe = _officer_outcome_call_fields(state, frame, 133326, 133240)\nreturn _prepare_officer_outcome_message_fields(state, frame, 'retired')"}})
