DECLARATIONS.update({'_city_engagement_merge_pending_resource_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, pending: int, total: int, destination_first: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if type(destination_first) is not bool or (pending, total) not in ((4294964886, 4294964890), (4294964890, 4294964886), (4294964894, 4294964898), (4294964898, 4294964894)):\n    raise ValueError('original participation or ownership resource pair required')\nframe = _movement_move_long(state, frame, 'target_x', state.read(total if destination_first else pending, 4))\nframe = _movement_arithmetic_long(state, frame, 'target_x', state.read(pending if destination_first else total, 4))\nframe = _first_compare_long(frame, frame.target_x, 999999)\nstate.sr = state.sr & 65504 | frame.status\nif not frame.status & 5:\n    frame = _movement_move_long(state, frame, 'target_x', 999999)\nstate.write(total, 4, frame.target_x)\nframe = _movement_test_long(state, frame, frame.target_x)\nstate.read(pending, 4)\nstate.write(pending, 4, 0)\nreturn _movement_test_long(state, frame, 0)"}})

DECLARATIONS.update({'dispatch_city_ownership_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131596)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nrelative = state.read(u32(131612 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', relative, 16)\nreturn _deployment_menu_call_fields(state, frame, u32(131674 + s16(relative)), 131610)"}})

DECLARATIONS.update({'resolve_city_ownership_transition_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131674)\nframe = _deployment_menu_call_fields(state, frame, 132068, 131678)\nframe = _deployment_menu_call_fields(state, frame, 132138, 131682)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\nrecognized = False\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        recognized = True\n        break\nif not recognized:\n    frame = _movement_move(state, frame, 'target_x', 135, 16)\n    frame = _deployment_menu_call_fields(state, frame, 32906, 131734)\n    frame = _deployment_menu_call_fields(state, frame, 131930, 131836)\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 5)\nframe = _movement_move(state, frame, 'target_x', 137, 16)\nframe = _deployment_menu_call_fields(state, frame, 32906, 131748)\nframe = _duel_menu_write_word_fields(state, frame, 4294946600, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294963072, 65535)\nframe = _deployment_menu_call_fields(state, frame, 131844, 131764)\nframe = _movement_test(state, frame, state.read(4294964480, 2), 16)\nif frame.status & 8:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 14)\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nfor address in (4294964066, 4294964088, 4294964824, 4294964946):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _movement_move(state, frame, 'target_x', 284, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 131818)"}})

DECLARATIONS.update({'_city_ownership_append_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, source: str, bounded: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(bounded) is not bool or (source, bounded) not in (('candidates', False), ('controller', True)):\n    raise ValueError('actual primary or bounded secondary roster required')\nwhile True:\n    cursor = frame.candidates if source == 'candidates' else frame.controller\n    member = cursor.word()\n    frame = first_replace(frame, **{source: cursor.advance(2)})\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\n    if bounded:\n        frame = _movement_compare(state, frame, low16(frame.target_y), 10, 16)\n        if not frame.status & 1:\n            return frame"}})

DECLARATIONS.update({'build_city_ownership_control_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131844)\nframe = first_replace(frame, roster=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294944164, 4294944122) if frame.status & 4 else (4294944080, 4294944206)\nframe = first_replace(frame, candidates=state.table_at(first).cursor(), controller=state.table_at(second).cursor())\nframe = _city_ownership_append_roster_fields(state, frame, 'candidates', False)\nframe = _movement_compare(state, frame, low16(frame.target_y), 10, 16)\nif frame.status & 1:\n    frame = _city_ownership_append_roster_fields(state, frame, 'controller', True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_y))\nreturn _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)"}})

DECLARATIONS.update({'_city_ownership_transfer_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, second_side: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(second_side) is not bool:\n    raise ValueError('actual transfer side required')\nwhile True:\n    cursor = frame.controller if second_side else frame.candidates\n    member = cursor.word()\n    frame = first_replace(frame, **{'controller' if second_side else 'candidates': cursor.advance(2)})\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    if not second_side:\n        frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.target_y), 16)\n        if frame.status & 4:\n            frame = first_replace(frame, scratch=state.table_at(4294953984).cursor())\n            frame = _settlement_write_byte_fields(state, frame, frame.scratch, 255, low16(frame.target_y))\n            continue\n        frame = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.target_x))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if second_side:\n        frame = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.target_x))\n    frame = _deployment_menu_call_fields(state, frame, 133326, 132052 if second_side else 132018)"}})

DECLARATIONS.update({'transfer_city_ownership_rosters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131930)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor(), candidates=state.table_at(4294944164).cursor(), controller=state.table_at(4294944122).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = first_replace(frame, candidates=state.table_at(4294944080).cursor(), controller=state.table_at(4294944206).cursor(), target_x=frame.target_y, target_y=frame.target_x)\nframe = first_replace(frame, scan=state.table_at(4294960704).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964210, frame.scan.word(low16(frame.target_x)))\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'target_y', frame.scan.word(low16(frame.target_y)), 16)\nframe = first_replace(frame, scan=frame.candidates, opponent=frame.controller)\nframe = _city_ownership_transfer_roster_fields(state, frame, False)\nframe = _city_ownership_transfer_roster_fields(state, frame, True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)\nframe = _settlement_store_word_fields(state, frame, frame.scan, 0, 65535)\nreturn _settlement_store_word_fields(state, frame, frame.opponent, 0, 65535)"}})

DECLARATIONS.update({'relabel_city_ownership_rosters_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132068)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor(), scan=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nfor address, continuation in ((4294944080, 132088), (4294944122, 132096), (4294944164, 132104), (4294944206, 132112)):\n    frame = first_replace(frame, candidates=state.table_at(address).cursor())\n    frame = _deployment_menu_call_fields(state, frame, 132114, continuation)\nreturn frame"}})

DECLARATIONS.update({'relabel_city_ownership_member_list_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132114)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.target_y))\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_y', 2)\n    offset = low16(frame.target_y)\n    frame.scan.long(offset)\n    frame.scan.set_long(offset, 0)\n    frame = _movement_test_long(state, frame, 0)"}})

DECLARATIONS.update({'merge_city_ownership_side_resources_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 132138)\nframe = first_replace(frame, roster=state.table_at(4294964886).cursor(), candidates=state.table_at(4294964890).cursor(), controller=state.table_at(4294964894).cursor(), scan=state.table_at(4294964898).cursor())\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = first_replace(frame, roster=frame.candidates, candidates=frame.roster, controller=frame.scan, scan=frame.controller)\nframe = _city_engagement_merge_pending_resource_fields(state, frame, frame.candidates.base, frame.roster.base, True)\nreturn _city_engagement_merge_pending_resource_fields(state, frame, frame.scan.base, frame.controller.base, True)'}})

DECLARATIONS.update({'initialize_city_ownership_description_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132218)\nframe = _movement_test(state, frame, state.read(4294964736, 2), 16)\nif not frame.status & 4:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 103674, 132232)\nframe = first_replace(frame, roster=state.table_at(703518).cursor())\nframe = _movement_move_long(state, frame, 'target_x', 3221225478)\nframe = _movement_move(state, frame, 'target_y', 10, 16)\nframe = _movement_move(state, frame, 'unit', 50082, 16)\nframe = _deployment_menu_call_fields(state, frame, 158714, 132258)\nframe = _duel_menu_write_word_fields(state, frame, 4294964736, 168)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nreturn _duel_menu_write_word_fields(state, frame, 4294954962, 8)"}})

DECLARATIONS.update({'advance_city_ownership_description_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132276)\nframe = _deployment_menu_call_fields(state, frame, 103674, 132282)\nframe = _movement_test(state, frame, state.read(4294954962, 2), 16)\nif not frame.status & 4:\n    frame = _duel_menu_change_word_fields(state, frame, 4294954962, -1)\n    frame = _movement_compare(state, frame, state.read(4294954962, 2), 8, 16)\n    if not frame.status & 5:\n        frame = _duel_menu_write_word_fields(state, frame, 4294954962, 8)\nelse:\n    frame = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\n    if not frame.status & 4:\n        frame = _movement_move(state, frame, 'target_x', 172, 16)\n        frame = _deployment_menu_call_fields(state, frame, 32906, 132332)\n        frame = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\n        frame = _duel_menu_write_word_fields(state, frame, 4294964144, state.read(4294964066, 2))\n        frame = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\n        frame = _duel_menu_write_word_fields(state, frame, 4294964754, 1030)\n        frame = _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)\n        frame = first_replace(frame, roster=state.table_at(132402).cursor())\n        frame = _movement_move_long(state, frame, 'target_x', 3221225478)\n        frame = _movement_move(state, frame, 'target_y', 10, 16)\n        frame = _movement_move(state, frame, 'unit', 50082, 16)\n        return _deployment_menu_call_fields(state, frame, 158714, 132382)\nframe = _deployment_menu_call_fields(state, frame, 132442, 132392)\nreturn _deployment_menu_call_fields(state, frame, 132612, 132398)"}})

DECLARATIONS.update({'_city_ownership_cursor_step_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, step: int', 'returns': 'FirstDeploymentFrame', 'flow': "if step not in (-1, 1):\n    raise ValueError('actual ownership cursor direction required')\nprevious = state.read(4294965008, 2)\nframe, changed = _movement_binary_flags(state, frame, previous, 1, 16, step < 0)\nstate.write(4294965008, 2, changed)\nreturn frame"}})

DECLARATIONS.update({'move_city_ownership_command_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132442)\nframe = _deployment_menu_call_fields(state, frame, 132544, 132446)\nif frame.status & 1:\n    return _duel_menu_write_word_fields(state, frame, 4294965008, 0, True)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    return _duel_menu_write_word_fields(state, frame, 4294964744, 1)\nframe = _duel_menu_change_word_fields(state, frame, 4294964744, -1)\nif not frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964744, 12)\nframe = _movement_bit(state, frame, low8(frame.target_x), 1)\nif frame.status & 4:\n    frame = _movement_test(state, frame, state.read(4294965008, 2), 16)\n    if frame.status & 4:\n        return _duel_menu_write_word_fields(state, frame, 4294965008, 2)\n    return _city_ownership_cursor_step_fields(state, frame, -1)\nframe = _movement_compare(state, frame, state.read(4294965008, 2), 2, 16)\nif frame.status & 1:\n    return _city_ownership_cursor_step_fields(state, frame, 1)\nreturn _duel_menu_write_word_fields(state, frame, 4294965008, 0, True)"}})

DECLARATIONS.update({'test_city_ownership_selected_leader_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 132544)\nframe = first_replace(frame, roster=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _movement_add_word(state, frame, 'target_x', state.read(4294964824, 2))\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nfor address in (4294964876, 4294964878):\n    frame = _movement_move(state, frame, 'target_y', state.read(address, 2), 16)\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\n    frame = _movement_compare(state, frame, low16(frame.target_x), frame.roster.word(low16(frame.target_y)), 16)\n    if frame.status & 4:\n        state.sr |= 1\n        return first_replace(frame, status=state.sr & 31)\nstate.sr &= 65534\nreturn first_replace(frame, status=state.sr & 31)"}})

