DECLARATIONS.update({'resume_city_result_control_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133424)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 131844, 133436)\nframe = _movement_test(state, frame, state.read(4294964480, 2), 16)\nif frame.status & 8:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 14)\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nfor address in (4294964066, 4294964088, 4294964824):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _movement_move(state, frame, 'target_x', 284, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 133486)"}})

DECLARATIONS.update({'_city_result_write_affiliations_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "while True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _settlement_write_byte_fields(state, frame, frame.candidates, low8(frame.target_x), low16(frame.target_y))"}})

DECLARATIONS.update({'assign_city_result_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133496)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_result_write_affiliations_fields(state, frame)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nreturn _deployment_menu_call_fields(state, frame, 133534, 133532)"}})

DECLARATIONS.update({'remove_city_result_opposing_head_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133534)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = first_replace(frame, candidates=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)\n    if frame.status & 4:\n        break\nframe = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.candidates, 255, low16(frame.target_y))\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, member, -4)\n    if frame.status & 8:\n        return frame"}})

DECLARATIONS.update({'prepare_city_result_surplus_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 133598)\nframe = _deployment_menu_call_fields(state, frame, 133608, 133602)\nreturn _duel_menu_change_word_fields(state, frame, 4294964066, 1)'}})

DECLARATIONS.update({'_city_result_mark_value_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, bit: int', 'returns': 'FirstDeploymentFrame', 'flow': "if bit not in (7, 14):\n    raise ValueError('actual city affiliation or surplus marker required')\nmask = 1 << bit\nframe = _postbattle_bit_fields(frame, bool(frame.target_x & mask))\nstate.sr = state.sr & 65504 | frame.status\nreturn first_replace(frame, target_x=frame.target_x | mask)"}})

DECLARATIONS.update({'_city_result_collect_surplus_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, source: str', 'returns': 'FirstDeploymentFrame', 'flow': "if source not in ('controller', 'roster', 'candidates'):\n    raise ValueError('actual survivor or selected-side roster required')\nwhile True:\n    cursor = frame.controller if source == 'controller' else frame.roster if source == 'roster' else frame.candidates\n    member = cursor.word()\n    frame = first_replace(frame, **{source: cursor.advance(2)})\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _movement_adjust_word(state, frame, 'distance', 1)\n    if source != 'controller':\n        frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.unit), 16)\n        if frame.status & 4:\n            continue\n    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.count), 16)\n    if frame.status & 4:\n        continue\n    frame = _city_result_mark_value_fields(state, frame, 14)\n    frame = _settlement_store_word_fields(state, frame, frame.scan, 0, low16(frame.target_x))\n    frame = first_replace(frame, scan=frame.scan.advance(2))\n    frame = _movement_adjust_word(state, frame, 'offset_x', 1)"}})

DECLARATIONS.update({'build_city_result_surplus_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133608)\nframe = first_replace(frame, roster=state.table_at(4294944080).cursor(), candidates=state.table_at(4294944122).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = first_replace(frame, roster=state.table_at(4294944164).cursor(), candidates=state.table_at(4294944206).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\nframe = first_replace(frame, controller=state.table_at(4294960704).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'unit', frame.controller.word(low16(frame.target_x)), 16)\nframe = first_replace(frame, controller=state.table_at(4294964318).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'count', frame.controller.word(low16(frame.target_x)), 16)\nframe = first_replace(frame, controller=state.table_at(4294946600).cursor(), scan=state.table_at(4294946646).cursor())\nframe = _movement_move(state, frame, 'distance', 0, 16)\nframe = _movement_move(state, frame, 'offset_x', 0, 16)\nfor source in ('controller', 'roster', 'candidates'):\n    frame = _city_result_collect_surplus_fields(state, frame, source)\nframe = _movement_compare(state, frame, low16(frame.distance), 10, 16)\nif frame.status & 5:\n    return _duel_menu_write_word_fields(state, frame, 4294946646, 65535)\nreturn _deployment_menu_call_fields(state, frame, 133788, 133786)"}})

DECLARATIONS.update({'sort_city_result_surplus_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133788)\nframe = first_replace(frame, roster=state.table_at(4294951680).cursor())\nframe = _special_action_sub_word(state, frame, 'offset_x', 2)\nwhile True:\n    frame = _movement_move(state, frame, 'target_x', low16(frame.offset_x), 16)\n    frame = first_replace(frame, candidates=state.table_at(4294946646).cursor())\n    while True:\n        member = frame.candidates.word()\n        frame = first_replace(frame, candidates=frame.candidates.advance(2))\n        frame = _movement_move(state, frame, 'target_y', member, 16)\n        frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n        frame = _movement_move(state, frame, 'count', frame.roster.byte(low16(frame.target_y)), 8)\n        frame = _movement_move(state, frame, 'unit', frame.candidates.word(), 16)\n        frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)\n        frame = _movement_compare(state, frame, low8(frame.count), frame.roster.byte(low16(frame.unit)), 8)\n        if not frame.status & 5:\n            frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, frame.candidates.word(), -2)\n            frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_y))\n        remaining = u16(low16(frame.target_x) - 1)\n        frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n        if remaining == 65535:\n            break\n    frame = _movement_adjust_word(state, frame, 'offset_x', -1)\n    if frame.status & 4:\n        break\nframe = first_replace(frame, scan=state.table_at(4294946646).cursor())\nframe = _special_action_sub_word(state, frame, 'distance', 10)\nframe = _city_engagement_record_shift_fields(state, frame, 'distance', 1)\nreturn _settlement_store_word_fields(state, frame, frame.scan, low16(frame.distance), 65535)"}})

DECLARATIONS.update({'commit_city_result_surplus_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 133856)\nframe = _deployment_menu_call_fields(state, frame, 133868, 133860)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 28)'}})

DECLARATIONS.update({'mark_city_result_surplus_affiliations_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133868)\nframe = _movement_test(state, frame, state.read(4294946646, 2), 16)\nif frame.status & 8:\n    return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_result_mark_value_fields(state, frame, 7)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor(), candidates=state.table_at(4294953984).cursor())\nreturn _city_result_write_affiliations_fields(state, frame)"}})

DECLARATIONS.update({'preserve_city_result_reserved_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, entry: int', 'returns': 'FirstDeploymentFrame', 'flow': "if entry not in (133910, 133912, 134236, 134556, 134558, 134560):\n    raise ValueError('confirmed original reserved RTS entry required')\nreturn _resource_cost_frame(state, frame, entry)"}})

DECLARATIONS.update({'_city_result_amount_plan': {'signature': 'kind: str', 'returns': 'tuple', 'flow': "if kind == 'first':\n    return (133914, 4294964122, 4294964204, 4294964126, 4294964212, 134082)\nif kind == 'second':\n    return (134238, 4294964464, 4294964466, 4294964154, 4294964216, 134402)\nraise ValueError('actual first or second result resource required')"}})

DECLARATIONS.update({'_edit_city_result_amount_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, kind: str', 'returns': 'FirstDeploymentFrame', 'flow': "entry, selection, minimum, amount, maximum, steps = _city_result_amount_plan(kind)\nframe = _resource_cost_frame(state, frame, entry)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 12, 16)\nif not frame.status & 4:\n    frame = _duel_menu_change_word_fields(state, frame, 4294964744, -1)\n    if not frame.status & 4:\n        return frame\n    frame = _duel_menu_write_word_fields(state, frame, 4294964744, 12)\n    frame = _duel_commit_bit_fields(state, frame, 'target_x', 3)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'target_x', state.read(selection, 2), 16)\n        frame = _movement_adjust_word(state, frame, 'target_x', -1)\n        if frame.status & 1:\n            return frame\n        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(minimum, 2), 16)\n        if frame.status & 1:\n            return frame\n        return _duel_menu_write_word_fields(state, frame, selection, low16(frame.target_x))\n    frame = _movement_compare(state, frame, state.read(selection, 2), 5, 16)\n    if not frame.status & 1:\n        return frame\n    frame, changed = _movement_binary_flags(state, frame, state.read(selection, 2), 1, 16)\n    state.write(selection, 2, changed)\n    return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    return _duel_menu_write_word_fields(state, frame, 4294964744, 1)\nframe = _duel_menu_change_word_fields(state, frame, 4294964744, -1)\nif not frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964744, 12)\nframe = _duel_commit_bit_fields(state, frame, 'target_x', 1)\ndecrease = not frame.status & 4\nframe = _movement_move_long(state, frame, 'target_x', state.read(amount, 4))\nframe = _movement_move(state, frame, 'target_y', state.read(selection, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 2)\nstep = state.read(u32(steps + s16(low16(frame.target_y))), 4)\nframe = _movement_arithmetic_long(state, frame, 'target_x', step, decrease)\nif decrease:\n    if frame.status & 1:\n        return frame\nelse:\n    frame = _first_compare_long(frame, frame.target_x, state.read(maximum, 4))\n    state.sr = state.sr & 65504 | frame.status\n    if not frame.status & 5:\n        return frame\nstate.write(amount, 4, frame.target_x)\nreturn _movement_test_long(state, frame, frame.target_x)"}})

DECLARATIONS.update({'edit_city_result_first_amount_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "return _edit_city_result_amount_fields(state, frame, 'first')"}})

DECLARATIONS.update({'edit_city_result_second_amount_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "return _edit_city_result_amount_fields(state, frame, 'second')"}})

DECLARATIONS.update({'_append_city_result_amount_packet_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, kind: str', 'returns': 'FirstDeploymentFrame', 'flow': "if kind == 'first':\n    entry, amount, selection, header, continuation = (134106, 4294964126, 4294964122, 50724, 134126)\nelif kind == 'second':\n    entry, amount, selection, header, continuation = (134426, 4294964154, 4294964464, 51108, 134446)\nelse:\n    raise ValueError('actual result amount packet required')\nframe = _resource_cost_frame(state, frame, entry)\nframe = _movement_move_long(state, frame, 'target_x', state.read(amount, 4))\nframe = _movement_move(state, frame, 'target_y', 50054, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = first_replace(frame, auxiliary=state.table_at(4294955776).cursor())\nframe = _deployment_menu_call_fields(state, frame, 75530, continuation)\nframe = first_replace(frame, roster=state.table_at(4294955264).cursor())\nframe = first_replace(frame, roster=frame.roster.advance(s16(state.read(4294963994, 2))))\nfor value in (6, header):\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, value)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\nframe = first_replace(frame, candidates=state.table_at(4294955776).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_y', 5, 16)\nwhile True:\n    digit = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'unit', digit, 16)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(selection, 2), 16)\n        frame = _movement_move(state, frame, 'unit', 49153 if frame.status & 1 else 50054, 16)\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.unit))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    remaining = u16(low16(frame.target_y) - 1)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, remaining))\n    if remaining == 65535:\n        break\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 0, clear=True)\nframe, advanced = _movement_binary_flags(state, frame, state.read(4294963994, 2), 16, 16)\nstate.write(4294963994, 2, advanced)\nreturn frame"}})

