DECLARATIONS.update({'_draw_city_result_amount_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, kind: str', 'returns': 'FirstDeploymentFrame', 'flow': "if kind == 'first':\n    entry, sprite, x, selection, continuation = (134192, 134228, 96, 4294964122, 134226)\nelif kind == 'second':\n    entry, sprite, x, selection, continuation = (134512, 134548, 120, 4294964464, 134546)\nelse:\n    raise ValueError('actual amount cursor required')\nframe = _resource_cost_frame(state, frame, entry)\nframe = _postbattle_bit_fields(frame, bool(state.read(4294964001, 1) & 16))\nstate.sr = state.sr & 65504 | frame.status\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(sprite).cursor())\nframe = _movement_move(state, frame, 'target_x', x, 16)\nframe = _movement_move(state, frame, 'target_y', state.read(selection, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 3)\nframe = _movement_add_word(state, frame, 'target_y', 144)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _deployment_menu_call_fields(state, frame, 44040, continuation)"}})

