DECLARATIONS.update({'remove_city_result_opposing_head_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 133534)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964876, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = first_replace(frame, candidates=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)\n    if frame.status & 4:\n        break\nframe = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.candidates, 255, low16(frame.target_y))\nreturn _city_resources_compact_roster_tail_fields(state, frame)"}})

DECLARATIONS.update({'_city_resources_store_long_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, value: int, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if address not in (4294946804, 4294964212, 4294964216, 4294964126, 4294964154, 4294964886, 4294964894, 4294964890, 4294964898, 4294964928):\n    raise ValueError('actual city resource destination required')\nif clear:\n    if address not in (4294964126, 4294964154) or value != 0:\n        raise ValueError('actual cleared quantity cell required')\n    state.read(address, 4)\nstate.write(address, 4, u32(value))\nreturn _movement_test_long(state, frame, value)"}})

DECLARATIONS.update({'prepare_city_resources_total_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 134590)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964894, 4294964886) if frame.status & 4 else (4294964890, 4294964898)\nframe = _movement_move_long(state, frame, 'target_x', state.read(first, 4))\nframe = _movement_arithmetic_long(state, frame, 'target_x', state.read(second, 4))\nreturn _city_resources_store_long_fields(state, frame, 4294946804, frame.target_x)"}})

DECLARATIONS.update({'build_city_resources_selectable_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 134626)\nframe = first_replace(frame, candidates=state.table_at(4294964480).cursor())\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nroster, affiliation = (4294944080, 4294964876) if frame.status & 4 else (4294944164, 4294964878)\nframe = first_replace(frame, roster=state.table_at(roster).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(affiliation, 2), 16)\nframe = first_replace(frame, controller=state.table_at(4294960704).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'target_y', frame.controller.word(low16(frame.target_y)), 16)\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.unit), 16)\n    if frame.status & 4:\n        continue\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.unit))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\nframe = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_x))\nfor address in (4294964824, 4294964088):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _movement_test(state, frame, state.read(4294964480, 2), 16)\nif frame.status & 8:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 23)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, state.read(4294964066, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nfor address in (4294964066, 4294964946):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _movement_move(state, frame, 'target_x', 291, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 134766)"}})

DECLARATIONS.update({'_city_resources_write_port_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, value: int', 'returns': 'FirstDeploymentFrame', 'flow': "if address not in (12582916, 12582912):\n    raise ValueError('actual resource-panel VDP port required')\nif state.hardware is None or not state.hardware.contains(address, 4):\n    raise MovementContinuationBoundary(address, frame, 'original resource-panel LONG write requires actual explicitly supplied VDP port')\nstate.write(address, 4, u32(value))\nreturn _movement_test_long(state, frame, value)"}})

DECLARATIONS.update({'upload_city_resources_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 134768)\nframe = _deployment_menu_call_fields(state, frame, 103674, 134772)\nframe = _duel_menu_write_word_fields(state, frame, 4294964882, 50054)\nframe = _duel_menu_write_word_fields(state, frame, 4294964884, 49153)\nfor carrier, value in (('target_x', 1), ('target_y', 3), ('count', 1)):\n    frame = _movement_move(state, frame, carrier, value, 16)\nframe = first_replace(frame, roster=state.table_at(703598).cursor(), candidates=state.table_at(4294955776).cursor())\nframe = _deployment_menu_call_fields(state, frame, 44682, 134812)\nframe = _city_resources_write_port_fields(state, frame, 12582916, 1084227586)\nframe = first_replace(frame, candidates=state.table_at(4294955776).cursor())\nframe = _movement_move(state, frame, 'count', 63, 16)\nwhile True:\n    tiles = frame.candidates.long()\n    frame = first_replace(frame, candidates=frame.candidates.advance(4))\n    frame = _city_resources_write_port_fields(state, frame, 12582912, tiles)\n    remaining = u16(low16(frame.count) - 1)\n    frame = first_replace(frame, count=replace_word(frame.count, remaining))\n    if remaining == 65535:\n        break\nreturn _duel_menu_change_word_fields(state, frame, 4294964066, 1)"}})

DECLARATIONS.update({'_city_resources_append_title_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, phase: str, second: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if phase not in ('setup', 'commit') or type(second) is not bool:\n    raise ValueError('actual resource-title phase and field required')\ntitle = (703678 if second else 703602) if phase == 'setup' else 134562\ncontinuation = (134946 if second else 134912) if phase == 'setup' else 135252 if second else 135228\nframe = first_replace(frame, roster=state.table_at(title).cursor())\nframe = _movement_move_long(state, frame, 'target_x', 3221225484)\nframe = _movement_move(state, frame, 'target_y', 7 if second else 6, 16)\nframe = _movement_move(state, frame, 'unit', 50460 if second else 49564, 16)\nreturn _deployment_menu_call_fields(state, frame, 158714, continuation)"}})

DECLARATIONS.update({'initialize_city_resources_quantity_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 134846)\nframe = _deployment_menu_call_fields(state, frame, 103674, 134850)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964886, 4294964894) if frame.status & 4 else (4294964890, 4294964898)\nframe = _city_resources_store_long_fields(state, frame, 4294964212, state.read(first, 4))\nframe = _city_resources_store_long_fields(state, frame, 4294964216, state.read(second, 4))\nframe = _city_resources_append_title_fields(state, frame, 'setup', False)\nfor address in (4294964126, 4294964154):\n    frame = _city_resources_store_long_fields(state, frame, address, 0, True)\nframe = _city_resources_append_title_fields(state, frame, 'setup', True)\nfor maximum, minimum, continuation in ((4294964212, 4294964204, 134954), (4294964216, 4294964466, 134966)):\n    frame = _movement_move_long(state, frame, 'target_x', state.read(maximum, 4))\n    frame = _deployment_menu_call_fields(state, frame, 135004, continuation)\n    frame = _duel_menu_write_word_fields(state, frame, minimum, low16(frame.target_x))\nfor address in (4294964122, 4294964464):\n    frame = _duel_menu_write_word_fields(state, frame, address, 5)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = first_replace(frame, roster=state.table_at(4294964480).cursor())\nreturn _duel_menu_write_word_fields(state, frame, 4294964134, frame.roster.word(low16(frame.target_x)))"}})

DECLARATIONS.update({'choose_city_resources_minimum_digit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135004)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nfor threshold in (10, 100, 1000, 10000, 100000):\n    frame = _first_compare_long(frame, frame.target_x, threshold)\n    state.sr = state.sr & 65504 | frame.status\n    if frame.status & 1:\n        break\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\nframe = _movement_move(state, frame, 'target_x', 5, 16)\nreturn _special_action_sub_word(state, frame, 'target_x', low16(frame.target_y))"}})

DECLARATIONS.update({'_city_resources_edit_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, second: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(second) is not bool:\n    raise ValueError('actual resource-panel field required')\nentry = 135138 if second else 135064\nframe = _resource_cost_frame(state, frame, entry)\nif second:\n    children = ((103674, 135142), (134238, 135146), (134426, 135150), (134512, 135154))\nelse:\n    children = ((103674, 135068), (133914, 135072), (134106, 135076), (134192, 135080))\nfor target, continuation in children:\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', 172, 16)\n    frame = _deployment_menu_call_fields(state, frame, 32906, 135172 if second else 135098)\n    return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 4)\nif frame.status & 4:\n    return frame\nif second:\n    return _duel_menu_change_word_fields(state, frame, 4294964066, -1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 2)"}})

DECLARATIONS.update({'edit_city_resources_first_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _city_resources_edit_panel_fields(state, frame, False)'}})

DECLARATIONS.update({'edit_city_resources_second_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _city_resources_edit_panel_fields(state, frame, True)'}})

DECLARATIONS.update({'commit_city_resources_quantities_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135192)\nfor target, continuation in ((135276, 135196), (135464, 135200), (135510, 135204)):\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\nframe = _city_resources_append_title_fields(state, frame, 'commit', False)\nframe = _city_resources_append_title_fields(state, frame, 'commit', True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 21)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1030)\nreturn _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)"}})

DECLARATIONS.update({'award_city_resources_selected_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135276)\nframe = first_replace(frame, candidates=state.table_at(4294951680).cursor())\nframe = _movement_move(state, frame, 'choice', state.read(4294964134, 2), 16)\nframe = _movement_compare(state, frame, frame.candidates.byte(low16(frame.choice)), 90, 8)\nif not frame.status & 1:\n    return frame\nframe = first_replace(frame, roster=state.table_at(4294952704).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.choice)), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = first_replace(frame, controller=state.table_at(135444).cursor())\nframe = _movement_move(state, frame, 'target_x', frame.controller.word(low16(frame.target_x)), 16)\nframe = _movement_move_long(state, frame, 'target_y', state.read(4294946804, 4))\nframe = _movement_divu_word(state, frame, 'target_y', low16(frame.target_x), 135324)\nframe = _movement_move_long(state, frame, 'unit', state.read(4294964126, 4))\nframe = _movement_arithmetic_long(state, frame, 'unit', state.read(4294964154, 4))\nframe = _movement_multiply_word(state, frame, 'unit', 10)\nframe = _movement_divu_word(state, frame, 'unit', low16(frame.target_y), 135338)\nframe = _deployment_menu_call_fields(state, frame, 33748, 135346)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _special_action_swap(state, frame, 'target_x')\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nfor threshold in (5, 8, 12, 15):\n    frame = _movement_compare(state, frame, low16(frame.unit), threshold, 16)\n    if frame.status & 5:\n        break\n    frame = _movement_add_word(state, frame, 'target_y', 2)\nbonus = state.read(u32(135454 + s16(low16(frame.target_y))), 2)\nframe = _movement_move(state, frame, 'target_y', bonus, 16)\nif frame.status & 4:\n    return frame\nframe = _movement_add_word(state, frame, 'target_y', low16(frame.target_x))\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.choice)), 8)\nframe = _movement_add_word(state, frame, 'unit', low16(frame.target_y))\nif frame.status & 8:\n    frame = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_compare(state, frame, low16(frame.unit), 100, 16)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'unit', 100, 16)\nreturn _settlement_write_byte_fields(state, frame, frame.candidates, low8(frame.unit), low16(frame.choice))"}})

DECLARATIONS.update({'debit_city_resources_quantities_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135464)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964886, 4294964894) if frame.status & 4 else (4294964890, 4294964898)\nframe = first_replace(frame, roster=state.table_at(first).cursor(), candidates=state.table_at(second).cursor())\nframe = _movement_move_long(state, frame, 'target_x', frame.roster.long())\nframe = _movement_arithmetic_long(state, frame, 'target_x', state.read(4294964126, 4), True)\nframe = _city_resources_store_long_fields(state, frame, frame.roster.base, frame.target_x)\nframe = _movement_move_long(state, frame, 'target_x', frame.candidates.long())\nframe = _movement_arithmetic_long(state, frame, 'target_x', state.read(4294964154, 4), True)\nreturn _city_resources_store_long_fields(state, frame, frame.candidates.base, frame.target_x)"}})

DECLARATIONS.update({'_city_resources_compact_roster_tail_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'while True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, member, -4)\n    if frame.status & 8:\n        return frame'}})

DECLARATIONS.update({'remove_city_resources_selected_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135510)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294964480).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)\n    if frame.status & 4:\n        break\nframe = _city_resources_compact_roster_tail_fields(state, frame)\nframe, remaining = _movement_binary_flags(state, frame, state.read(4294964790, 2), 1, 16, True)\nstate.write(4294964790, 2, remaining)\nreturn frame"}})

DECLARATIONS.update({'prepare_city_resources_selected_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135540)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, state.read(4294964134, 2))\nframe = _movement_move(state, frame, 'target_x', 292, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, 135564)\nreturn _duel_menu_write_word_fields(state, frame, 4294964818, 1)"}})

DECLARATIONS.update({'confirm_city_resources_next_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135572)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _movement_test(state, frame, state.read(4294964480, 2), 16)\nif frame.status & 8:\n    return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 16)\nfor address in (4294964088, 4294964824):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 0, True)\nframe = _movement_move(state, frame, 'target_x', 291, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 135632)"}})

DECLARATIONS.update({'prepare_city_resources_roster_limit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135642)\nframe = _deployment_menu_call_fields(state, frame, 135716, 135646)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.count))\nframe = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\nif frame.status & 5:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 28)\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_y))\nframe = _duel_menu_write_word_fields(state, frame, 4294965010, low16(frame.count))\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nfor address in (4294964088, 4294964824):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _city_resources_store_long_fields(state, frame, 4294964928, 703762)\nframe = _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)\nframe = _deployment_menu_call_fields(state, frame, 135822, 135694)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 135704)"}})

DECLARATIONS.update({'build_city_resources_expanded_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135716)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nroster, trailing, affiliation = (4294944080, 4294944206, 4294964876) if frame.status & 4 else (4294944164, 4294944122, 4294964878)\nframe = first_replace(frame, roster=state.table_at(roster).cursor(), scan=state.table_at(trailing).cursor())\nframe = _movement_move(state, frame, 'unit', state.read(affiliation, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 1)\nframe = first_replace(frame, controller=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'unit', frame.controller.word(low16(frame.unit)), 16)\nframe = first_replace(frame, candidates=state.table_at(4294946646).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'count', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.unit), 16)\n    if frame.status & 4:\n        frame = _movement_adjust_word(state, frame, 'count', 1)\n        continue\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)\nwhile True:\n    member = frame.scan.word()\n    frame = first_replace(frame, scan=frame.scan.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, member)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    if frame.status & 8:\n        return frame\n    frame = _movement_adjust_word(state, frame, 'target_y', 1)"}})

DECLARATIONS.update({'test_city_resources_other_affiliated_city_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135822)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\naffiliation = 4294964876 if frame.status & 4 else 4294964878\nframe = _movement_move(state, frame, 'target_x', state.read(affiliation, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294964264).cursor())\nframe = _movement_move(state, frame, 'unit', 39, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'count', frame.roster.byte(low16(frame.unit)), 8)\n    frame = _movement_compare(state, frame, low8(frame.count), low8(frame.target_x), 8)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, low8(frame.unit), low8(frame.target_y), 8)\n        if not frame.status & 4:\n            frame = _movement_move(state, frame, 'target_x', 293, 16)\n            state.sr &= 65534\n            return first_replace(frame, status=frame.status & 30)\n    remaining = u16(low16(frame.unit) - 1)\n    frame = first_replace(frame, unit=replace_word(frame.unit, remaining))\n    if remaining == 65535:\n        frame = _movement_move(state, frame, 'target_x', 293, 16)\n        state.sr |= 1\n        return first_replace(frame, status=frame.status | 1)"}})

APPROVED.setdefault('business_city', set()).update({'_special_action_shift_long', '_special_action_swap'})
APPROVED.setdefault('services', set()).update({'_movement_multiply_word', '_movement_divu_word'})

DECLARATIONS.update({'highbank_coordinate_live_state_28': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState28Input', 'returns': 'HighbankCoordinateLiveState28Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState28Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, roster=inputs.destination.cursor())\nframe = confirm_city_member_selection_fields(state, frame)\nreturn HighbankCoordinateLiveState28Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

