DECLARATIONS.update({'highbank_coordinate_live_state_28_alternate_1': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState28Alternate1Input', 'returns': 'HighbankCoordinateLiveState28Alternate1Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState28Alternate1Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field, unit=inputs.tile, roster=inputs.destination.cursor())\nframe = confirm_city_member_selection_fields(state, frame)\nreturn HighbankCoordinateLiveState28Alternate1Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_city_members_counter_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, step: int', 'returns': 'FirstDeploymentFrame', 'flow': "if address not in (4294964088, 4294964868) or step not in (-1, 1):\n    raise ValueError('actual city member counter required')\nframe, value = _movement_binary_flags(state, frame, state.read(address, 2), 1, 16, step < 0)\nstate.write(address, 2, value)\nreturn frame"}})

DECLARATIONS.update({'_city_members_selection_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carrier: str, toggle: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if carrier not in ('target_x', 'target_y') or type(toggle) is not bool:\n    raise ValueError('actual member selection marker required')\nvalue = frame.carrier(carrier)\nframe = _postbattle_bit_fields(frame, bool(value & 16384))\nstate.sr = state.sr & 65504 | frame.status\nreturn first_replace(frame, **{carrier: value ^ 16384}) if toggle else frame"}})

DECLARATIONS.update({'confirm_city_member_selection_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 135974)\nframe = _deployment_menu_call_fields(state, frame, 136112, 135978)\nframe = _deployment_menu_call_fields(state, frame, 136236, 135982)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _deployment_menu_call_fields(state, frame, 32906, 136002)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964790, 2), 16)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964790, 2), 16)\n    frame = _special_action_sub_word(state, frame, 'target_x', state.read(4294964868, 2))\n    frame = _movement_add_word(state, frame, 'target_x', state.read(4294965010, 2))\n    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\n    return frame if not frame.status & 5 else _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964736, 172)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)\nframe = _city_members_selection_bit_fields(state, frame, 'target_y', True)\nif not frame.status & 4:\n    frame = _city_members_counter_fields(state, frame, 4294964868, -1)\n    return _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.target_y))\nframe = _movement_compare(state, frame, state.read(4294964868, 2), 10, 16)\nif not frame.status & 1:\n    return _city_members_selection_bit_fields(state, frame, 'target_y', True)\nframe = _city_members_counter_fields(state, frame, 4294964868, 1)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.target_y))\nreturn _deployment_menu_call_fields(state, frame, 100424, 136062)"}})

DECLARATIONS.update({'scroll_city_member_selection_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136112)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    return _duel_menu_write_word_fields(state, frame, 4294964744, 1)\nframe = _duel_menu_change_word_fields(state, frame, 4294964744, -1)\nif not frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964744, 12)\nframe = _duel_commit_bit_fields(state, frame, 'target_x', 1)\nif frame.status & 4:\n    frame = _movement_test(state, frame, state.read(4294964088, 2), 16)\n    if frame.status & 4:\n        return frame\n    frame = _city_members_counter_fields(state, frame, 4294964088, -1)\nelse:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964790, 2), 16)\n    if frame.status & 4:\n        return frame\n    frame = _city_members_counter_fields(state, frame, 4294964088, 1)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _special_action_sub_word(state, frame, 'target_x', 2)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964790, 2), 16)\nframe = _special_action_sub_word(state, frame, 'target_y', 4)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), low16(frame.target_y), 16)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964824, 2), 16)\nif frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964824, low16(frame.target_x))\nreturn _duel_menu_write_word_fields(state, frame, 4294964736, 172)"}})

DECLARATIONS.update({'draw_city_member_selection_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136236)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    frame = _duel_menu_byte_bit_fields(state, frame, 4294964001, 3)\n    if not frame.status & 4:\n        return frame\nframe = first_replace(frame, roster=state.table_at(136298).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964088, 2), 16)\nframe = _special_action_sub_word(state, frame, 'target_x', state.read(4294964824, 2))\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_add_word(state, frame, 'target_x', low16(frame.unit))\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 3)\nframe = _movement_add_word(state, frame, 'target_x', 16)\nframe = _movement_move(state, frame, 'target_y', 224, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _deployment_menu_call_fields(state, frame, 44040, 136296)"}})

DECLARATIONS.update({'commit_city_selected_member_group_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136396)\nframe = _deployment_menu_call_fields(state, frame, 135822, 136400)\nif frame.status & 1:\n    return _deployment_menu_call_fields(state, frame, 136606, 136466)\nframe = _deployment_menu_call_fields(state, frame, 136468, 136408)\nframe = _deployment_menu_call_fields(state, frame, 136646, 136412)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    frame = _city_members_selection_bit_fields(state, frame, 'target_x')\n    if not frame.status & 4:\n        break\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 30)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1030)\nreturn _duel_menu_write_word_fields(state, frame, 4294964074, 0, True)"}})

DECLARATIONS.update({'mark_city_selected_member_affiliations_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136606)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_result_mark_value_fields(state, frame, 7)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _city_members_selection_bit_fields(state, frame, 'target_y')\n    if frame.status & 4:\n        continue\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n    frame = _settlement_write_byte_fields(state, frame, frame.candidates, low8(frame.target_x), low16(frame.target_y))"}})

DECLARATIONS.update({'_city_members_cap_packet_share_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, second: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(second) is not bool:\n    raise ValueError('actual first or second packet resource required')\nresource, limit = ('count', 'target_y') if second else ('unit', 'target_x')\nframe = _movement_compare(state, frame, low16(frame.carrier(resource)), low16(frame.carrier(limit)), 16)\nif frame.status & 5:\n    return frame\nframe = _movement_move_long(state, frame, resource, frame.carrier(limit))\nframe = _recruitment_right_long(state, frame, resource, 3)\nframe = _movement_move_long(state, frame, 'target_x', frame.carrier(resource))\nframe = _special_action_shift_long(state, frame, resource, 1)\nreturn _movement_arithmetic_long(state, frame, resource, frame.target_x)"}})

DECLARATIONS.update({'allocate_city_selected_group_resources_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136646)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964886, 4294964894) if frame.status & 4 else (4294964890, 4294964898)\nframe = _movement_move_long(state, frame, 'target_x', state.read(first, 4))\nframe = _movement_move_long(state, frame, 'target_y', state.read(second, 4))\nframe = _recruitment_right_long(state, frame, 'target_x', 1)\nframe = _recruitment_right_long(state, frame, 'target_y', 1)\nframe = first_replace(frame, candidates=state.table_at(4294952960).cursor())\nframe = _movement_move_long(state, frame, 'unit', 0)\nframe = _movement_move(state, frame, 'count', 0, 16)\nframe = _movement_move(state, frame, 'count', frame.roster.byte(), 8)\nframe = _movement_adjust_word(state, frame, 'count', -1)\nwhile True:\n    frame = _movement_move(state, frame, 'distance', 0, 16)\n    frame = _movement_move(state, frame, 'distance', frame.roster.byte(low16(frame.count), 13), 8)\n    frame = _city_engagement_record_shift_fields(state, frame, 'distance', 2)\n    frame = _movement_arithmetic_long(state, frame, 'unit', frame.candidates.long(low16(frame.distance)))\n    frame = _movement_arithmetic_long(state, frame, 'unit', 100)\n    remaining = u16(low16(frame.count) - 1)\n    frame = first_replace(frame, count=replace_word(frame.count, remaining))\n    if remaining == 65535:\n        break\nframe = _movement_divu_word(state, frame, 'unit', 10, 136714)\nframe = _movement_move_long(state, frame, 'unit', frame.unit & 65535)\nframe = _movement_move_long(state, frame, 'count', frame.unit)\nframe = _special_action_shift_long(state, frame, 'unit', 1)\nframe = _movement_arithmetic_long(state, frame, 'unit', frame.count)\nframe = _special_action_shift_long(state, frame, 'unit', 1)\nframe = _movement_move(state, frame, 'count', low16(frame.unit), 16)\nframe = _city_members_cap_packet_share_fields(state, frame, False)\nframe = _city_members_cap_packet_share_fields(state, frame, True)\nfor resource, first_byte in (('unit', 5), ('count', 9)):\n    frame = _movement_move_long(state, frame, 'target_x', frame.carrier(resource))\n    frame = _movement_store_packed_resource(state, frame, 'target_x', first_byte)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964886, 4294964894) if frame.status & 4 else (4294964890, 4294964898)\nfor address, resource in ((first, 'unit'), (second, 'count')):\n    frame = _movement_move_long(state, frame, 'target_x', state.read(address, 4))\n    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.carrier(resource), True)\n    frame = _city_resources_store_long_fields(state, frame, address, frame.target_x)\nreturn frame"}})

DECLARATIONS.update({'confirm_city_selected_group_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 136870)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 139354, 136884)\nreturn _duel_menu_change_word_fields(state, frame, 4294964066, 1)'}})

DECLARATIONS.update({'transfer_city_selected_owner_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 136890)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'unit', state.read(4294964874, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nowner, other = (4294964876, 4294964878) if frame.status & 4 else (4294964878, 4294964876)\nframe = _movement_move(state, frame, 'target_x', state.read(owner, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(other, 2), 16)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.unit))\nframe = _duel_menu_write_word_fields(state, frame, 4294964086, low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, frame.roster.word(low16(frame.target_y)))\nframe = _duel_menu_write_word_fields(state, frame, 4294964806, state.read(4294964874, 2))\nframe = _movement_move(state, frame, 'target_x', 295, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nfor target, continuation in ((423666, 136972), (139614, 136978), (137040, 136982), (137002, 136988)):\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\nframe = first_replace(frame, roster=state.table_at(4294961719).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nreturn _settlement_write_byte_fields(state, frame, frame.roster, 0, low16(frame.target_x), clear=True)"}})

DECLARATIONS.update({'_city_members_clear_indexed_long_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, offset: int', 'returns': 'FirstDeploymentFrame', 'flow': "if frame.roster.base not in (4294943056, 4294961012, 4294962564, 4294962724):\n    raise ValueError('actual city record-clear table required')\nframe.roster.long(low16(offset))\nframe.roster.set_long(low16(offset), 0)\nreturn _movement_test_long(state, frame, 0)"}})

DECLARATIONS.update({'clear_city_member_matching_packet_headers_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137002)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', 255, 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\nwhile True:\n    frame = _movement_compare(state, frame, low8(frame.target_y), frame.roster.byte(low16(frame.target_x)), 8)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\n        frame = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\n        frame = _city_members_clear_indexed_long_fields(state, frame, low16(frame.unit))\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        return frame"}})

DECLARATIONS.update({'clear_city_first_side_assignment_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137040)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(4294961012).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nreturn _city_members_clear_indexed_long_fields(state, frame, low16(frame.target_x))"}})

DECLARATIONS.update({'finish_city_selected_owner_transfer_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137066)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nfor target, continuation in ((139416, 137080), (139578, 137084), (137160, 137088), (137300, 137092), (137486, 137096)):\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 512)\nfor address in (4294964066, 4294964050):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964086, 65535)\nfor source, destination in ((4294964877, 4294944290), (4294964879, 4294944291)):\n    frame = _settlement_write_byte_fields(state, frame, state.table_at(destination).cursor(), state.read(source, 1))\nframe = first_replace(frame, roster=state.table_at(4294942719).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, 0, low16(frame.target_x), clear=True)\nframe = _movement_adjust_word(state, frame, 'target_x', -1)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 3, True)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\nframe = first_replace(frame, roster=state.table_at(4294963114).cursor())\nprevious = frame.roster.byte(low16(frame.target_y))\nmask = 1 << (low8(frame.target_x) & 7)\nframe = _postbattle_bit_fields(frame, bool(previous & mask))\nstate.sr = state.sr & 65504 | frame.status\nframe.roster.set_byte(low16(frame.target_y), previous & ~mask)\nreturn frame"}})

DECLARATIONS.update({'update_city_selected_head_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137300)\nframe = first_replace(frame, roster=state.table_at(4294964318).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = first_replace(frame, candidates=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_y)), 16)\nframe = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.target_y)), 8)\nframe = _movement_compare(state, frame, low8(frame.unit), state.read(4294964875, 1), 8)\nif frame.status & 4:\n    return _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.target_y))\nframe = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.unit)), 8)\nframe = _movement_compare(state, frame, low8(frame.unit), state.read(4294964875, 1), 8)\nif not frame.status & 4:\n    return frame\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nreturn frame if not frame.status & 4 else _deployment_menu_call_fields(state, frame, 137394, 137392)"}})

DECLARATIONS.update({'select_city_best_affiliated_head_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137394)\nframe = _movement_save_longs(state, frame, ('distance', 'scan'))\nframe = first_replace(frame, scan=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'distance', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = first_replace(frame, candidates=state.table_at(4294951680).cursor())\nfor roster, continuation in ((4294944080, 137420), (4294944122, 137428), (4294944164, 137436), (4294944206, 137444)):\n    frame = first_replace(frame, controller=state.table_at(roster).cursor())\n    frame = _deployment_menu_call_fields(state, frame, 137454, continuation)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.unit))\nreturn _movement_restore_longs(state, frame, ('distance', 'scan'))"}})

DECLARATIONS.update({'scan_city_best_affiliated_head_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137454)\nwhile True:\n    member = frame.controller.word()\n    frame = first_replace(frame, controller=frame.controller.advance(2))\n    frame = _movement_move(state, frame, 'count', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'count', low16(frame.count) & 255, 16)\n    frame = _movement_compare(state, frame, low8(frame.distance), frame.scan.byte(low16(frame.count)), 8)\n    if not frame.status & 4:\n        continue\n    frame = _movement_compare(state, frame, low8(frame.target_y), frame.candidates.byte(low16(frame.count)), 8)\n    if not frame.status & 1:\n        continue\n    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.count)), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.count), 16)"}})

DECLARATIONS.update({'clear_city_affiliated_packet_resources_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137486)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.target_y)), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 63, 16)\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_x), 16)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)\n        frame = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\n        frame = _city_members_clear_indexed_long_fields(state, frame, low16(frame.unit))\n    remaining = u16(low16(frame.target_y) - 1)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, remaining))\n    if remaining == 65535:\n        break\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nfor address in (4294962564, 4294962724):\n    frame = first_replace(frame, roster=state.table_at(address).cursor())\n    frame = _city_members_clear_indexed_long_fields(state, frame, low16(frame.target_x))\nreturn frame"}})

DECLARATIONS.update({'prepare_city_affiliation_result_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137552)\nframe = _duel_menu_write_word_fields(state, frame, 4294964066, 27)\nframe = _movement_move(state, frame, 'target_x', 294, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nframe = _deployment_menu_call_fields(state, frame, 423666, 137572)\nreturn _duel_menu_write_word_fields(state, frame, 4294964818, 1)"}})

DECLARATIONS.update({'dispatch_city_posttransfer_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137580)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964066, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\noffset = state.read(u32(137596 + s16(low16(frame.target_x))), 2)\nframe = _movement_move(state, frame, 'target_x', offset, 16)\ntarget = u32(137642 + s16(low16(frame.target_x)))\nreturn _deployment_menu_call_fields(state, frame, target, 137594)"}})

DECLARATIONS.update({'prepare_city_posttransfer_phase_message_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137642)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_move(state, frame, 'target_x', 312, 16)\nreturn _deployment_menu_call_fields(state, frame, 423666, 137656)"}})

DECLARATIONS.update({'confirm_city_posttransfer_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 137658)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _duel_menu_write_word_fields(state, frame, 4294964950, 2)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294946600, 65535)\nreturn _duel_menu_write_word_fields(state, frame, 4294963072, 65535)'}})

DECLARATIONS.update({'prepare_city_visible_opposing_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137692)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\nvisible = False\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        visible = True\n        break\nif not visible:\n    return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_test(state, frame, state.read(4294944206, 2), 16)\nif frame.status & 8:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, 8)\nframe = first_replace(frame, roster=state.table_at(4294944206).cursor(), candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, member)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    if frame.status & 8:\n        break\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\n    if not frame.status & 1:\n        break\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 4)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nfor address in (4294964066, 4294964088, 4294964824):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, True)\nframe = _movement_move(state, frame, 'target_x', 284, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, 137818)"}})

