DECLARATIONS.update({'_city_survivor_mark_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, primary: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(primary) is not bool:\n    raise ValueError('original survivor transfer side required')\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor())\nif primary:\n    frame = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_survivor_set_register_bit_fields(state, frame, 'target_x', 7)\nif not primary:\n    frame = first_replace(frame, candidates=state.table_at(4294953984).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        break\n    frame = _settlement_write_byte_fields(state, frame, frame.candidates, low8(frame.target_x), low16(frame.target_y))\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 22 if primary else 12)"}})

DECLARATIONS.update({'_city_survivor_prepare_limit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, primary: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(primary) is not bool:\n    raise ValueError('original survivor limit side required')\ncount_return, check_return, message_return, done = (138774, 138826, 138836, 22) if primary else (138194, 138246, 138256, 12)\nframe = _deployment_menu_call_fields(state, frame, 138268, count_return)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nframe = _movement_add_word(state, frame, 'target_y', 1)\nframe = _movement_compare(state, frame, low16(frame.target_y), 10, 16)\nif frame.status & 5:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, done)\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294965010, 1)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964088, 0, clear=True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964824, 0, clear=True)\nstate.write(4294964928, 4, 703762)\nframe = _movement_test_long(state, frame, 703762)\nframe = _duel_menu_write_word_fields(state, frame, 4294964074, 0, clear=True)\nframe = _deployment_menu_call_fields(state, frame, 135822, check_return)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, message_return)"}})

DECLARATIONS.update({'_city_survivor_prepare_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, primary: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(primary) is not bool:\n    raise ValueError('original survivor candidate side required')\naffiliation, source, empty, saved, message = (4294964876, 4294944122, 18, 14, 138568) if primary else (4294964878, 4294944206, 8, 4, 137818)\nframe = _movement_move(state, frame, 'target_x', state.read(affiliation, 2), 16)\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        break\nelse:\n    return _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = _movement_test(state, frame, state.read(source, 2), 16)\nif frame.status & 8:\n    return _duel_menu_write_word_fields(state, frame, 4294964066, empty)\nframe = first_replace(frame, roster=state.table_at(source).cursor(), candidates=state.table_at(4294964480).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, member)\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    if frame.status & 8:\n        break\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\n    if not frame.status & 1:\n        break\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, saved)\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1029)\nfor address in (4294964066, 4294964088, 4294964824):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, clear=True)\nframe = _movement_move(state, frame, 'target_x', 284, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294946688, low16(frame.target_x))\nreturn _deployment_menu_call_fields(state, frame, 423666, message)"}})

DECLARATIONS.update({'_city_survivor_relocate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, primary: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(primary) is not bool:\n    raise ValueError('original relocation entry required')\ncheck, packet, resources, failure, saved = (138860, 138868, 138872, 138926, 22) if primary else (138370, 138378, 138382, 138436, 12)\nframe = _deployment_menu_call_fields(state, frame, 135822, check)\nif frame.status & 1:\n    return _deployment_menu_call_fields(state, frame, 136606, failure)\nframe = _deployment_menu_call_fields(state, frame, 136468, packet)\nframe = _deployment_menu_call_fields(state, frame, 136646, resources)\nframe = _duel_menu_change_word_fields(state, frame, 4294964066, 1)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    frame = _postbattle_bit_fields(frame, bool(frame.target_x & 16384))\n    state.sr = state.sr & 65504 | frame.status\n    if not frame.status & 4:\n        break\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nframe = _duel_menu_write_word_fields(state, frame, 4294964176, low16(frame.target_x))\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, saved)\nframe = _duel_menu_write_word_fields(state, frame, 4294964074, 0, clear=True)\nreturn _duel_menu_write_word_fields(state, frame, 4294964754, 1030)"}})

DECLARATIONS.update({'_city_survivor_sample_index_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if continuation not in (138028, 138052):\n    raise ValueError('original survivor random return required')\nframe = _deployment_menu_call_fields(state, frame, 33748, continuation)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nreturn _special_action_swap(state, frame, 'target_x')"}})

DECLARATIONS.update({'_city_survivor_set_register_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, name: str, bit: int', 'returns': 'FirstDeploymentFrame', 'flow': "if name != 'target_x' or bit not in (7, 14):\n    raise ValueError('original survivor register flag required')\nvalue = frame.target_x\nframe = _postbattle_bit_fields(frame, bool(value & 1 << bit))\nstate.sr = state.sr & 65504 | frame.status\nreturn first_replace(frame, target_x=value | 1 << bit)"}})

DECLARATIONS.update({'build_city_result_selection_roster_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 131092)\nframe = first_replace(frame, roster=state.table_at(4294944248).cursor(), candidates=state.table_at(4294944080).cursor())\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\nframe = first_replace(frame, candidates=state.table_at(4294944164).cursor())\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, member)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if frame.status & 8:\n        break\nframe = _duel_menu_write_word_fields(state, frame, 4294964106, state.read(4294964754, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964144, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 1034)\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 2)"}})

DECLARATIONS.update({'build_city_survivor_union_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 138268)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = first_replace(frame, roster=state.table_at(4294944080).cursor())\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\n    frame = first_replace(frame, scan=state.table_at(4294942759).cursor())\n    frame = _movement_move(state, frame, 'target_y', frame.scan.byte(low16(frame.target_y)), 8)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\nelse:\n    frame = first_replace(frame, roster=state.table_at(4294944164).cursor())\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\n    frame = first_replace(frame, scan=state.table_at(4294964318).cursor())\n    frame = _movement_move(state, frame, 'target_y', frame.scan.word(low16(frame.target_y)), 16)\nframe = first_replace(frame, candidates=state.table_at(4294946600).cursor(), controller=state.table_at(4294946646).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_move(state, frame, 'unit', member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)\n    if frame.status & 4:\n        continue\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    frame = _settlement_store_word_fields(state, frame, frame.controller, 0, low16(frame.unit))\n    frame = first_replace(frame, controller=frame.controller.advance(2))\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.controller, 0, member)\n    frame = first_replace(frame, controller=frame.controller.advance(2))\n    if frame.status & 8:\n        return frame\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)"}})

