DECLARATIONS.update({'confirm_primary_city_survivor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 138702)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _deployment_menu_call_fields(state, frame, 32906, 138722)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = _movement_add_word(state, frame, 'target_y', 41)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_y), low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294942800).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.roster, state.read(4294964875, 1), low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _city_survivor_clear_position_fields(state, frame, frame.roster, low16(frame.target_x))\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 12)"}})

DECLARATIONS.update({'confirm_secondary_city_survivor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 138138)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _deployment_menu_call_fields(state, frame, 32906, 138158)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, state.read(4294964875, 1), low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _city_survivor_clear_position_fields(state, frame, frame.roster, low16(frame.target_x))\nreturn _duel_menu_write_word_fields(state, frame, 4294964066, 2)"}})

