DECLARATIONS.update({'finish_city_survivor_result_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 138928)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 512)\nfor address in (4294964066, 4294964050, 4294964932):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, clear=True)\nframe = _duel_menu_write_word_fields(state, frame, 4294964086, 65535)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nfor address, source in ((4294959100, 4294964890), (4294959260, 4294964898), (4294962564, 4294964886), (4294962724, 4294964894)):\n    frame = first_replace(frame, roster=state.table_at(address).cursor())\n    value = state.read(source, 4)\n    frame.roster.set_long(low16(frame.target_x), value)\n    frame = _movement_test_long(state, frame, value)\nreturn _deployment_menu_call_fields(state, frame, 102926, 139004)"}})

