DECLARATIONS.update({'select_city_excess_survivors_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137940)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor())\nframe = _movement_move(state, frame, 'choice', 0, 16)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif frame.status & 4:\n    frame = first_replace(frame, roster=state.table_at(4294944080).cursor())\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_test(state, frame, member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_adjust_word(state, frame, 'choice', 1)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor())\nframe = _movement_move(state, frame, 'offset_y', 0, 16)\nwhile True:\n    member = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_test(state, frame, member, 16)\n    if frame.status & 8:\n        break\n    frame = _movement_adjust_word(state, frame, 'choice', 1)\n    frame = _movement_adjust_word(state, frame, 'offset_y', 1)\nframe = _movement_move(state, frame, 'target_x', 18, 16)\nframe = _special_action_sub_word(state, frame, 'target_x', low16(frame.offset_y))\nwhile True:\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    remaining = u16(low16(frame.target_x) - 1)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, remaining))\n    if remaining == 65535:\n        break\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor(), candidates=state.table_at(4294946600).cursor())\nframe = _special_action_sub_word(state, frame, 'choice', 10)\nif not frame.status & 5:\n    frame = _movement_move(state, frame, 'offset_y', 9, 16)\n    while True:\n        frame = _city_survivor_sample_index_fields(state, frame, 138028)\n        frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\n        frame = _city_survivor_sample_index_fields(state, frame, 138052)\n        frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\n        frame = _city_engagement_record_shift_fields(state, frame, 'unit', 1)\n        frame = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\n        if not frame.status & 8:\n            frame = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.unit)), 16)\n            if not frame.status & 8:\n                frame = first_replace(frame, target_y=frame.count, count=frame.target_y)\n                frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_x), low16(frame.target_y))\n                frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.unit), low16(frame.count))\n        remaining = u16(low16(frame.offset_y) - 1)\n        frame = first_replace(frame, offset_y=replace_word(frame.offset_y, remaining))\n        if remaining == 65535:\n            break\n    frame = _movement_adjust_word(state, frame, 'choice', -1)\n    frame = first_replace(frame, candidates=state.table_at(4294946600).cursor())\n    while True:\n        member = frame.candidates.word()\n        frame = first_replace(frame, candidates=frame.candidates.advance(2))\n        frame = _movement_move(state, frame, 'target_x', member, 16)\n        frame = _city_survivor_set_register_bit_fields(state, frame, 'target_x', 14)\n        frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n        frame = first_replace(frame, roster=frame.roster.advance(2))\n        remaining = u16(low16(frame.choice) - 1)\n        frame = first_replace(frame, choice=replace_word(frame.choice, remaining))\n        if remaining == 65535:\n            break\nreturn _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)"}})

DECLARATIONS.update({'select_city_result_member_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 131144)\nframe = _movement_test(state, frame, state.read(4294964134, 2), 16)\nif frame.status & 8:\n    return build_city_result_selection_roster_fields(state, frame)\nframe = _duel_menu_write_word_fields(state, frame, 4294964480, state.read(4294964134, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964082, state.read(4294964134, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294964482, 65535)\nframe = _duel_menu_write_word_fields(state, frame, 4294964790, 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964946, 4)\nframe = _duel_menu_write_word_fields(state, frame, 4294964754, 519)\nfor address in (4294964066, 4294964050, 4294964088):\n    frame = _duel_menu_write_word_fields(state, frame, address, 0, clear=True)\nreturn frame'}})

DECLARATIONS.update({'transfer_primary_city_survivors_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 138614)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor(), controller=state.table_at(4294943056).cursor(), scan=state.table_at(4294942800).cursor(), candidates=state.table_at(4294944122).cursor())\nframe = _duel_menu_write_word_fields(state, frame, 4294964210, state.read(4294964878, 2))\nframe = _movement_move(state, frame, 'target_y', state.read(4294964876, 2), 16)\nframe = _movement_add_word(state, frame, 'target_y', 65)\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _settlement_write_byte_fields(state, frame, frame.controller, low8(frame.target_y), low16(frame.target_x))\n    frame = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.target_x))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_write_byte_fields(state, frame, frame.scan, state.read(4294964875, 1), low16(frame.target_x))\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\n    frame = _city_survivor_clear_position_fields(state, frame, frame.controller, low16(frame.target_x))\n    frame = _deployment_menu_call_fields(state, frame, 133326, 138676)\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)\nreturn _duel_menu_write_word_fields(state, frame, 4294944122, 65535)"}})

DECLARATIONS.update({'transfer_secondary_city_survivors_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 137864)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 1)\nframe = _duel_menu_write_word_fields(state, frame, 4294964210, frame.roster.word(low16(frame.target_y)))\nframe = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294946600).cursor(), candidates=state.table_at(4294944206).cursor(), controller=state.table_at(4294953984).cursor(), scan=state.table_at(4294943056).cursor())\nwhile True:\n    member = frame.candidates.word()\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\n    frame = _movement_move(state, frame, 'target_x', member, 16)\n    if frame.status & 8:\n        break\n    frame = _settlement_write_byte_fields(state, frame, frame.controller, low8(frame.target_y), low16(frame.target_x))\n    frame = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.target_x))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\n    frame = _city_survivor_clear_position_fields(state, frame, frame.scan, low16(frame.target_x))\n    frame = _deployment_menu_call_fields(state, frame, 133326, 137926)\nframe = _settlement_store_word_fields(state, frame, frame.roster, 0, 65535)\nreturn _duel_menu_write_word_fields(state, frame, 4294944206, 65535)"}})

DECLARATIONS.update({'highbank_select_live_state_21': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState21Input', 'returns': 'HighbankSelectLiveState21Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState21Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field)\nframe = assign_city_unselected_members_fields(state, frame)\nreturn HighbankSelectLiveState21Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

