DECLARATIONS.update({'highbank_calculate_live_quotient_6': {'signature': 'state: SceneState, inputs: HighbankCalculateLiveQuotient6Input', 'returns': 'HighbankCalculateLiveQuotient6Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCalculateLiveQuotient6Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, unit=inputs.tile, count=inputs.row, distance=inputs.offset, offset_x=inputs.limit, choice=inputs.remaining, candidates=inputs.source.cursor(), stack_cursor=inputs.stack_cursor)\nframe = evaluate_city_officer_movement_chance_fields(state, frame)\nreturn HighbankCalculateLiveQuotient6Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), value=frame.target_x, field=frame.target_y, tile=frame.unit, row=frame.count, offset=frame.distance, limit=frame.offset_x, remaining=frame.choice, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'highbank_select_live_state_23': {'signature': 'state: SceneState, inputs: HighbankSelectLiveState23Input', 'returns': 'HighbankSelectLiveState23Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankSelectLiveState23Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), unit=inputs.tile, offset_x=inputs.limit)\nframe = sum_city_opposing_roster_tripled_count_fields(state, frame)\nreturn HighbankSelectLiveState23Result(destination=state.table_at(frame.roster.base), source=state.table_at(frame.candidates.base), tile=frame.unit, row=frame.count, limit=frame.offset_x, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'_city_closure_store_long_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, view, offset: int, value: int=0, clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if type(clear) is not bool or (view.base not in (4294959100, 4294959260, 4294960732, 4294961652, 4294960736) and (not (4294961656 <= view.base <= 4294961716 and (view.base - 4294961656) % 4 == 0))):\n    raise ValueError('actual city resource or link-table destination required')\nif clear:\n    view.long(offset)\nview.set_long(offset, 0 if clear else value)\nreturn _movement_test_long(state, frame, 0 if clear else value)"}})

DECLARATIONS.update({'_city_closure_clear_owner_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, owner_index: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(owner_index) is not bool:\n    raise ValueError('actual owner/link-row bit role required')\nname = 'target_x' if owner_index else 'count'\nbit = low16(frame.target_y if owner_index else frame.target_x) & 31\nvalue = frame.carrier(name)\nframe = _postbattle_bit_fields(frame, bool(value & 1 << bit))\nstate.sr = state.sr & 65504 | frame.status\nreturn first_replace(frame, **{name: value & ~(1 << bit)})"}})

DECLARATIONS.update({'assign_city_unselected_members_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 139354)\nframe = first_replace(frame, roster=state.table_at(4294946646).cursor(), candidates=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nwhile True:\n    member = frame.roster.next_word()\n    frame = _movement_move(state, frame, 'target_y', member, 16)\n    if frame.status & 8:\n        break\n    frame = _city_members_selection_bit_fields(state, frame, 'target_y')\n    if frame.status & 4:\n        frame = _settlement_write_byte_fields(state, frame, frame.candidates, value=low8(frame.target_x), offset=low16(frame.target_y))\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\naddress = 4294964876 if frame.status & 4 else 4294964878\nframe = _movement_move(state, frame, 'target_y', state.read(address, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor())\nreturn _settlement_write_byte_fields(state, frame, frame.roster, value=low8(frame.target_y), offset=low16(frame.target_x))"}})

DECLARATIONS.update({'commit_city_resources_and_remove_links_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 139416)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nfirst, second = (4294964886, 4294964894) if frame.status & 4 else (4294964890, 4294964898)\nframe = _movement_move_long(state, frame, 'target_x', state.read(first, 4))\nframe = _movement_move_long(state, frame, 'target_y', state.read(second, 4))\nframe = _movement_move(state, frame, 'unit', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\nframe = first_replace(frame, roster=state.table_at(4294959100).cursor())\nframe = _city_closure_store_long_fields(state, frame, frame.roster, low16(frame.unit), frame.target_x)\nframe = first_replace(frame, roster=state.table_at(4294959260).cursor())\nframe = _city_closure_store_long_fields(state, frame, frame.roster, low16(frame.unit), frame.target_y)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(4294960732).cursor())\nframe = _movement_test_long(state, frame, frame.roster.long(low16(frame.unit)))\nif not frame.status & 4:\n    frame = _city_closure_store_long_fields(state, frame, frame.roster, low16(frame.unit), clear=True)\n    frame = first_replace(frame, roster=state.table_at(4294961652).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\n    frame = _city_closure_store_long_fields(state, frame, frame.roster, low16(frame.target_x), clear=True)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294960896, 2), 16)\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964878, 2), 16)\n    frame = _city_closure_clear_owner_bit_fields(state, frame, True)\n    frame = _duel_menu_write_word_fields(state, frame, 4294960896, low16(frame.target_x))\nframe = first_replace(frame, roster=state.table_at(4294961656).cursor(), candidates=state.table_at(4294960736).cursor())\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964874, 2), 16)\nwhile True:\n    frame = _movement_compare(state, frame, low8(frame.target_y), frame.roster.byte(), 8)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'unit', 0, 16)\n        frame = _movement_move(state, frame, 'unit', frame.roster.byte(0, 1), 8)\n        frame = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\n        frame = _city_closure_store_long_fields(state, frame, frame.roster, 0, clear=True)\n        frame = _city_closure_store_long_fields(state, frame, frame.candidates, low16(frame.unit), clear=True)\n        frame = _movement_move(state, frame, 'count', state.read(4294960896, 2), 16)\n        frame = _city_closure_clear_owner_bit_fields(state, frame, False)\n        frame = _duel_menu_write_word_fields(state, frame, 4294960896, low16(frame.count))\n    frame = first_replace(frame, roster=frame.roster.advance(4))\n    frame = _movement_adjust_word(state, frame, 'target_x', 1)\n    frame = _movement_compare(state, frame, low16(frame.target_x), 16, 16)\n    if not frame.status & 1:\n        return frame"}})

DECLARATIONS.update({'clear_city_matching_member_assignments_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 139578)\nframe = first_replace(frame, roster=state.table_at(4294942800).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nwhile True:\n    index = low16(frame.target_y)\n    frame = _movement_move(state, frame, 'unit', frame.roster.byte(index), 8)\n    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 63, 16)\n    frame = _movement_compare(state, frame, low8(frame.unit), low8(frame.target_x), 8)\n    if frame.status & 4:\n        frame = _settlement_write_byte_fields(state, frame, frame.roster, value=0, offset=index, clear=True)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(index - 1)))\n    if low16(frame.target_y) == 65535:\n        return frame"}})

DECLARATIONS.update({'reassign_city_linked_officer_affiliations_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 139614)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964951, 1)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor(), candidates=state.table_at(4294942800).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _deployment_menu_bit(state, frame, frame.target_x, 6)\nframe = first_replace(frame, target_x=frame.target_x | 64)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nframe = _movement_move(state, frame, 'distance', state.read(4294964878, 2), 16)\nframe = _movement_add_word(state, frame, 'distance', 105)\nwhile True:\n    index = low16(frame.target_y)\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(index), 8)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'count', frame.candidates.byte(index), 8)\n        if not frame.status & 4:\n            frame = _movement_move(state, frame, 'count', low16(frame.count) & 63, 16)\n            frame = _movement_compare(state, frame, low8(frame.count), low8(frame.unit), 8)\n            if not frame.status & 4:\n                frame = _settlement_write_byte_fields(state, frame, frame.roster, value=low8(frame.distance), offset=index)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(index - 1)))\n    if low16(frame.target_y) == 65535:\n        break\nframe = first_replace(frame, candidates=state.table_at(4294938624).cursor())\nframe = _movement_move(state, frame, 'unit', state.read(4294964878, 2), 16)\nwhile True:\n    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(), 8)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 15, 16)\n    if frame.status & 4:\n        return frame\n    frame = _movement_compare(state, frame, low8(frame.unit), frame.candidates.byte(0, 4), 8)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'count', low16(frame.target_y), 16)\n        frame = _movement_adjust_word(state, frame, 'count', -1)\n        while True:\n            frame = _movement_move(state, frame, 'offset_x', 0, 16)\n            frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(low16(frame.count), 13), 8)\n            frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.offset_x)), 8)\n            if frame.status & 4:\n                frame = _settlement_write_byte_fields(state, frame, frame.roster, value=low8(frame.distance), offset=low16(frame.offset_x))\n            frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n            if low16(frame.count) == 65535:\n                break\n    frame = first_replace(frame, candidates=frame.candidates.advance(13 + s16(low16(frame.target_y))))"}})

DECLARATIONS.update({'try_city_officer_movement_trigger_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _resource_cost_frame(state, frame, 140510)\nframe = _deployment_menu_call_fields(state, frame, 140684, 140514)\nif frame.status & 1:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 143336, 140522)\nreturn frame if frame.status & 1 else _deployment_menu_call_fields(state, frame, 140532, 140530)'}})

DECLARATIONS.update({'trigger_city_officer_map_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 140532)\nframe = first_replace(frame, roster=state.table_at(4294944340).cursor())\nframe = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return _retreat_policy_carry(state, frame, False)\nframe = first_replace(frame, roster=state.table_at(16727234).cursor())\nframe = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return _retreat_policy_carry(state, frame, False)\nframe = first_replace(frame, candidates=state.table_at(16727490).cursor())\nframe = _movement_test(state, frame, frame.candidates.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return _retreat_policy_carry(state, frame, False)\nframe = _deployment_menu_call_fields(state, frame, 107576, 140578)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 7, True)\nframe, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), continuation=140604)\nframe = _movement_compare(state, frame, low8(frame.target_x), 6, 8)\nif frame.status & 4:\n    return _retreat_policy_carry(state, frame, False)\nframe = first_replace(frame, roster=state.table_at(713462).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964874, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = first_replace(frame, candidates=state.table_at(16722944).cursor())\nframe = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 2)\nframe = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), low16(frame.unit))\nframe = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x), 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), low16(frame.unit), 2)\nframe = first_replace(frame, roster=state.table_at(4294946344).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.roster, value=1, offset=low16(frame.choice))\nframe = _deployment_menu_call_fields(state, frame, 122026, 140670)\nreturn _retreat_policy_carry(state, frame, True)"}})

DECLARATIONS.update({'_city_closure_random_eighth_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if continuation not in (140780, 140896):\n    raise ValueError('actual movement probability continuation required')\nframe = _deployment_menu_call_fields(state, frame, 33748, continuation)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _settlement_shift_sample_long_fields(state, frame, 'target_x', 3)\nframe = _special_action_swap(state, frame, 'target_x')\nreturn _movement_compare(state, frame, low16(frame.target_x), low16(frame.unit), 16)"}})

DECLARATIONS.update({'_city_closure_commit_movement_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.choice))\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, low16(frame.choice))\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test(state, frame, low16(frame.choice), 16)\nframe = _deployment_menu_call_fields(state, frame, 97418, 140932)\nsaved = frame.stack_cursor.word()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))\nframe = _movement_move(state, frame, 'choice', saved, 16)\nframe = _movement_test(state, frame, state.read(4294964972, 2), 16)\nif frame.status & 8:\n    return _retreat_policy_carry(state, frame, False)\nframe = _deployment_menu_call_fields(state, frame, 98096, 140946)\nframe = _duel_menu_write_word_fields(state, frame, 4294964178, state.read(4294964134, 2))\nframe = _duel_menu_write_word_fields(state, frame, 4294965056, 302)\nframe = _damage_bchg_side(BattlePresentationMemory(state), frame)\nframe = _deployment_menu_call_fields(state, frame, 155876, 140970)\nframe = _damage_bchg_side(BattlePresentationMemory(state), frame)\nreturn _retreat_policy_carry(state, frame, True)"}})

DECLARATIONS.update({'evaluate_city_officer_movement_chance_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 140684)\nframe = first_replace(frame, roster=state.table_at(4294952960).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _movement_move_long(state, frame, 'target_y', frame.roster.long(low16(frame.target_x)))\nframe = _command_detail_compare_long_fields(state, frame, frame.target_y, 200)\nsmall_force = bool(frame.status & 5)\nif not small_force:\n    frame = _command_detail_compare_long_fields(state, frame, frame.target_y, 500)\n    if frame.status & 5:\n        frame = first_replace(frame, roster=state.table_at(4294946816).cursor())\n        frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 1, True)\n        frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)\n        frame = _city_engagement_record_shift_fields(state, frame, 'target_y', 2, True)\n        frame = first_replace(frame, roster=state.table_at(4294947328).cursor())\n        frame = _movement_compare(state, frame, low16(frame.target_y), frame.roster.word(low16(frame.target_x)), 16)\n        small_force = not bool(frame.status & 1)\nif small_force:\n    frame = _movement_move(state, frame, 'unit', 2, 16)\n    frame = first_replace(frame, roster=state.table_at(4294960704).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964878, 2), 16)\n    frame = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\n    frame = _movement_compare(state, frame, low16(frame.choice), frame.roster.word(low16(frame.target_x)), 16)\n    if frame.status & 4:\n        frame = _movement_move(state, frame, 'unit', 4, 16)\n        frame = _deployment_menu_call_fields(state, frame, 141056, 140770)\n        if not frame.status & 1:\n            return _retreat_policy_carry(state, frame, True)\n    frame = _city_closure_random_eighth_fields(state, frame, 140780)\n    if frame.status & 1:\n        return _city_closure_commit_movement_fields(state, frame)\nframe = _deployment_menu_call_fields(state, frame, 140982, 140800)\nframe = _movement_compare(state, frame, low16(frame.target_x), 3, 16)\ndefault_capacity_gate = bool(frame.status & 1)\nif not default_capacity_gate:\n    frame = _movement_test_long(state, frame, state.read(4294964898, 4))\n    default_capacity_gate = not bool(frame.status & 4)\n    if not default_capacity_gate:\n        frame = _movement_move_long(state, frame, 'unit', state.read(4294965100, 4))\n        frame = _movement_divu_word(state, frame, 'unit', 3, 140820)\n        frame = _movement_move_long(state, frame, 'unit', frame.unit & 65535)\n        frame = _command_detail_compare_long_fields(state, frame, frame.unit, state.read(4294964896, 4))\n        default_capacity_gate = not bool(frame.status & 5)\nif default_capacity_gate:\n    frame = _deployment_menu_call_fields(state, frame, 141026, 140842)\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_x), 16)\n    if not frame.status & 5:\n        return _retreat_policy_carry(state, frame, False)\n    frame = _command_detail_compare_long_fields(state, frame, frame.count, 1000)\n    if not frame.status & 5:\n        return _retreat_policy_carry(state, frame, False)\n    frame = _settlement_shift_sample_long_fields(state, frame, 'count', 1)\n    frame = _command_detail_compare_long_fields(state, frame, frame.count, frame.target_y)\n    if not frame.status & 5:\n        return _retreat_policy_carry(state, frame, False)\n    frame = _movement_move_long(state, frame, 'target_x', state.read(4294965096, 4))\n    frame = _command_detail_compare_long_fields(state, frame, frame.target_x, state.read(4294964898, 4))\n    if frame.status & 1:\n        return _retreat_policy_carry(state, frame, False)\nframe = _movement_move(state, frame, 'unit', 2, 16)\nframe = _deployment_menu_call_fields(state, frame, 141056, 140886)\nif not frame.status & 1:\n    return _retreat_policy_carry(state, frame, True)\nframe = _city_closure_random_eighth_fields(state, frame, 140896)\nreturn _city_closure_commit_movement_fields(state, frame) if frame.status & 1 else _retreat_policy_carry(state, frame, False)"}})

DECLARATIONS.update({'sum_city_opposing_roster_tripled_count_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 141026)\nframe = first_replace(frame, roster=state.table_at(4294944164).cursor(), candidates=state.table_at(4294952960).cursor())\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move_long(state, frame, 'count', 0)\nwhile True:\n    member = frame.roster.next_word()\n    frame = _movement_move(state, frame, 'offset_x', member, 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_add_word(state, frame, 'unit', 3)\n    frame = _city_engagement_record_shift_fields(state, frame, 'offset_x', 2)\n    frame = _movement_arithmetic_long(state, frame, 'count', frame.candidates.long(low16(frame.offset_x)))"}})

