DECLARATIONS.update({'_city_contact_actor_rating_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294948352).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 1)\nreturn _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)"}})

DECLARATIONS.update({'_city_contact_random_quarter_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if continuation not in (143400, 144074):\n    raise ValueError('actual contact readiness random continuation required')\nframe = _deployment_menu_call_fields(state, frame, 33748, continuation)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _special_action_swap(state, frame, 'target_x')\nreturn _movement_compare(state, frame, low16(frame.target_x), low16(frame.unit), 16)"}})

DECLARATIONS.update({'_city_contact_restore_selected_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carry: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(carry) is not bool:\n    raise ValueError('actual preselection carry result required')\nsaved = frame.stack_cursor.word()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))\nframe = _movement_move(state, frame, 'target_x', saved, 16)\nreturn _retreat_policy_carry(state, frame, carry)"}})

DECLARATIONS.update({'_city_contact_submit_target_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, role: int', 'returns': 'FirstDeploymentFrame', 'flow': "if role == 0:\n    map_return, terrain_return, city_return, commit_return = (143712, 143738, 143752, 143766)\nelif role == 1:\n    map_return, terrain_return, city_return, commit_return = (144298, 144324, 144338, 144352)\nelse:\n    raise ValueError('actual packed-target or nearest-contact submit role required')\nframe = first_replace(frame, roster=state.table_at(16722944).cursor())\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.unit), low16(frame.target_x))\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.unit), low16(frame.target_y), 2)\nframe = first_replace(frame, roster=state.table_at(4294946344).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.roster, value=1, offset=low16(frame.choice))\nframe = _deployment_menu_call_fields(state, frame, 107576, map_return)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 7, True)\nframe, category = _deployment_terrain_lookup(BattlePolicyMemory(state), frame, low16(frame.target_y), low16(frame.unit), continuation=terrain_return)\nframe = _movement_compare(state, frame, low8(frame.target_x), 6, 8)\nif not frame.status & 4:\n    return _deployment_menu_call_fields(state, frame, 122026, city_return)\nframe = _duel_menu_write_word_fields(state, frame, 4294964134, low16(frame.choice))\nreturn _deployment_menu_call_fields(state, frame, 121724, commit_return)"}})

DECLARATIONS.update({'try_city_contact_readiness_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 143336)\nframe = _deployment_menu_call_fields(state, frame, 144594, 143340)\nframe = _movement_test(state, frame, state.read(4294955776, 2), 16)\nif frame.status & 8:\n    return _retreat_policy_carry(state, frame, False)\nframe = _city_contact_actor_rating_fields(state, frame)\nframe = _movement_move(state, frame, 'unit', 1, 16)\nfor threshold in (60, 80, 100):\n    frame = _movement_compare(state, frame, low16(frame.target_x), threshold, 16)\n    if frame.status & 1:\n        break\n    frame = _movement_add_word(state, frame, 'unit', 1)\nframe = _city_contact_random_quarter_fields(state, frame, 143400)\nif low16(frame.target_x) > low16(frame.unit):\n    return _retreat_policy_carry(state, frame, False)\nreturn _deployment_menu_call_fields(state, frame, 155602, 143420)"}})

DECLARATIONS.update({'move_city_actor_to_packed_target_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, variant: int=0', 'returns': 'FirstDeploymentFrame', 'flow': "if variant not in (0, 1, 2, 3):\n    raise ValueError('actual live packed-target source variant required')\nframe = _resource_cost_frame(state, frame, (143582, 144456, 144520, 144584)[variant])\nframe = _movement_move(state, frame, 'target_x', state.read(16727746 + 2 * variant, 2), 16)\nframe = first_replace(frame, roster=state.table_at(4294944340).cursor())\nframe = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(16727234).cursor())\nframe = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, candidates=state.table_at(16727490).cursor())\nframe = _movement_test(state, frame, frame.candidates.byte(low16(frame.choice)), 8)\nif not frame.status & 4:\n    return frame\nframe = _deployment_menu_call_fields(state, frame, 144016, 143632)\nif frame.status & 1:\n    return frame\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'target_y', low8(frame.target_x), 8)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 64512, 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 3)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_y', 7)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'unit', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\nframe = _movement_compare(state, frame, low16(frame.target_x), frame.roster.word(low16(frame.unit)), 16)\nif frame.status & 4:\n    frame = _movement_compare(state, frame, low16(frame.target_y), frame.roster.word(low16(frame.unit), 2), 16)\n    if frame.status & 4:\n        return frame\nframe = _deployment_menu_call_fields(state, frame, 143768, 143678)\nreturn _city_contact_submit_target_fields(state, frame, 0)"}})

DECLARATIONS.update({'preselect_city_nearest_contact_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 144016)\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, low16(frame.target_x))\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\nframe = _deployment_menu_call_fields(state, frame, 144594, 144022)\nframe = _movement_test(state, frame, state.read(4294955776, 2), 16)\nif frame.status & 8:\n    return _city_contact_restore_selected_word_fields(state, frame, False)\nframe = _deployment_menu_call_fields(state, frame, 144138, 144034)\nframe = _city_contact_actor_rating_fields(state, frame)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nfor threshold in (70, 90):\n    frame = _movement_compare(state, frame, low16(frame.target_x), threshold, 16)\n    if frame.status & 1:\n        break\n    frame = _movement_add_word(state, frame, 'unit', 1)\nframe = _city_contact_random_quarter_fields(state, frame, 144074)\nif not frame.status & 1:\n    frame = _deployment_menu_call_fields(state, frame, 144238, 144094)\n    return _city_contact_restore_selected_word_fields(state, frame, True)\nframe = first_replace(frame, roster=state.table_at(4294944596).cursor())\nframe = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)\nif frame.status & 4:\n    frame = _deployment_menu_call_fields(state, frame, 155602, 144118)\nreturn _city_contact_restore_selected_word_fields(state, frame, True)"}})

DECLARATIONS.update({'move_city_actor_to_nearest_contact_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 144238)\nframe = first_replace(frame, roster=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x), 2), 16)\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\nframe = _deployment_menu_call_fields(state, frame, 143768, 144260)\nframe = _movement_move(state, frame, 'unit', low16(frame.choice), 16)\nframe = _city_engagement_record_shift_fields(state, frame, 'unit', 2)\nreturn _city_contact_submit_target_fields(state, frame, 1)"}})

