DECLARATIONS.update({'highbank_coordinate_live_state_84': {'signature': 'state: SceneState, inputs: HighbankCoordinateLiveState84Input', 'returns': 'HighbankCoordinateLiveState84Result', 'flow': "checked_state(state)\nif type(inputs) is not HighbankCoordinateLiveState84Input:\n    raise ValueError('function-specific historical duel-commit input required')\ninputs.validate(state)\nconditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)\nstate.sr = state.sr & 65520 | conditions\nframe = first_replace(FirstDeploymentFrame.unobserved(), offset_x=inputs.limit, choice=inputs.remaining, roster=inputs.destination.cursor())\nframe = try_first_side_type2_order_fields(state, frame)\nreturn HighbankCoordinateLiveState84Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)"}})

DECLARATIONS.update({'attempt_first_side_contact_actions_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 155602)\nstack = frame.stack_cursor.advance(-2)\nstack.set_word(0, low16(frame.choice))\nframe = first_replace(frame, stack_cursor=stack)\nframe = _movement_test(state, frame, low16(frame.choice), 16)\nselected = False\nfor target, continuation in ((155658, 155608), (155948, 155616), (156236, 155624), (156414, 155632), (156680, 155640)):\n    frame = _deployment_menu_call_fields(state, frame, target, continuation)\n    if frame.status & 1:\n        selected = True\n        break\nrestored = frame.stack_cursor.word()\nframe = first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))\nframe = _movement_move(state, frame, 'choice', restored, 16)\nreturn frame if selected else _retreat_policy_carry(state, frame, False)"}})

DECLARATIONS.update({'execute_first_side_contact_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, mode: int', 'returns': 'FirstDeploymentFrame', 'flow': "if mode == 0:\n    target, random_return = (155658, 155664)\n    selector, selection_return, budget, budget_return = (155782, 155686, 155824, 155702)\n    order, present_return, message, message_return = (4, 155736, 300, 155762)\n    budget_carrier = 'target_x'\nelif mode == 1:\n    target, random_return = (155948, 155954)\n    selector, selection_return, budget, budget_return = (156068, 155976, 156180, 155990)\n    order, present_return, message, message_return = (0, 156022, 296, 156048)\n    budget_carrier = 'target_y'\nelif mode == 2:\n    target, random_return = (156236, 156242)\n    selector, selection_return, budget, budget_return = (156068, 156264, 156358, 156278)\n    order, present_return, message, message_return = (2, 156312, 298, 156338)\n    budget_carrier = 'target_y'\nelif mode == 3:\n    target, random_return = (156414, 156420)\n    selector, selection_return, budget, budget_return = (156536, 156442, 156624, 156456)\n    order, present_return, message, message_return = (5, 156490, 301, 156516)\n    budget_carrier = 'target_y'\nelif mode == 4:\n    target, random_return = (156680, 156686)\n    selector, selection_return, budget, budget_return = (156880, 156716, 156968, 156730)\n    order, present_return, message, message_return = (1, 156764, 297, 156790)\n    budget_carrier = 'target_y'\nelse:\n    raise ValueError('only the five actual first-side contact action plans are admitted')\nframe = _resource_cost_frame(state, frame, target)\nframe = _city_contact_random_quarter_fields(state, frame, random_return, True)\nif frame.status & 4:\n    return _retreat_policy_carry(state, frame, False)\nif mode == 4:\n    frame = _deployment_menu_call_fields(state, frame, 156810, 156708)\n    if not frame.status & 1:\n        return _retreat_policy_carry(state, frame, False)\nframe = _deployment_menu_call_fields(state, frame, selector, selection_return)\nif mode == 0:\n    frame = _movement_compare(state, frame, low8(frame.target_x), 50, 8)\n    if low8(frame.target_x) > 50:\n        return _retreat_policy_carry(state, frame, False)\n    chosen = low16(frame.target_y)\nelse:\n    frame = _movement_test(state, frame, low16(frame.offset_x), 16)\n    if frame.status & 8:\n        return _retreat_policy_carry(state, frame, False)\n    chosen = low16(frame.offset_x)\nframe = _duel_menu_write_word_fields(state, frame, 4294964134, chosen)\nframe = _deployment_menu_call_fields(state, frame, budget, budget_return)\nceiling = state.read(4294964890, 4)\namount = frame.carrier(budget_carrier)\nframe = _movement_compare(state, frame, amount, ceiling, 32)\nif amount > ceiling:\n    return _retreat_policy_carry(state, frame, False)\nframe = first_replace(frame, roster=state.table_at(4294944596).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.roster, value=3, offset=low16(frame.choice))\nframe = _duel_menu_write_word_fields(state, frame, 4294964210, low16(frame.choice))\nframe = _duel_menu_write_word_fields(state, frame, 4294964948, order, clear=order == 0)\nframe = _deployment_menu_call_fields(state, frame, 107642, present_return)\nif not frame.status & 1:\n    frame = _damage_bchg_side(BattlePresentationMemory(state), frame)\n    frame = _duel_menu_write_word_fields(state, frame, 4294964176, state.read(4294964134, 2))\n    frame = _duel_menu_write_word_fields(state, frame, 4294965056, message)\n    frame = _deployment_menu_call_fields(state, frame, 155876, message_return)\n    frame = _damage_bchg_side(BattlePresentationMemory(state), frame)\nreturn _retreat_policy_carry(state, frame, True)"}})

