DECLARATIONS.update({'_city_contact_random_quarter_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, continuation: int, constant_three: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': "if continuation not in (143400, 144074, 155664, 155954, 156242, 156420, 156686):\n    raise ValueError('actual contact readiness random continuation required')\nif type(constant_three) is not bool or constant_three != (continuation in (155664, 155954, 156242, 156420, 156686)):\n    raise ValueError('actual quarter comparison role must match its caller token')\nframe = _deployment_menu_call_fields(state, frame, 33748, continuation)\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _special_action_shift_long(state, frame, 'target_x', 2)\nframe = _special_action_swap(state, frame, 'target_x')\nreturn _movement_compare(state, frame, low16(frame.target_x), 3 if constant_three else low16(frame.unit), 16)"}})

