DECLARATIONS.update({'_scenario_column_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, columns: int', 'returns': 'FirstDeploymentFrame', 'flow': "if columns not in (2, 3):\n    raise ValueError('actual paired/triple scenario panel role required')\nfor displacement in (80, 0) if columns == 2 else (160, 80, 0):\n    frame = _scenario_panel_word_fields(state, frame, 38, displacement, displacement == 0)\nheaders = ((80, 51970), (0, 51842)) if columns == 2 else ((160, 52354), (80, 52226), (0, 52098))\nfor displacement, header in headers:\n    frame = _scenario_panel_word_fields(state, frame, header, displacement, displacement == 0)\nfor displacement in (80, 0) if columns == 2 else (160, 80, 0):\n    frame = _scenario_panel_tile_fields(state, frame, 898)\n    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), displacement, displacement == 0)\nframe = _scenario_panel_tile_fields(state, frame, 1285 if columns == 2 else 1357, 'target_y')\nframe = _movement_move(state, frame, 'target_x', 35, 16)\nwhile True:\n    for displacement in (0, 80) if columns == 2 else (0, 80, 160):\n        frame = _scenario_panel_word_fields(state, frame, low16(frame.target_y), displacement)\n        frame = _movement_adjust_word(state, frame, 'target_y', 1)\n    frame = first_replace(frame, roster=frame.roster.advance(2), target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nfor displacement in (80, 0) if columns == 2 else (160, 80, 0):\n    frame = _scenario_panel_tile_fields(state, frame, 2946)\n    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), displacement, displacement == 0)\nframe = _scenario_panel_word_fields(state, frame, 0, 80 if columns == 2 else 160, clear=True)\nreturn _command_policy_change_memory_fields(state, frame, 4294963994, 160 if columns == 2 else 240)"}})

DECLARATIONS.update({'_scenario_numeric_text_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_move_long(state, frame, 'target_y', 16640)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = first_replace(frame, auxiliary=state.table_at(4294955776))\nframe = _command_policy_call_fields(state, frame, 75530, 422526)\nframe = _command_policy_store_word_fields(state, frame, 4294955788, 32780)\nframe = first_replace(frame, auxiliary=state.table_at(4294955776))\nwhile True:\n    frame = _movement_test(state, frame, frame.auxiliary.word(), 16)\n    frame = first_replace(frame, auxiliary=frame.auxiliary.advance(2))\n    if not frame.status & 4:\n        break\nframe = first_replace(frame, auxiliary=frame.auxiliary.advance(-2))\nframe = _command_policy_store_long_fields(state, frame, 4294964180, state.read(4294964158, 4))\nframe = _command_policy_store_long_fields(state, frame, 4294964158, frame.auxiliary.base)\nreturn restore_scenario_saved_command_fields(state, frame)"}})

