DECLARATIONS.update({'build_scenario_single_row_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 423198)\nfor value in (38, 51714):\n    frame = _scenario_panel_word_fields(state, frame, value, advance=True)\nframe = _scenario_panel_tile_fields(state, frame, 896)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)\nframe = _movement_move(state, frame, 'target_x', 35, 16)\nframe = _scenario_panel_tile_fields(state, frame, 897)\nwhile True:\n    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _scenario_panel_tile_fields(state, frame, 2944)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)\nframe = _scenario_panel_word_fields(state, frame, 0, clear=True)\nframe = _command_policy_change_memory_fields(state, frame, 4294963994, 80)\nframe = _command_policy_bit_fields(state, frame, 4294964132, 2)\nif frame.status & 4:\n    return frame\nframe = _scenario_panel_word_fields(state, frame, 13, 30)\nframe = _scenario_panel_word_fields(state, frame, 13, advance=True)\nframe = _scenario_panel_tile_fields(state, frame, 2356)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)\nframe = _scenario_panel_tile_fields(state, frame, 2484)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)\nframe = _scenario_panel_tile_fields(state, frame, 4992)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)\nframe = _scenario_panel_word_fields(state, frame, 32768, advance=True)\nframe = _movement_move(state, frame, 'target_x', 10, 16)\nframe = _scenario_panel_tile_fields(state, frame, 4993)\nwhile True:\n    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)\n    frame = _scenario_panel_word_fields(state, frame, 32768, advance=True)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _scenario_panel_tile_fields(state, frame, 7040)\nframe = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)\nframe = _scenario_panel_word_fields(state, frame, 32768, advance=True)\nframe = _command_policy_change_memory_fields(state, frame, 4294963994, 60)\nreturn _scenario_panel_word_fields(state, frame, 0, 30, clear=True)"}})

DECLARATIONS.update({'build_scenario_summary_buffers_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 421546)\nframe = _movement_move(state, frame, 'target_x', 511, 16)\nframe = first_replace(frame, roster=state.table_at(16740352).cursor(), candidates=state.table_at(16742400).cursor(), controller=state.table_at(4294934528), scan=state.table_at(4294936576).cursor())\nwhile True:\n    for name in ('roster', 'candidates', 'controller', 'scan'):\n        view = frame.roster if name == 'roster' else frame.candidates if name == 'candidates' else frame.controller if name == 'controller' else frame.scan\n        frame = _command_policy_store_long_fields(state, frame, view.address() if name != 'controller' else view.base, 0, True)\n        following = state.table_at(u32(view.base + 4)) if name == 'controller' else view.advance(4)\n        frame = first_replace(frame, **{name: following})\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _command_policy_store_word_fields(state, frame, 4294934746, 3)\nframe = first_replace(frame, roster=state.table_at(4294960704).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294963120, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\nfor address in (4294934748, 4294934750):\n    frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_x))\nframe = _movement_move(state, frame, 'target_x', state.read(4294944290, 2), 16)\nif frame.status & 8:\n    frame = _command_policy_store_word_fields(state, frame, 4294934746, 4)\n    frame = first_replace(frame, roster=state.table_at(4294960704).cursor())\n    frame = _movement_move(state, frame, 'target_x', state.read(4294963120, 2), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)\n    for address in (4294934748, 4294934750, 4294934752, 4294934754):\n        frame = _command_policy_store_word_fields(state, frame, address, frame.roster.word(low16(frame.target_x)))\nelse:\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(4294963120, 2), 16)\n    if frame.status & 4:\n        frame = _movement_fixed_shift_word(state, frame, 'target_y', 8, True)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)\n    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\n    for address in (4294934752, 4294934754):\n        frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_x))\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964084, 1), 8)\nframe = _movement_add_word(state, frame, 'target_x', 184)\nframe = _command_policy_store_word_fields(state, frame, 4294934756, low16(frame.target_x))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964085, 1), 8)\nframe = _movement_adjust_word(state, frame, 'target_x', 1)\nframe = _command_policy_store_word_fields(state, frame, 4294934758, low16(frame.target_x))\nframe = _command_policy_change_memory_fields(state, frame, 4294964066, 1)\nreturn _command_policy_store_word_fields(state, frame, 4294964050, 0, True)"}})

