DECLARATIONS.update({'execute_command_member_transfer_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 204310)\nframe = _movement_move(state, frame, 'unit', state.read(4294964068, 2), 16)\nframe = _command_policy_call_fields(state, frame, 203446, 204318)\nframe = _movement_compare(state, frame, low16(frame.distance), 1, 16)\nif not frame.status & 4:\n    frame = _command_policy_call_fields(state, frame, 204398, 204330)\n    frame = _movement_test(state, frame, state.read(4294964134, 2), 16)\n    if not frame.status & 8:\n        frame = _command_policy_call_fields(state, frame, 204448, 204342)\n        frame = _movement_test(state, frame, state.read(4294964114, 2), 16)\n        if not frame.status & 4:\n            frame = first_replace(frame, roster=state.table_at(4294954240).cursor())\n            frame = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\n            frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))\n            frame = first_replace(frame, roster=state.table_at(4294953984).cursor())\n            frame = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\n            frame = _settlement_write_byte_fields(state, frame, frame.roster, state.read(4294964115, 1), low16(frame.target_x))\n            frame = _command_policy_call_fields(state, frame, 204542, 204382)\n            frame = _command_policy_call_fields(state, frame, 204602, 204386)\n            frame = _command_policy_call_fields(state, frame, 204622, 204390)\nreturn _command_policy_store_word_fields(state, frame, 4294965032, 3)"}})

