DECLARATIONS.update({'execute_member_transfer_command_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 202292)\nframe = _command_policy_call_fields(state, frame, 202152, 202296)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964136, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nwhile True:\n    frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.target_y)), 8)\n    if frame.status & 4:\n        frame = _movement_adjust_word(state, frame, 'unit', 1)\n    frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))\n    if low16(frame.target_y) == 65535:\n        break\nframe = _movement_compare(state, frame, low16(frame.unit), 10, 16)\nif frame.status & 1:\n    frame = first_replace(frame, roster=state.table_at(4294953984).cursor())\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\n    frame = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.target_y))\n    frame = first_replace(frame, roster=state.table_at(4294964263).cursor())\n    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)\n    frame = first_replace(frame, roster=state.table_at(4294960704).cursor())\n    frame = _command_policy_store_word_fields(state, frame, 4294964210, frame.roster.word(low16(frame.target_x)))\n    frame = _command_policy_call_fields(state, frame, 133326, 202374)\n    frame = _command_policy_member_notice_fields(state, frame, 287, 202402)\n    frame = _command_policy_store_word_fields(state, frame, 4294964818, 1)\n    return _command_policy_call_fields(state, frame, 202126, 202412)\nframe = first_replace(frame, roster=state.table_at(4294953984).cursor())\nframe = _movement_move(state, frame, 'target_y', state.read(4294964134, 2), 16)\nframe = _command_policy_register_bit_fields(state, frame, frame.target_x, 7)\nframe = first_replace(frame, target_x=frame.target_x | 128)\nframe = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.target_y))\nframe = _command_policy_member_notice_fields(state, frame, 155, 202460, 4294964176)\nreturn _command_policy_call_fields(state, frame, 202126, 202464)"}})

DECLARATIONS.update({'find_command_minimum_loyalty_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203686)\nframe = first_replace(frame, roster=state.table_at(4294965034).cursor(), candidates=state.table_at(4294951680).cursor())\nframe = _movement_move(state, frame, 'target_y', 255, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'distance', frame.roster.word(), 16)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if frame.status & 8:\n        return frame\n    frame = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.distance)), 8)\n    if frame.status & 4:\n        continue\n    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)\n    if not frame.status & 1:\n        continue\n    frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)"}})

