DECLARATIONS.update({'process_command_choice_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 201776)\nframe = _command_policy_call_fields(state, frame, 201842, 201780)\nframe = _command_policy_call_fields(state, frame, 201918, 201784)\nframe, waiting = _command_policy_debounce_fields(state, frame)\nif waiting:\n    return frame\nframe = _command_policy_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _command_policy_call_fields(state, frame, 202060, 201830)\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nreturn _command_policy_call_fields(state, frame, 32906, 201840)"}})

