DECLARATIONS.update({'process_command_policy_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 202602)\nframe = _command_policy_call_fields(state, frame, 202716, 202606)\nframe = _command_policy_call_fields(state, frame, 202760, 202610)\nframe, waiting = _command_policy_debounce_fields(state, frame)\nif waiting:\n    return frame\nframe = _command_policy_bit_fields(state, frame, 4294964739, 5)\nif frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _command_policy_call_fields(state, frame, 32906, 202662)\nframe = _movement_test(state, frame, state.read(4294964102, 2), 16)\nif frame.status & 4:\n    frame = _command_policy_call_fields(state, frame, 202924, 202674)\n    frame = _command_policy_store_word_fields(state, frame, 4294964744, 300)\n    frame = _command_policy_store_word_fields(state, frame, 4294964066, 1)\n    frame = _command_policy_message_fields(state, frame, 133, 202696)\n    return _command_policy_call_fields(state, frame, 203038, 202700)\nframe = _command_policy_store_word_fields(state, frame, 4294964066, 1)\nreturn _command_policy_call_fields(state, frame, 203038, 202714)"}})

DECLARATIONS.update({'rank_command_neighbor_city_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203376)\nsaved = ('target_x', 'unit', 'count', 'distance', 'roster', 'candidates', 'controller')\nframe = _movement_save_longs(state, frame, saved)\nframe = first_replace(frame, roster=state.table_at(871386).cursor(), controller=state.table_at(4294961719))\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 3)\nframe = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.target_x))))\nframe = _movement_move(state, frame, 'count', state.read(4294964086, 2), 16)\nframe = first_replace(frame, candidates=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'offset_x', 65535, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nwhile True:\n    frame = _movement_move(state, frame, 'unit', frame.roster.byte(), 8)\n    frame = first_replace(frame, roster=frame.roster.advance(1))\n    if frame.status & 8:\n        break\n    frame = _movement_test(state, frame, frame.controller.byte(low16(frame.unit)), 8)\n    if not frame.status & 4:\n        continue\n    frame = _movement_compare(state, frame, low8(frame.count), frame.candidates.byte(low16(frame.unit)), 8)\n    if frame.status & 4:\n        continue\n    frame = _command_policy_call_fields(state, frame, 203446, 203430)\n    frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.target_y), 16)\n    if frame.status & 5:\n        continue\n    frame = _movement_move(state, frame, 'target_y', low16(frame.distance), 16)\n    frame = _movement_move(state, frame, 'offset_x', low16(frame.unit), 16)\nreturn _movement_restore_longs(state, frame, saved)"}})

DECLARATIONS.update({'rank_scenario_force_leader_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 421318)\nframe = _movement_move(state, frame, 'target_x', state.read(4294963120, 2), 16)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nframe = _movement_move(state, frame, 'distance', 2, 16)\nframe = _movement_move(state, frame, 'unit', 65535, 16)\nframe = first_replace(frame, roster=state.table_at(4294964263).cursor(), candidates=state.table_at(4294953984).cursor(), controller=state.table_at(4294952704), scan=state.table_at(4294951680).cursor())\nframe = _movement_move(state, frame, 'count', 255, 16)\nwhile True:\n    index = low16(frame.count)\n    frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(index), 8)\n    if not frame.status & 12:\n        frame = _movement_move(state, frame, 'offset_x', low16(frame.offset_x) & 63, 16)\n        frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.offset_x)), 8)\n        if frame.status & 4:\n            frame = _movement_move(state, frame, 'offset_y', 5, 16)\n            frame = _movement_move(state, frame, 'choice', frame.scan.byte(index), 8)\n            frame = _movement_compare(state, frame, low8(frame.choice), 90, 8)\n            evaluate = not frame.status & 1\n            if not evaluate:\n                frame = _movement_compare(state, frame, low8(frame.choice), 80, 8)\n                if not frame.status & 1:\n                    frame = _movement_move(state, frame, 'offset_y', frame.controller.byte(index), 8)\n                    frame = _movement_move(state, frame, 'offset_y', low16(frame.offset_y) & 7, 16)\n                    frame = _movement_compare(state, frame, low16(frame.offset_y), low16(frame.distance), 16)\n                    if not frame.status & 1:\n                        evaluate = not frame.status & 4\n                        if not evaluate:\n                            frame = _movement_compare(state, frame, low8(frame.choice), low8(frame.target_y), 8)\n                            evaluate = not frame.status & 5\n            else:\n                frame = _movement_compare(state, frame, low8(frame.choice), low8(frame.target_y), 8)\n                evaluate = not frame.status & 5\n            if evaluate:\n                frame = _movement_move(state, frame, 'target_y', low8(frame.choice), 8)\n                frame = _movement_move(state, frame, 'distance', low16(frame.offset_y), 16)\n                frame = _movement_move(state, frame, 'unit', index, 16)\n    frame = first_replace(frame, count=replace_word(frame.count, u16(index - 1)))\n    if low16(frame.count) == 65535:\n        return frame"}})

DECLARATIONS.update({'refresh_command_map_on_input_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203220)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 47, 16)\nif frame.status & 4:\n    return frame\nframe = _movement_move_long(state, frame, 'target_x', 3221225510)\nframe = _movement_move(state, frame, 'target_y', 7, 16)\nframe = _movement_move(state, frame, 'unit', 51714, 16)\nframe = first_replace(frame, roster=state.table_at(201610).cursor())\nframe = _command_policy_call_fields(state, frame, 158714, 203256)\nframe = _command_policy_store_word_fields(state, frame, 4294964754, 513)\nframe = _duel_menu_byte_bit_fields(state, frame, 4294964132, 6, True)\nreturn _command_policy_call_fields(state, frame, 41294, 203274)"}})

DECLARATIONS.update({'remove_command_member_queue_reference_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 204602)\nframe = first_replace(frame, roster=state.table_at(4294965034).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\nwhile True:\n    value = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _movement_compare(state, frame, low16(frame.target_x), value, 16)\n    if frame.status & 4:\n        break\nwhile True:\n    value = frame.roster.word()\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, value, -4)\n    if frame.status & 8:\n        return frame"}})

DECLARATIONS.update({'remove_scenario_selected_force_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 421074)\nframe = _movement_move(state, frame, 'target_x', state.read(4294963120, 2), 16)\nfor address in (4294964858, 4294964860, 4294964862):\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)\n    if frame.status & 4:\n        frame = _command_policy_store_word_fields(state, frame, address, 128)\n        break\nremaining = False\nfor address in (4294964859, 4294964861, 4294964863):\n    frame = _movement_test(state, frame, state.read(address, 1), 8)\n    if not frame.status & 8:\n        remaining = True\n        break\nstatus = frame.status | 1 if remaining else frame.status & 30\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)"}})

DECLARATIONS.update({'replace_command_city_head_queue_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 204542)\nframe = first_replace(frame, roster=state.table_at(4294964318).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964134, 2), 16)\nif not frame.status & 4:\n    return frame\nframe = first_replace(frame, roster=state.table_at(4294965034).cursor(), candidates=state.table_at(4294964480).cursor())\nwhile True:\n    frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if frame.status & 8:\n        break\n    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964134, 2), 16)\n    if frame.status & 4:\n        continue\n    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))\n    frame = first_replace(frame, candidates=frame.candidates.advance(2))\nframe = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nreturn _command_policy_call_fields(state, frame, 57846, 204600)"}})

