DECLARATIONS.update({'select_command_city_order_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203916)\nframe = first_replace(frame, roster=state.table_at(4294959900).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x), 2), 16)\nframe = _movement_compare(state, frame, low16(frame.target_y), 50, 16)\nimprove = bool(frame.status & 5)\nif not improve:\n    frame = _movement_compare(state, frame, low16(frame.target_y), 66, 16)\n    if frame.status & 1:\n        frame = _command_policy_call_fields(state, frame, 33748, 203952)\n        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\n        frame = _movement_compare(state, frame, low16(frame.target_x), 5, 16)\n        improve = bool(frame.status & 1)\nreturn _command_policy_store_word_fields(state, frame, 4294965032, 11 if improve else 6)"}})

DECLARATIONS.update({'select_command_loyalty_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203626)\nframe = _command_policy_call_fields(state, frame, 203686, 203630)\nframe = _movement_compare(state, frame, low16(frame.target_y), 50, 16)\nrecovery = bool(frame.status & 5)\nif not recovery:\n    frame = _movement_compare(state, frame, low16(frame.target_y), 71, 16)\n    if frame.status & 1:\n        frame = _command_policy_call_fields(state, frame, 33748, 203652)\n        frame = _movement_move(state, frame, 'target_x', state.read(4294964764, 2), 16)\n        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)\n        frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)\n        recovery = bool(frame.status & 1)\nreturn _command_policy_store_word_fields(state, frame, 4294965032, 9 if recovery else 4)"}})

DECLARATIONS.update({'select_command_population_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203330)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _command_policy_call_fields(state, frame, 203376, 203338)\nframe = _movement_test(state, frame, low16(frame.offset_x), 16)\naction = 2\nif not frame.status & 8:\n    frame = _movement_move(state, frame, 'unit', state.read(4294964068, 2), 16)\n    frame = _command_policy_call_fields(state, frame, 203446, 203352)\n    frame = _first_compare_long(frame, frame.distance, frame.target_y)\n    state.sr = state.sr & 65504 | frame.status\n    action = 3 if frame.status & 1 else 2\nreturn _command_policy_store_word_fields(state, frame, 4294965032, action)"}})

