DECLARATIONS.update({'select_command_recruitment_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 203982)\nframe = _command_policy_call_fields(state, frame, 33748, 203988)\nframe = _command_policy_call_fields(state, frame, 204110, 203992)\nframe = _command_policy_call_fields(state, frame, 204140, 203996)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964764, 2), 16)\nframe = _movement_move_long(state, frame, 'offset_x', frame.distance)\nframe = _special_action_shift_long(state, frame, 'offset_x', 1)\nframe = _first_compare_long(frame, frame.count, frame.offset_x)\nstate.sr = state.sr & 65504 | frame.status\nrecruit = True\nif not frame.status & 1:\n    frame = _movement_arithmetic_long(state, frame, 'offset_x', frame.distance)\n    frame = _first_compare_long(frame, frame.count, frame.offset_x)\n    state.sr = state.sr & 65504 | frame.status\n    if frame.status & 1:\n        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\n        frame = _movement_compare(state, frame, low16(frame.target_x), 7, 16)\n        recruit = not bool(frame.status & 4)\n    else:\n        frame = _special_action_shift_long(state, frame, 'distance', 1)\n        frame = _movement_arithmetic_long(state, frame, 'offset_x', frame.distance)\n        frame = _first_compare_long(frame, frame.count, frame.offset_x)\n        state.sr = state.sr & 65504 | frame.status\n        if frame.status & 1:\n            frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\n            frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)\n            recruit = bool(frame.status & 1)\n        else:\n            frame = _special_action_shift_long(state, frame, 'offset_x', 1)\n            frame = _first_compare_long(frame, frame.count, frame.offset_x)\n            state.sr = state.sr & 65504 | frame.status\n            if frame.status & 1:\n                frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 0)\n                recruit = not bool(frame.status & 4)\n            else:\n                frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\n                frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)\n                recruit = bool(frame.status & 1)\nreturn _command_policy_store_word_fields(state, frame, 4294965032, 12 if recruit else 7)"}})

DECLARATIONS.update({'select_command_supply_action_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 204190)\nframe = _command_policy_call_fields(state, frame, 204268, 204194)\nframe = first_replace(frame, roster=state.table_at(4294959260).cursor())\nframe = _movement_move(state, frame, 'unit', state.read(4294964068, 2), 16)\nframe = _movement_fixed_shift_word(state, frame, 'unit', 2)\nframe = _movement_move_long(state, frame, 'unit', frame.roster.long(low16(frame.unit)))\nframe = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)\nframe = _movement_move_long(state, frame, 'target_y', frame.target_x)\nframe = _special_action_shift_long(state, frame, 'target_x', 1)\nframe = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\nframe = _first_compare_long(frame, frame.unit, frame.target_x)\nstate.sr = state.sr & 65504 | frame.status\nsupply = bool(frame.status & 1)\nif not supply:\n    frame = _special_action_shift_long(state, frame, 'target_y', 2)\n    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)\n    frame = _first_compare_long(frame, frame.unit, frame.target_x)\n    state.sr = state.sr & 65504 | frame.status\n    if frame.status & 1:\n        frame = _command_policy_call_fields(state, frame, 33748, 204242)\n        frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 1)\n        supply = bool(frame.status & 4)\nreturn _command_policy_store_word_fields(state, frame, 4294965032, 14 if supply else 13)"}})

