DECLARATIONS.update({'step_command_choice_cursor_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _resource_cost_frame(state, frame, 201842)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif frame.status & 4:\n    return _command_policy_store_word_fields(state, frame, 4294964744, 1)\nframe = _command_policy_change_memory_fields(state, frame, 4294964744, -1)\nif not frame.status & 4:\n    return frame\nframe = _command_policy_store_word_fields(state, frame, 4294964744, 12)\nframe = _command_policy_register_bit_fields(state, frame, frame.target_x, 1)\nif frame.status & 4:\n    frame = _movement_test(state, frame, state.read(4294965008, 2), 16)\n    if not frame.status & 4:\n        frame = _command_policy_change_memory_fields(state, frame, 4294965008, -1)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294965008, 2), 2, 16)\n    if frame.status & 1:\n        frame = _command_policy_change_memory_fields(state, frame, 4294965008, 1)\nreturn frame"}})

