DECLARATIONS.update({'_assign_command_project_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, second_slot: bool', 'returns': 'FirstDeploymentFrame', 'flow': "if type(second_slot) is not bool:\n    raise ValueError('actual assignment slot required')\nchoice_target, choice_return, amount_target, amount_return, relation_return = (205632, 205556, 205678, 205570, 205596) if second_slot else (205408, 205332, 205468, 205346, 205372)\nframe = _command_policy_call_fields(state, frame, choice_target, choice_return)\nframe = _movement_test(state, frame, low16(frame.target_y), 16)\nif not frame.status & 8:\n    frame = _command_policy_store_word_fields(state, frame, 4294964134, low16(frame.target_y))\n    frame = _command_policy_call_fields(state, frame, amount_target, amount_return)\n    frame = _movement_test_long(state, frame, state.read(4294964126, 4))\n    if not frame.status & 4:\n        frame = first_replace(frame, roster=state.table_at(4294954240).cursor())\n        frame = _movement_move(state, frame, 'target_x', state.read(4294964134, 2), 16)\n        state.write(frame.roster.address(low16(frame.target_x)), 1, 1)\n        frame = _movement_test(state, frame, 1, 8)\n        frame = _command_policy_call_fields(state, frame, 204960, relation_return)\n        frame = first_replace(frame, roster=state.table_at(4294961164).cursor())\n        frame = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\n        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)\n        frame = _movement_add_word(state, frame, 'target_x', state.read(4294964068, 2))\n        frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)\n        displacement = 0 if second_slot else 4\n        frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), state.read(4294964134, 2), displacement=displacement)\n        frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), state.read(4294964128, 2), displacement=displacement + 2)\nreturn _command_detail_finish_fields(state, frame, 7 if second_slot else 6)"}})

