DECLARATIONS.update({'_command_detail_dispatch_menu_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, table_address: int, call_base: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "if (table_address, call_base, continuation) not in ((206210, 206226, 206206), (208984, 209006, 208980)):\n    raise ValueError('actual command menu dispatch geometry required')\nwhile True:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294965032, 2), 16)\n    if frame.status & 8:\n        return frame\n    frame = _movement_adjust_word(state, frame, 'target_x', -1)\n    frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)\n    frame = _movement_move(state, frame, 'target_x', state.table_at(table_address).word(low16(frame.target_x)), 16)\n    frame = _command_policy_call_fields(state, frame, u32(call_base + s16(low16(frame.target_x))), continuation)"}})

