DECLARATIONS.update({'_commit_retreat_target_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, origin: int', 'returns': 'FirstDeploymentFrame', 'flow': "profiles = {141288: (141402, 141428, 141442, 141456), 141830: (141944, 141970, 141984, 141998), 142166: (142304, 142330, 142344, 142358), 142882: (143016, 143042, 143056, 143070), 143116: (143250, 143276, 143290, 143304)}\nif origin not in profiles:\n    raise ValueError('actual retreat packet variant required')\nmap_return, terrain_return, city_return, duel_return = profiles[origin]\nframe = first_replace(frame, roster=state.table_at(16722944).cursor())\nframe = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)\nframe = _continuation_shift_word_fields(state, frame, 'target_y', 2)\nframe = _continuation_shift_word_fields(state, frame, 'distance', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_y), low16(frame.distance))\nframe = _continuation_shift_word_fields(state, frame, 'target_x', 7, True)\nframe = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_y), low16(frame.target_x), displacement=2)\nframe = first_replace(frame, roster=state.table_at(4294946344).cursor())\nframe = _settlement_write_byte_fields(state, frame, frame.roster, value=1, offset=low16(frame.choice))\nframe = _command_policy_call_fields(state, frame, 107576, map_return)\nframe = first_replace(frame, candidates=state.table_at(4294943056).cursor())\nframe = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)\nframe = _continuation_shift_word_fields(state, frame, 'target_x', 2)\nframe = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)\nframe = _continuation_shift_word_fields(state, frame, 'target_y', 7, True)\nframe = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)\nframe = _continuation_shift_word_fields(state, frame, 'unit', 7, True)\nframe = _command_policy_call_fields(state, frame, 107598, terrain_return)\nframe = _movement_compare(state, frame, low8(frame.target_x), 6, 8)\nif not frame.status & 4:\n    return _command_policy_call_fields(state, frame, 122026, city_return)\nframe = _command_policy_store_word_fields(state, frame, 4294964134, low16(frame.choice))\nreturn _command_policy_call_fields(state, frame, 121724, duel_return)"}})

