DECLARATIONS.update({'_update_retreat_position_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, origin: int', 'returns': 'FirstDeploymentFrame', 'flow': "profiles = {141288: (141348, 141356, 141688, 141364, False), 141830: (141890, 141898, 142118, 141906, True), 142166: (142250, 142258, 142456, 142266, False), 142882: (142962, 142970, 143072, 142978, True), 143116: (143196, 143204, 142118, 143212, True)}\nif origin not in profiles:\n    raise ValueError('actual complete retreat update entry required')\nside_return, sample_return, fallback_target, fallback_return, second_side = profiles[origin]\nfor carrier, address in (('roster', 4294944340), ('roster', 16727234), ('candidates', 16727490)):\n    frame = first_replace(frame, **{carrier: state.table_at(address).cursor()})\n    frame = _movement_test(state, frame, (frame.roster if carrier == 'roster' else frame.candidates).byte(low16(frame.choice)), 8)\n    if not frame.status & 4:\n        return frame\ndirect_sample = True\nif origin in (142166, 142882, 143116):\n    first_return = {142166: 142210, 142882: 142926, 143116: 143160}[origin]\n    frame = _command_policy_call_fields(state, frame, 142360, first_return)\n    if frame.status & 1:\n        if origin == 142166:\n            frame = _command_policy_store_word_fields(state, frame, 4294964134, low16(frame.count))\n        contact_return = {142166: 142222, 142882: 142934, 143116: 143168}[origin]\n        frame = _command_policy_call_fields(state, frame, 142470, contact_return)\n        if frame.status & 1:\n            return frame\n        direct_sample = False\nif direct_sample:\n    frame = first_replace(frame, roster=state.table_at(4294943056).cursor())\n    frame = _movement_move(state, frame, 'offset_y', low16(frame.choice), 16)\n    frame = _continuation_shift_word_fields(state, frame, 'offset_y', 2)\n    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.offset_y)), 16)\n    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.offset_y), 2), 16)\n    frame = _command_policy_call_fields(state, frame, 141458, side_return)\n    failed = bool(frame.status & 1)\n    if not failed:\n        frame = _command_policy_call_fields(state, frame, 142000 if second_side else 141570, sample_return)\n        failed = bool(frame.status & 1)\n    if failed:\n        frame = _command_policy_call_fields(state, frame, fallback_target, fallback_return)\nreturn _commit_retreat_target_fields(state, frame, origin)"}})

