DECLARATIONS.update({'_constrain_retreat_fallback_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, entry: int', 'returns': 'FirstDeploymentFrame', 'flow': "continuations = {142118: 142130, 142456: 142464, 143072: 143080}\nif entry not in continuations:\n    raise ValueError('an actual retreat coordinate fallback entry is required')\nframe = _resource_cost_frame(state, frame, entry)\nif entry == 142118:\n    frame = _movement_move(state, frame, 'distance', low16(frame.unit), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)\nelse:\n    frame = _movement_move(state, frame, 'target_x', low16(frame.unit), 16)\n    frame = _movement_move(state, frame, 'target_y', low16(frame.count), 16)\nframe = _command_policy_call_fields(state, frame, 143768, continuations[entry])\nframe = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)\nreturn _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)"}, 'constrain_transposed_retreat_coordinate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _constrain_retreat_fallback_fields(state, frame, 142118)'}, 'constrain_contact_retreat_coordinate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _constrain_retreat_fallback_fields(state, frame, 142456)'}, 'constrain_second_contact_retreat_coordinate_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'return _constrain_retreat_fallback_fields(state, frame, 143072)'}})
